  ui_story_5017_50170101_32_dialog_content = "그렇겠지. 편지엔 <color=#FFB400>「개인적인 부탁」</color>이 있다고 적혀 있었어.",
  ui_story_5017_50170101_33_dialog_content = "널 만나고 싶대.",
