  ui_story_5017_50170101_40_dialog_content = "투덜대지 말고. 이 방이야.",
  ui_story_5017_50170101_41_dialog_content = "실례합니다──",
  ui_story_5017_50170101_42_dialog_content = "네네~!",
  ui_story_5017_50170101_43_dialog_content = "우와, 전설의 아이테르가 이렇게 생겼구나!",
  ui_story_5017_50170101_44_dialog_content = "얼굴도 꽤 귀엽잖아? 우와, 꼬리도 있어!",
  ui_story_5017_50170101_45_dialog_content = "저기...",
  ui_story_5017_50170101_46_dialog_content = "아이테르는 이쪽이야...",
  ui_story_5017_50170101_47_dialog_content = "응... 내가 아이테르야...",
  ui_story_5017_50170101_48_dialog_content = "아앗──?!",
  ui_story_5017_50170101_49_dialog_content = "평범하네.",
  ui_story_5017_50170101_50_dialog_content = "야! 그렇게 실망하지 않아도 되잖아!",
  ui_story_5017_50170101_51_dialog_content = "자, 자. 일단 앉아. 먹으면서 얘기하자.",
  ui_story_5017_50170101_52_dialog_content = "그럼 소개할게. 난 <color=#FFB400>「요우」</color>라고 해.",
  ui_story_5017_50170101_53_dialog_content = "이번에 내가 린 가문 상회에 부탁한 건 전설의 아이테르, 널 만나고 싶어서야.",
  ui_story_5017_50170101_54_dialog_content = "왜 날 찾은 건데?",
  ui_story_5017_50170101_55_dialog_content = "아이테르는 사람의 마음을 들여다보고, 그 의식을 왜곡하고,\n심지어는 타인의 기억을 읽을 수도 있다고 들었어...",
  ui_story_5017_50170101_56_dialog_content = "정말이야?",
  ui_story_5017_50170101_57_dialog_content = "음... 그렇게 말하니까 되게 무섭게 느껴지긴 하지만, 사실이야.",
  ui_story_5017_50170101_58_dialog_content = "그거 다행이네!",
  ui_story_5017_50170101_59_dialog_content = "부탁할 일이 있어!",
  ui_story_5017_50170101_60_dialog_content = "이렇게 갑자기?",
