  ui_story_5017_50170101_62_dialog_content = "뭐?! 그건 또 무슨 무서운 부탁이냐고...",
  ui_story_5017_50170101_63_dialog_content = "내 <color=#FFB400>잃어버린 기억</color>을 찾는 걸 네가 도와줬으면 해.",
  ui_story_5017_50170101_64_dialog_content = "어라...",
  ui_story_5017_50170101_65_dialog_content = "너... 기억을 잃었어?",
  ui_story_5017_50170101_66_dialog_content = "음... 뭐랄까...",
  ui_story_5017_50170101_67_dialog_content = "어렸을 때 기억이 하나도 안 나.",
  ui_story_5017_50170101_68_dialog_content = "다들 「어린 시절의 추억」은 아름답다고 하잖아.\n그래서 나도 그때의 기억을 되찾고 싶었어.",
  ui_story_5017_50170101_69_dialog_content = "그래서 의사한테도 가 봤고, 이런저런 약도 먹어 봤지만, 전부 효과가 없었어.",
  ui_story_5017_50170101_70_dialog_content = "원래는 포기하려고 했어. 그래봤자 기억일 뿐이잖아.\n앞으로 더 많은 추억을 만들면 그만이지.",
  ui_story_5017_50170101_71_dialog_content = "근데 얼마 전부터 자꾸... 이상하게 심장이 뛰기 시작했어.",
  ui_story_5017_50170101_72_dialog_content = "심장이 뛰어?",
  ui_story_5017_50170101_73_dialog_content = "응, 그리고 불안한 마음도 들고.",
  ui_story_5017_50170101_74_dialog_content = "왜 그런지는 모르겠지만, 이건 어쩌면 잃어버린 기억과 관계가 있을지도 몰라!",
  ui_story_5017_50170101_75_dialog_content = "이런 걸... 뭐라고 하더라...",
  ui_story_5017_50170101_76_dialog_content = "직감?",
  ui_story_5017_50170101_77_dialog_content = "맞아! 직감!",
  ui_story_5017_50170101_78_dialog_content = "그래서 난 모든 일을 제쳐두고 기억을 찾는 데 전념하기로 결심했어.",
