  ui_story_5017_50170101_80_dialog_content = "할 수 있는 걸 전부 시도해 봤지만, 전혀 진전이 없었거든.",
  ui_story_5017_50170101_81_dialog_content = "그러다가 마지막에 누가 나한테 말해줬던 거야.\n세상 마지막 「아이테르」의 생존자를 찾아가 보라고!",
  ui_story_5017_50170101_82_dialog_content = "나?",
  ui_story_5017_50170101_83_dialog_content = "그래.",
  ui_story_5017_50170101_84_dialog_content = "넌 내 마지막 희망이야!",
  ui_story_5017_50170101_85_dialog_content = "어때? 도와줄래?",
  ui_story_5017_50170101_86_dialog_content = "기억을 되찾는 일 같은 건 나도 할 수 있을지 장담은 못 해...",
