  ui_story_5017_50170101_88_dialog_content = "근데 「기억」보다 더 소중한 물건이 뭐가 있을지 모르겠어서...",
  ui_story_5017_50170101_89_dialog_content = "내가 가진 건 「나이티움」뿐인데, 그걸로 괜찮을까?",
  ui_story_5017_50170101_90_dialog_content = "「나이티움」?",
  ui_story_5017_50170101_91_dialog_content = "혹시 얼마나 줄 건지 물어봐도 될까?",
  ui_story_5017_50170101_92_dialog_content = "앗, 난 산수를 잘 못하거든. 그래서 잘은 모르겠지만...",
