  ui_story_5017_50170101_128_dialog_content = "어라? 전부 돈이잖아?",
  ui_story_5017_50170101_129_dialog_content = "(돈을 이렇게도 쉽게 벌 수 있었던 거야?!)",
  ui_story_5017_50170101_130_dialog_content = "(이 녀석 기억... 보면 볼수록 화가 난단 말이지...)",
