  ui_story_5017_50170101_139_dialog_content = "(이게 요우의 가장 오래된 기억인가?)",
  ui_story_5017_50170101_140_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5017_50170101_141_dialog_content = "(아니야. 더 오래된 기억이 있어!)",
