  ui_story_5017_50170101_143_dialog_content = "(마음을 가라앉히자...)",
  ui_story_5017_50170101_144_dialog_content = "(정신을 집중해...)",
  ui_story_5017_50170101_145_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170101_146_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170101_147_dialog_content = "<color=#e8d9bb>딸랑, 딸랑──</color>",
  ui_story_5017_50170101_148_dialog_content = "<color=#e8d9bb>딸랑, 딸랑──</color>",
  ui_story_5017_50170101_149_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5017_50170101_150_dialog_content = "(방금 그건...)",
  ui_story_5017_50170101_151_dialog_content = "(방울 소리?)",
  ui_story_5017_50170101_152_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5017_50170101_153_dialog_content = "어때, 어때?",
  ui_story_5017_50170101_154_dialog_content = "신기한 아이테르, 내 기억은 찾았어?",
  ui_story_5017_50170101_155_dialog_content = "미안... 네가 가진 가장 오래된 기억엔 온통 바다밖에 없었어...",
  ui_story_5017_50170101_156_dialog_content = "그렇구나...",
  ui_story_5017_50170101_157_dialog_content = "네가 본 게 맞아. 그게 내 기억의 시작이야.",
  ui_story_5017_50170101_158_dialog_content = "바다에서 눈을 떴을 때, 난 내 이름 말고는 아무것도 기억 못 했어.",
  ui_story_5017_50170101_159_dialog_content = "참, 그때 난 어선에 타고 있었어.",
  ui_story_5017_50170101_160_dialog_content = "내 고향이 <color=#FFB400>「운도」</color>라는 것도 선원한테 듣고 나서야 알았고 말이야.",
  ui_story_5017_50170101_161_dialog_content = "운도라면... 혹시 운산?",
  ui_story_5017_50170101_162_dialog_content = "맞아, 운산이 있는 섬이 바로 「운도」야.",
  ui_story_5017_50170101_163_dialog_content = "근데 난 「운도」라는 이름에도 아무런 인상이 없었어.",
  ui_story_5017_50170101_164_dialog_content = "이 세상 모든 게 나한테는 낯설고 아무 상관도 없는 듯한 기분이라고 할까.",
  ui_story_5017_50170101_165_dialog_content = "유일하게 나와 세상을 이어주는 연결고리는 이거 하나뿐이었어.",
  ui_story_5017_50170101_166_dialog_content = "이건...",
  ui_story_5017_50170101_167_dialog_content = "<color=#FFB400>옥</color>인가?",
  ui_story_5017_50170101_168_dialog_content = "응.",
  ui_story_5017_50170101_169_dialog_content = "눈을 떴을 때 가지고 있었던 거야.",
  ui_story_5017_50170101_170_dialog_content = "누구 건지도, 왜 내가 이걸 가지고 있었는지도 몰라.",
  ui_story_5017_50170101_171_dialog_content = "근데 이걸 쥐고 있으면... 항상 따뜻한 느낌이 들어.\n마치 만나본 적이 없는 사람과 마음이 통하는 것처럼 말이야.",
  ui_story_5017_50170101_172_dialog_content = "그렇구나. 그럼 어쩌면 그건 네가 아는 사람이 남겨준 걸지도 몰라!",
  ui_story_5017_50170101_173_dialog_content = "근데 난 이 옥에 대한 기억도 전혀 없는걸!",
  ui_story_5017_50170101_174_dialog_content = "어때? 바다 말고 또 다른 건 못 봤어?",
  ui_story_5017_50170101_175_dialog_content = "방울 소리가 들렸어.",
  ui_story_5017_50170101_176_dialog_content = "방울 소리?",
  ui_story_5017_50170101_177_dialog_content = "응, 방울 아니면 풍경 같은 거겠지. 일정한 리듬으로 울렸어.",
  ui_story_5017_50170101_178_dialog_content = "대충 이런 느낌이랄까... 크흠!",
  ui_story_5017_50170101_179_dialog_content = "딸랑── 딸랑── 딸랑, 딸랑!",
  ui_story_5017_50170101_180_dialog_content = "......",
  ui_story_5017_50170101_181_dialog_content = "......",
  ui_story_5017_50170101_182_dialog_content = "...뭔가 떠오르는 거 없어?",
  ui_story_5017_50170101_183_dialog_content = "기차가 생각났어.",
  ui_story_5017_50170101_184_dialog_content = "난 부엌이 생각났어.",
  ui_story_5017_50170101_185_dialog_content = "미안! 역시 이런 건 잘 못해서...",
  ui_story_5017_50170101_186_dialog_content = "그럼 요우는 그 뒤로 「운도」에 돌아간 적 있어?",
  ui_story_5017_50170101_187_dialog_content = "아니...",
  ui_story_5017_50170101_188_dialog_content = "사실 조금 망설이고 있거든.",
  ui_story_5017_50170101_189_dialog_content = "뭘 망설이는 건데?",
  ui_story_5017_50170101_190_dialog_content = "그 섬 사람들은 어쩌면 정말로 날 알고 있을지도 몰라.",
  ui_story_5017_50170101_191_dialog_content = "친구나 가족, 그리고 어쩌면 나한테 얻어맞은 사람도 있겠지...",
  ui_story_5017_50170101_192_dialog_content = "(전부 가능성은 충분히 있겠네!)",
  ui_story_5017_50170101_193_dialog_content = "근데 난 전혀 기억을 못 하잖아...",
  ui_story_5017_50170101_194_dialog_content = "그럼 난 그 사람들을 어떻게 대해야 할까...",
  ui_story_5017_50170101_195_dialog_content = "그랬구나.",
  ui_story_5017_50170101_196_dialog_content = "그 기분은 알 것 같아. 그래도...",
  ui_story_5017_50170101_197_dialog_content = "그 사람들 얘길 들으면 기억을 되찾을 수도 있잖아, 안 그래?",
  ui_story_5017_50170101_198_dialog_content = "난 뭔가 잊었을 때, 관계가 있는 물건을 보고 다시 생각이 나는 경우가 많아.",
  ui_story_5017_50170101_199_dialog_content = "요우 네 상황이랑 비교하긴 힘들겠지만, 그래도 어느 정도는 같은 원리라고 생각해.",
  ui_story_5017_50170101_200_dialog_content = "으아... 모르겠다아! 그럼... 역시 가 보는 편이 좋을까나...?",
  ui_story_5017_50170101_201_dialog_content = "당연히 가 봐야지!",
  ui_story_5017_50170101_202_dialog_content = "기억을 되찾는 걸 돕겠다고 약속했으니까, 우린 반드시 해낼 거야!",
  ui_story_5017_50170101_203_dialog_content = "지금 바로 운도로 가자!",
  ui_story_5017_50170101_204_dialog_content = "뭐?! 정말?",
  ui_story_5017_50170101_205_dialog_content = "지금 당장?",
  ui_story_5017_50170101_206_dialog_content = "그래, 지금 당장!",
  ui_story_5017_50170101_207_dialog_content = "(보수도 받아야 하니까, 끝까지 해내고 말겠어!)",
  ui_story_5017_50170101_208_dialog_content = "근데 운도는 엄청 멀다구!",
  ui_story_5017_50170101_209_dialog_content = "일단 대륙 동쪽 끝까지 가고, 다시 배로 바다를 건너서...",
  ui_story_5017_50170101_210_dialog_content = "괜찮아. 나한테 맡겨!",
  ui_story_5017_50170101_211_dialog_content = "전설 속 아이테르의 능력은 사람의 마음을 들여다보는 게 다가 아니거든!",
  ui_story_5017_50170201_1_dialog_content = "「붉은 꽃 꺾어 님에게 주니──」",
  ui_story_5017_50170201_2_dialog_content = "「꽃잎은 옥설 위에 떨어지네.」",
  ui_story_5017_50170201_3_dialog_content = "<color=#e8d9bb>───</color>",
  ui_story_5017_50170201_4_dialog_content = "!",
  ui_story_5017_50170201_5_dialog_content = "일어났구나, 요우.",
  ui_story_5017_50170201_6_dialog_content = "우리...",
  ui_story_5017_50170201_7_dialog_content = "거의 다 온 거지?",
  ui_story_5017_50170201_8_dialog_content = "응! 저 앞이 바로 운도일 거야!",
  ui_story_5017_50170201_9_dialog_content = "근데 넌 어떻게 알았어?",
  ui_story_5017_50170201_10_dialog_content = "그건... 뭐라 설명하긴 힘든데...",
  ui_story_5017_50170201_11_dialog_content = "아무튼 알 수 있어!",
  ui_story_5017_50170201_12_dialog_content = "그렇구나, 또 「직감」인 모양이네.",
  ui_story_5017_50170201_13_dialog_content = "그나저나... 음...",
  ui_story_5017_50170201_14_dialog_content = "「스카이워커호」의 속도에 전혀 놀라질 않다니 의외네.",
  ui_story_5017_50170201_15_dialog_content = "......",
  ui_story_5017_50170201_16_dialog_content = "우와! 이렇게 빨리 도착했어! 「스카이워커호」 정말 대단해!",
  ui_story_5017_50170201_17_dialog_content = "그렇게 어색하게 놀랄 것까지야...",
  ui_story_5017_50170201_18_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_5017_50170201_19_dialog_content = "뭐지?!",
  ui_story_5017_50170201_20_dialog_content = "무슨 일이야?!",
  ui_story_5017_50170201_21_dialog_content = "<color=#e8d9bb>쿠우웅──</color>",
  ui_story_5017_50170201_22_dialog_content = "우와... 지금 내려가는 거야?",
  ui_story_5017_50170201_23_dialog_content = "내려가는 건 맞는데... 우리가 한 게 아니야...",
  ui_story_5017_50170201_24_dialog_content = "어떻게 된 거야?! PlayerName!",
  ui_story_5017_50170201_25_dialog_content = "갑자기 「스카이워커호」를 제어할 수가 없어!",
  ui_story_5017_50170201_26_dialog_content = "나도 모르겠어!",
  ui_story_5017_50170201_27_dialog_content = "주변에 무슨 문제가 생겼나?",
  ui_story_5017_50170201_28_dialog_content = "아무 이상도 안 느껴져. 주변 상황은 정상이야...",
  ui_story_5017_50170201_29_dialog_content = "알겠어. 그럼 일단 착륙 준비부터 하자...",
  ui_story_5017_50170201_30_dialog_content = "준비?! 어떻게 준비하는데?",
  ui_story_5017_50170201_31_dialog_content = "어디든 되는대로 꽉 잡고 있어!",
  ui_story_5017_50170201_32_dialog_content = "괜찮아. 「스카이워커호」는 불시착 경험이 많으니까!",
  ui_story_5017_50170201_33_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_5017_50170201_34_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5017_50170201_35_dialog_content = "콜록콜록... 콜록...",
  ui_story_5017_50170201_36_dialog_content = "머리가 어지러워... 다들 괜찮아?",
  ui_story_5017_50170201_37_dialog_content = "휴우~ 공기가 상쾌하네!",
  ui_story_5017_50170201_38_dialog_content = "이번 착륙은 저번보다 훨씬 안정적이었어!",
  ui_story_5017_50170201_39_dialog_content = "너흰... 아무렇지도 않아?",
  ui_story_5017_50170201_40_dialog_content = "기껏해야 불시착인걸. 이런 일은 전에도 얼마든지 있었으니까.",
  ui_story_5017_50170201_41_dialog_content = "...정말 대단해, 존경스러워!",
  ui_story_5017_50170201_42_dialog_content = "얼른 봐. 여기가 네 고향이야!",
  ui_story_5017_50170201_43_dialog_content = "익숙한 느낌이 들어?",
  ui_story_5017_50170201_44_dialog_content = "저 분홍색 꽃들이 「벚꽃」 맞지?",
  ui_story_5017_50170201_45_dialog_content = "정말 예뻐... 꼭 눈꽃이 타오르는 것 같네.",
  ui_story_5017_50170201_46_dialog_content = "맞아, 맞아! 뭐 생각나는 거 있어?",
  ui_story_5017_50170201_47_dialog_content = "벚꽃... 본 적 있는 것 같아...",
  ui_story_5017_50170201_48_dialog_content = "그래! 분명히 본 적 있을 거야!",
  ui_story_5017_50170201_49_dialog_content = "계속 떠올려 봐. 어디서 봤는데?",
  ui_story_5017_50170201_50_dialog_content = "......",
  ui_story_5017_50170201_51_dialog_content = "............",
  ui_story_5017_50170201_52_dialog_content = "책에서 봤어.",
  ui_story_5017_50170201_53_dialog_content = "뭐?",
  ui_story_5017_50170201_54_dialog_content = "책에서 읽은 적 있어. 벚꽃은 운도의 명물이지?",
  ui_story_5017_50170201_55_dialog_content = "그건 맞아. 근데...",
  ui_story_5017_50170201_56_dialog_content = "그거 말고는 정말 기억이 안 나?",
  ui_story_5017_50170201_57_dialog_content = "전혀!",
  ui_story_5017_50170201_58_dialog_content = "......",
  ui_story_5017_50170201_59_dialog_content = "생각 안 할래. 머리 아파!",
  ui_story_5017_50170201_60_dialog_content = "이런 멋진 풍경이 눈앞에 있는데 머리나 쓰고 있으면 시간이 아깝잖아!",
  ui_story_5017_50170201_61_dialog_content = "그것도 그렇네... 내가 너무 조급했어...",
  ui_story_5017_50170201_62_dialog_content = "「스카이워커호」의 문제도 아직 단서가 없으니까, 일단은 여기서 복구하게 놔두자.",
  ui_story_5017_50170201_63_dialog_content = "우린 여길 둘러보는 게 좋겠어.",
  ui_story_5017_50170201_64_dialog_content = "현지인을 만날 수 있으면 이 섬에 대해 물어볼 수 있을 거야.",
  ui_story_5017_50170201_65_dialog_content = "현지인?",
  ui_story_5017_50170201_66_dialog_content = "여기 있잖아?",
  ui_story_5017_50170201_67_dialog_content = "누구?",
  ui_story_5017_50170201_68_dialog_content = "누구?",
  ui_story_5017_50170201_69_dialog_content = "나! 여긴 내 고향이잖아!",
  ui_story_5017_50170201_70_dialog_content = "으엑... 미안, 방금 했던 말 정정할게.",
  ui_story_5017_50170201_71_dialog_content = "「운도에 대해 잘 아는 현지인」을 만났으면 좋겠어.",
  ui_story_5017_50170201_72_dialog_content = "넌 여기 처음 와봤으니까 우리랑 다를 게 없잖아.",
  ui_story_5017_50170201_73_dialog_content = "후후, 그거야 모르는 일이지!",
  ui_story_5017_50170201_74_dialog_content = "「운도는 아스트라 대륙의 동쪽에 위치하며, 폭풍해 중부 도서군에 속하는 섬이다.」",
  ui_story_5017_50170201_75_dialog_content = "「섬의 지형은 험한 산지가 많고, 평원의 면적은 좁다.\n대부분 산악 및 구릉지대로 이루어져 있으며...」",
  ui_story_5017_50170201_76_dialog_content = "......",
  ui_story_5017_50170201_77_dialog_content = "PlayerName, 그러고 보니 우리 여기 오는 거 갑자기 결정했었지?",
  ui_story_5017_50170201_78_dialog_content = "맞아.",
  ui_story_5017_50170201_79_dialog_content = "그럼 아무런 준비도 안 했던 거네?",
  ui_story_5017_50170201_80_dialog_content = "그렇지.",
  ui_story_5017_50170201_81_dialog_content = "근데 왜 요우는 <color=#FFB400>「운도 여행 가이드북」</color> 같은 걸 가지고 있어?!",
  ui_story_5017_50170201_82_dialog_content = "후후, 난 이 가이드북을 항상 가지고 다니거든!",
  ui_story_5017_50170201_83_dialog_content = "운도엔 와본 적 없지만, 고향을 생각하는 내 마음을 무시하면 곤란해!",
  ui_story_5017_50170201_84_dialog_content = "그게 무슨 이상한 마음인데!",
  ui_story_5017_50170201_85_dialog_content = "아무튼 계속 읽어볼게.",
  ui_story_5017_50170201_86_dialog_content = "「운도의 지리적 특징은...」",
  ui_story_5017_50170201_87_dialog_content = "잠깐 스톱!",
  ui_story_5017_50170201_88_dialog_content = "지리 수업은 그걸로 됐고! 더 실용적인 정보는 없어?",
  ui_story_5017_50170201_89_dialog_content = "음... 내가 목차를 좀 볼게...",
  ui_story_5017_50170201_90_dialog_content = "이거 내용이 꽤 많네! 「운도의 소문」, 「계절 복장」, 「민간전승」, 「맛집 특집」...",
  ui_story_5017_50170201_91_dialog_content = "이거 정말 가이드북 맞아?",
  ui_story_5017_50170201_92_dialog_content = "당연하지! 표지 제목을 봐!",
  ui_story_5017_50170201_93_dialog_content = "아, 찾았어. 여기 「여행 시 주의사항」부터 읽어줘.",
  ui_story_5017_50170201_94_dialog_content = "알겠어.",
  ui_story_5017_50170201_95_dialog_content = "「운도의 경치는 그림처럼 아름답고, 일 년 내내 기후가 봄처럼 따스하다.\n온천욕을 하고 벚꽃을 감상하는 등 휴가지로 최적인 곳이다.」",
  ui_story_5017_50170201_96_dialog_content = "「가장 중요한 것은 이곳이 절대적으로 안전하다는 점이다.\n<color=#FFB400>운도에는 암귀가 한 마리도 존재하지 않는다</color>.」",
  ui_story_5017_50170201_97_dialog_content = "하긴, 이렇게 예쁜 곳에도 암귀가 있으면 정말 너무하잖아.",
  ui_story_5017_50170201_98_dialog_content = "맞아!",
  ui_story_5017_50170201_99_dialog_content = "그래도 여기 있는 동안은 암귀 소탕을 못 한다고 생각하니 조금 아쉬운걸.",
  ui_story_5017_50170201_100_dialog_content = "넌 평소에 대체 어떤 생활을 하고 있는 거야?!",
  ui_story_5017_50170201_101_dialog_content = "그럼 계속 읽을게.",
  ui_story_5017_50170201_102_dialog_content = "「운도의 주민은 해안가에 주로 거주하며, 항구를 따라 독특한 운치가 있는 도시...」",
  ui_story_5017_50170201_103_dialog_content = "「<color=#FFB400>강부성</color>을 건설했다.」",
  ui_story_5017_50170201_104_dialog_content = "오! 도시라니 잘됐네!",
  ui_story_5017_50170201_105_dialog_content = "거기 가면 단서를 찾기 더 쉬울지도 몰라.",
  ui_story_5017_50170201_106_dialog_content = "그리고 여기가 요우의 고향이라면 분명히 누군가 요우를 기억하고 있지 않을까?",
  ui_story_5017_50170201_107_dialog_content = "나도 그렇게 생각해!",
  ui_story_5017_50170201_108_dialog_content = "그럼 가자, 강부성으로!",
  ui_story_5017_50170201_109_dialog_content = "강부성으로!",
  ui_story_5017_50170201_110_dialog_content = "......",
  ui_story_5017_50170201_X110_dialog_content = "......",
  ui_story_5017_50170201_111_dialog_content = "그래서... 강부성이 어디 있는데?",
  ui_story_5017_50170201_112_dialog_content = "한참 걸었는데... 주변 풍경이 전혀 변하질 않았는데?",
  ui_story_5017_50170201_113_dialog_content = "그러게! 힘들어 죽겠네!",
  ui_story_5017_50170201_114_dialog_content = "쉬고 싶어... 강부성엔 분명히 맛있는 음식이 많을 거야...",
  ui_story_5017_50170201_115_dialog_content = "근데 문제는 이렇게 무작정 걸어도 언제 강부성에 도착할지 알 수 없다는 거야...",
  ui_story_5017_50170201_116_dialog_content = "어라? 저 앞에 사람이 있는 것 같은데?",
  ui_story_5017_50170201_117_dialog_content = "앗! 진짜다!",
  ui_story_5017_50170201_118_dialog_content = "저기! 내 말 들려?",
  ui_story_5017_50170201_119_dialog_content = "다행이네! 가서 길 물어보고 올게!",
  ui_story_5017_50170201_120_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5017_50170201_121_dialog_content = "실례합니다. 말씀 좀 물을게요――",
  ui_story_5017_50170201_122_dialog_content = "......",
  ui_story_5017_50170201_123_dialog_content = "저흰 여기 처음 온 관광객인데요. 강부성에 가려면 어느 쪽으로 가야 되죠?",
  ui_story_5017_50170201_124_dialog_content = "......",
  ui_story_5017_50170201_125_dialog_content = "어라... 저기요? 저흰 여기...",
  ui_story_5017_50170201_126_dialog_content = "으어어──",
  ui_story_5017_50170201_127_dialog_content = "그아아!",
  ui_story_5017_50170201_128_dialog_content = "뭐야?",
  ui_story_5017_50170201_129_dialog_content = "바이스! 조심해!",
  ui_story_5017_50170202_1_dialog_content = "끄억...",
  ui_story_5017_50170202_2_dialog_content = "기분 나쁜 괴물이네...",
  ui_story_5017_50170202_3_dialog_content = "운도엔 암귀가 없는 거 아니었어?",
  ui_story_5017_50170202_4_dialog_content = "왠지... 암귀는 아닌 것 같아...",
  ui_story_5017_50170202_5_dialog_content = "맞아...",
  ui_story_5017_50170202_6_dialog_content = "봐, 갑자기 사라져 버렸잖아.",
  ui_story_5017_50170202_7_dialog_content = "암귀가 아니면 대체 뭐지?",
  ui_story_5017_50170202_8_dialog_content = "방금 그 괴물들... 생김새나 행동이나...",
  ui_story_5017_50170202_9_dialog_content = "아무리 봐도 불길한 생각밖에 안 드는데...",
  ui_story_5017_50170202_10_dialog_content = "나도 그래...",
  ui_story_5017_50170202_11_dialog_content = "응?! 무슨 생각인데?",
  ui_story_5017_50170202_12_dialog_content = "「귀신」...",
  ui_story_5017_50170202_13_dialog_content = "야! 그런 얼굴로 무서운 소리하지 마!",
  ui_story_5017_50170202_14_dialog_content = "나... 방금 말도 걸었는데...",
  ui_story_5017_50170202_15_dialog_content = "에이, 그럴 리가 없잖아! 이 세상에 「귀신」 같은 게 어디 있어!",
  ui_story_5017_50170202_16_dialog_content = "진짜 있더라도 내가 한 방에 날려줄게!",
  ui_story_5017_50170202_17_dialog_content = "너, 넌 안 무서워?",
  ui_story_5017_50170202_18_dialog_content = "당연하지!",
  ui_story_5017_50170202_19_dialog_content = "날 이길 수 없는 녀석은 하나도 안 무서워!",
  ui_story_5017_50170202_20_dialog_content = "아무튼 조심하자. 여긴 생각보다 안전한 곳이 아닌 것 같아.",
  ui_story_5017_50170202_21_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_22_dialog_content = "무슨 소리지?!",
  ui_story_5017_50170202_23_dialog_content = "자꾸 호들갑 좀 떨지 마! 나까지 깜짝 놀랐잖아!",
  ui_story_5017_50170202_24_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_25_dialog_content = "숲 쪽에서 들리는 것 같아.",
  ui_story_5017_50170202_26_dialog_content = "잠깐만, 이거 설마...",
  ui_story_5017_50170202_27_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_28_dialog_content = "요우의 기억 속에서 들었던 그 소리야!",
  ui_story_5017_50170202_29_dialog_content = "요우! 너 혹시...",
  ui_story_5017_50170202_30_dialog_content = "이 소리... 나도 들어봤어!",
  ui_story_5017_50170202_31_dialog_content = "<color=#e8d9bb>딸랑, 딸랑──</color>",
  ui_story_5017_50170202_32_dialog_content = "확실해! 분명히 들어본 소리야!",
  ui_story_5017_50170202_33_dialog_content = "요우! 잠깐만!",
  ui_story_5017_50170202_34_dialog_content = "혼자 가 버리면 어떡해!",
  ui_story_5017_50170202_35_dialog_content = "숲속으로... 달려가 버렸어.",
  ui_story_5017_50170202_36_dialog_content = "얼른 따라가자!",
  ui_story_5017_50170202_37_dialog_content = "<color=#e8d9bb>딸랑────, 딸랑────</color>",
  ui_story_5017_50170202_38_dialog_content = "뭐가 저렇게 빨라?! 벌써 안 보이잖아...",
  ui_story_5017_50170202_39_dialog_content = "방울 소리가 나는 쪽으로 가면 될 거야!",
  ui_story_5017_50170202_40_dialog_content = "<color=#e8d9bb>스윽── 스윽──</color>",
  ui_story_5017_50170202_41_dialog_content = "방금 뭔가 이상한 소리 못 들었어...?",
  ui_story_5017_50170202_42_dialog_content = "몰라.",
  ui_story_5017_50170202_43_dialog_content = "무슨 대답이 그래?!",
  ui_story_5017_50170202_44_dialog_content = "어? 저기...",
  ui_story_5017_50170202_45_dialog_content = "난 아무 말도 안 했는데...",
  ui_story_5017_50170202_46_dialog_content = "히익!",
  ui_story_5017_50170202_47_dialog_content = "그으으...",
  ui_story_5017_50170202_48_dialog_content = "진정해! 바이스! 나 맞을 뻔했다고!",
  ui_story_5017_50170202_49_dialog_content = "빠, 빨리 가자. 요우를 놓치면 큰일이야!",
  ui_story_5017_50170202_50_dialog_content = "너무 빠르잖아!",
  ui_story_5017_50170202_51_dialog_content = "그렇게 빨리 가면 따라갈 수가 없다고!",
  ui_story_5017_50170202_52_dialog_content = "휴, 정말 손이 많이 간다니까.",
  ui_story_5017_50170202_53_dialog_content = "얌전히 있어!",
  ui_story_5017_50170202_54_dialog_content = "뭐?",
  ui_story_5017_50170202_55_dialog_content = "으잇──챠!",
  ui_story_5017_50170202_56_dialog_content = "으엑?! 자, 잠깐만!",
  ui_story_5017_50170202_57_dialog_content = "가, 갑자기 안아 들면 어쩌자는 거야?!",
  ui_story_5017_50170202_58_dialog_content = "지금 그런 거 따질 때가 아니잖아!",
  ui_story_5017_50170202_59_dialog_content = "얼른 가자!",
  ui_story_5017_50170202_60_dialog_content = "너 정말... 휴, 됐어.",
  ui_story_5017_50170202_61_dialog_content = "대신 한 가지만 충고할게.",
  ui_story_5017_50170202_62_dialog_content = "...절대 뒤돌아보지 마.",
  ui_story_5017_50170202_63_dialog_content = "이럴 때까지 겁주고 싶은 거야?!",
  ui_story_5017_50170202_64_dialog_content = "겁주려는 게 아냐. 진심 어린 충고라고...",
  ui_story_5017_50170202_65_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_66_dialog_content = "<color=#e8d9bb>딸랑────</color>",
  ui_story_5017_50170202_67_dialog_content = "거의 다 왔어!",
  ui_story_5017_50170202_68_dialog_content = "요우가 보여! 저기 있어!",
  ui_story_5017_50170202_69_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_70_dialog_content = "으앗! 요우 근처에도 괴물이 있잖아!",
  ui_story_5017_50170202_71_dialog_content = "왜 괴물을 안 날려버리는 거지?",
  ui_story_5017_50170202_72_dialog_content = "멍하니 서 있잖아!",
  ui_story_5017_50170202_73_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_74_dialog_content = "요우!",
  ui_story_5017_50170202_75_dialog_content = "요우──!",
  ui_story_5017_50170202_76_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5017_50170202_77_dialog_content = "「이제 음양을 읊노니, 이 곡조와 함께 그대의 혼은 피안으로 돌아가리라.」",
  ui_story_5017_50170202_78_dialog_content = "「삼도의 강물 아래에서 곡의 유생을 원망할지니.」",
  ui_story_5017_50170202_79_dialog_content = "「만다라가 부르나니, 금슬은 합하여 울레라.」",
  ui_story_5017_50170202_80_dialog_content = "(우린 자기도 모르게 모두 입을 다물어 버렸다.)",
  ui_story_5017_50170202_81_dialog_content = "(여자는 대나무숲 속에서 발끝으로 가볍게 땅을 차며,\n손에 든 방울을 쫓아가듯 춤을 추고 있었다.)",
  ui_story_5017_50170202_82_dialog_content = "(그 발걸음은 너무나도 가벼웠고, 들리는 것은 그저 방울 소리뿐.)",
  ui_story_5017_50170202_83_dialog_content = "(그 춤은 한 번도 본 적 없는 것이었고...)",
  ui_story_5017_50170202_84_dialog_content = "(모든 사람의 시선이 그녀에게 고정되어 있었다.)",
  ui_story_5017_50170202_85_dialog_content = "「듣는 이의 넋을 달래노니, 혼백이여 스러질지어다.」",
  ui_story_5017_50170202_86_dialog_content = "그것이 삶이든, 죽음이든 여할 것이니.",
  ui_story_5017_50170202_87_dialog_content = "그... 어억...",
  ui_story_5017_50170202_88_dialog_content = "이 춤, 나 본 적 있어...",
  ui_story_5017_50170202_89_dialog_content = "방울 소리, 춤, 그리고 괴물이 울부짖는 소리...",
  ui_story_5017_50170202_90_dialog_content = "(그래... 그러고 보니까 나도 생각났어...)",
  ui_story_5017_50170202_91_dialog_content = "(요우의 기억 속에서 들은 게 바로 이 방울 소리였어!)",
  ui_story_5017_50170202_92_dialog_content = "정말 아름다운 춤이었어...",
  ui_story_5017_50170202_93_dialog_content = "내가 만약 「귀신」이었으면... 저런 멋진 춤을 봤으니까 분명히 기쁘게 성불했을 것 같아.",
  ui_story_5017_50170202_94_dialog_content = "그러게, 같은 생각이야.",
  ui_story_5017_50170202_95_dialog_content = "후훗.",
  ui_story_5017_50170202_96_dialog_content = "춤을 즐겨 주시는 것은 좋은 일이지만, 죽음을 재촉해서는 아니 될 일이지요.",
  ui_story_5017_50170202_97_dialog_content = "처리가 힘들 테니까요.",
  ui_story_5017_50170202_98_dialog_content = "마, 말하기 시작했어!",
  ui_story_5017_50170202_99_dialog_content = "대답해도 되는 건가?",
  ui_story_5017_50170202_100_dialog_content = "힘내! 일단 자기소개부터!",
  ui_story_5017_50170202_101_dialog_content = "저기, 전...",
  ui_story_5017_50170202_102_dialog_content = "혹시 나 알아?",
  ui_story_5017_50170202_103_dialog_content = "네?",
  ui_story_5017_50170202_104_dialog_content = "당신은 누구신지요.",
  ui_story_5017_50170202_105_dialog_content = "난 요우야!",
  ui_story_5017_50170202_106_dialog_content = "요우...로군요. 만나 뵙게 되어 기쁩니다.",
  ui_story_5017_50170202_107_dialog_content = "아, 아니, 내 말은 그러니까...",
  ui_story_5017_50170202_108_dialog_content = "아까 방울 소리가 들려서 소리를 따라 여기까지 왔거든. 그리고 그 춤을 보니까 든 생각인데...",
  ui_story_5017_50170202_109_dialog_content = "아무래도 우리, 전에 분명히...",
  ui_story_5017_50170202_110_dialog_content = "알겠습니다.",
  ui_story_5017_50170202_111_dialog_content = "저는 <color=#FFB400>린네</color>라고 합니다. 이곳의 무녀랍니다.",
  ui_story_5017_50170202_112_dialog_content = "조금 전의 <color=#FFB400>「신악」</color>이 흡족하셨다면, 거듭 보실 기회가 있을 것입니다.",
  ui_story_5017_50170202_113_dialog_content = "아무래도 오늘 「저 녀석들」은 점잖게 있지 않을 성싶으니 말이지요.",
  ui_story_5017_50170202_114_dialog_content = "「저 녀석들」이라는 건 설마...",
  ui_story_5017_50170202_115_dialog_content = "네, 아까 여러분이 보셨던...",
  ui_story_5017_50170202_116_dialog_content = "<color=#FFB400>「오니」</color>입니다.",
  ui_story_5017_50170301_1_dialog_content = "<color=#FFB400>「오니」</color>?!",
  ui_story_5017_50170301_2_dialog_content = "오니라는 건... 제가 아는 「귀신」 같은 건가요...?",
  ui_story_5017_50170301_3_dialog_content = "왕생하지 못한 망령은 그 원념으로 인해 그늘 아래에서 형체를 이루지요.",
  ui_story_5017_50170301_4_dialog_content = "그 더러운 형상은 그들의 지난날의 모습이고...",
  ui_story_5017_50170301_5_dialog_content = "넋의 잔해는 아직 간직하고 있는 의식을 붙잡습니다...",
  ui_story_5017_50170301_6_dialog_content = "그리하여 일찍이 세상을 떠났어야 마땅한 생령은 썩어 문드러진 모습으로 다시 나타납니다.",
  ui_story_5017_50170301_7_dialog_content = "그것이 바로 「오니」입니다.",
  ui_story_5017_50170301_8_dialog_content = "그러니까 그 오니는 결국...",
  ui_story_5017_50170301_9_dialog_content = "<color=#FFB400>「죽은 자」</color>랍니다.",
  ui_story_5017_50170301_10_dialog_content = "흐이익──!",
  ui_story_5017_50170301_11_dialog_content = "그...그런 게 정말 존재했단 말이에요? 죽은 사람이... 괴물이 된다니...",
  ui_story_5017_50170301_12_dialog_content = "어머, 여러분은 운도에 오신 지 얼마 안 된 타향 분들이시겠군요.",
  ui_story_5017_50170301_13_dialog_content = "운도 밖 세상의 관념에는 영혼이란 것이 존재하지 않는다고 알고 있습니다.\n따라서 귀신도 존재하지 않는다고 믿으시겠지요.",
  ui_story_5017_50170301_14_dialog_content = "하지만 괜찮습니다.",
  ui_story_5017_50170301_15_dialog_content = "차차 믿게 되실 테니 말이지요.",
  ui_story_5017_50170301_16_dialog_content = "으윽...",
  ui_story_5017_50170301_17_dialog_content = "그, 그럼 「오니」는 운도 어디에나 있는 존재인 거야?",
  ui_story_5017_50170301_18_dialog_content = "으음... 그러한 것은 아닙니다.",
  ui_story_5017_50170301_19_dialog_content = "오니는 평소에는 많이 보이지 않습니다.",
  ui_story_5017_50170301_20_dialog_content = "다만 최근 이틀간 「음」의 흐름이 「양」보다 더 성하게 되었습니다.",
  ui_story_5017_50170301_21_dialog_content = "따라서 부정한 것들이 도처에 모습을 드러내고 있는 것입니다.",
  ui_story_5017_50170301_22_dialog_content = "<color=#FFB400>「음」? 「양」?</color>",
  ui_story_5017_50170301_23_dialog_content = "세상의 만물을 이루는 두 가지 힘을 이릅니다.",
  ui_story_5017_50170301_24_dialog_content = "서로가 서로를 살리고, 억누르기도 하는 것이지요.",
  ui_story_5017_50170301_25_dialog_content = "으엑...",
  ui_story_5017_50170301_26_dialog_content = "모르셔도 무방한 것입니다. 그저 성 바깥은 위험하다는 점만 알아주신다면 충분합니다.",
  ui_story_5017_50170301_27_dialog_content = "저를 따라 오시지요. 제가 강부성까지 안내해 드리겠습니다.",
  ui_story_5017_50170301_28_dialog_content = "강부성?! 마침 잘됐네요! 저희도 원래 거기 가려던 거였거든요.",
  ui_story_5017_50170301_29_dialog_content = "어머, 여러분은 <color=#FFB400>「춘일제」</color>에 참가하러 오신 것인지요.",
  ui_story_5017_50170301_30_dialog_content = "「춘일제」?",
  ui_story_5017_50170301_31_dialog_content = "아닌 모양이로군요...",
  ui_story_5017_50170301_32_dialog_content = "여러분은 운수가 무척 좋으시군요.\n강부성이 가장 운치 있는 시기에 때맞춰 오셨으니 말입니다.",
  ui_story_5017_50170301_33_dialog_content = "우와! 설마 축제 같은 건가요? 어떤 행사죠?",
  ui_story_5017_50170301_34_dialog_content = "그것을 알아가는 설렘은 여러분 몫으로 남겨 드리고 싶군요.",
  ui_story_5017_50170301_35_dialog_content = "다만, 지금의 상황에서는... 그저 순조롭게 진행되기만을 바랄 뿐입니다...",
  ui_story_5017_50170301_36_dialog_content = "린네 씨, 나 정말 몰라?",
  ui_story_5017_50170301_37_dialog_content = "네, 오늘 뵙기 전까지 저는 요우를 몰랐습니다.",
  ui_story_5017_50170301_38_dialog_content = "그...그럼 왜 날 그냥 「요우」라고 부르는 건데? 그렇게 친근하게!",
  ui_story_5017_50170301_39_dialog_content = "당신이 너무 사랑스럽기 때문이랍니다.",
  ui_story_5017_50170301_40_dialog_content = "마음에 안 드시는 것인지요.",
  ui_story_5017_50170301_41_dialog_content = "아니, 그런 뜻은 아니지만...",
  ui_story_5017_50170301_42_dialog_content = "그 방울 소리랑 춤... 무척 익숙하다는 생각이 들었거든.",
  ui_story_5017_50170301_43_dialog_content = "그러니까 우린 분명히 만난 적이 있을 거야! 아주 어릴 때라도 말이야!",
  ui_story_5017_50170301_44_dialog_content = "당신처럼 귀여운 소녀를 만난 적이 있었다면 분명히 기억이 남았을 것입니다.",
  ui_story_5017_50170301_45_dialog_content = "그렇구나...",
  ui_story_5017_50170301_46_dialog_content = "그럼... 혹시 이거 본 적 있어?",
  ui_story_5017_50170301_47_dialog_content = "으음?",
  ui_story_5017_50170301_48_dialog_content = "............",
  ui_story_5017_50170301_49_dialog_content = "죄송합니다만, 역시 모르겠습니다.",
  ui_story_5017_50170301_50_dialog_content = "다만 그 옥은 매우 순수한 「양」의 기를 발하고 있군요.",
  ui_story_5017_50170301_51_dialog_content = "무척이나 진귀한 물건이니, 꼭 소중히 여기셨으면 좋겠습니다.",
  ui_story_5017_50170301_52_dialog_content = "우와, 뭔가 잘 알고 있는 것 같네!",
  ui_story_5017_50170301_53_dialog_content = "그럼 이 물건에 대해 아는 게 있으면 더 알려줘!",
  ui_story_5017_50170301_54_dialog_content = "그 외에 제가 아는 것이라면 그 물건이 강부성의 것이고,\n재질이나 제조 방식 모두 오래되었다는 점이 있겠군요...",
  ui_story_5017_50170301_55_dialog_content = "또한 그 옥은 단순한 장식품으로 보이지는 않습니다.",
  ui_story_5017_50170301_56_dialog_content = "장식품이 아니라고?",
  ui_story_5017_50170301_57_dialog_content = "근데 다른 쓰임새가 있을 것처럼 보이진 않는걸.",
  ui_story_5017_50170301_58_dialog_content = "설마 쪼개서 숟가락으로 쓰기라도 하는 걸까...",
  ui_story_5017_50170301_59_dialog_content = "쉿──",
  ui_story_5017_50170301_60_dialog_content = "응?",
  ui_story_5017_50170301_61_dialog_content = "소리가 들립니다.",
  ui_story_5017_50170301_62_dialog_content = "「오니」입니다.",
  ui_story_5017_50170301_63_dialog_content = "「오니」?! 어디죠?",
  ui_story_5017_50170301_64_dialog_content = "으아아아악!",
  ui_story_5017_50170301_65_dialog_content = "앗! 저쪽에 사람이 있어요!",
  ui_story_5017_50170301_66_dialog_content = "어라, 둘은 벌써 달려가 버렸잖아...",
  ui_story_5017_50170301_67_dialog_content = "우리도 서두르자!",
  ui_story_5017_50170302_1_dialog_content = "흐이익!",
  ui_story_5017_50170302_2_dialog_content = "숲속에도 있어... 어, 어서 아래로 도망쳐!",
  ui_story_5017_50170302_3_dialog_content = "대체 오늘은 왜 오니가 이렇게 많은 거야?",
  ui_story_5017_50170302_4_dialog_content = "설마 또 그때처럼...",
  ui_story_5017_50170302_5_dialog_content = "이...이런 악귀 놈들...",
  ui_story_5017_50170302_6_dialog_content = "가까이 오지 마!",
  ui_story_5017_50170302_7_dialog_content = "스윽──",
  ui_story_5017_50170302_8_dialog_content = "「무릇 신악을 펼치면, 이매망량 모두 진토로 돌아감이라.」",
  ui_story_5017_50170302_9_dialog_content = "대단해!",
  ui_story_5017_50170302_10_dialog_content = "우리가 끼어들 필요도 없는 거야?",
  ui_story_5017_50170302_11_dialog_content = "박수만 쳐도 되겠는데?!",
  ui_story_5017_50170302_12_dialog_content = "저는 요사함을 쫓는 무녀입니다. 이는 제가 가장 능히 해낼 수 있는 일이지요.",
  ui_story_5017_50170302_13_dialog_content = "길을 잃은 이 어리석은 넋들은 제가 제도하여 왕생시켜 드리겠습니다.",
  ui_story_5017_50170302_14_dialog_content = "여러분은 부디 저쪽의 놀란 마을 분들을 보살펴 주십시오.",
  ui_story_5017_50170302_15_dialog_content = "요우, 그리고 다른 두 분...",
  ui_story_5017_50170302_16_dialog_content = "아, 그러고 보니, 아직 두 분의 존함을 듣지 못했군요.",
  ui_story_5017_50170302_17_dialog_content = "그렇네요!",
  ui_story_5017_50170302_18_dialog_content = "일단 이쪽의 비실이는 PlayerName, 그리고 전 바이스라고 해요.",
  ui_story_5017_50170302_19_dialog_content = "비실이?!",
  ui_story_5017_50170302_20_dialog_content = "후훗, 잘 기억했습니다.",
  ui_story_5017_50170302_21_dialog_content = "그럼 저 사람들은 우리한테 맡겨!",
  ui_story_5017_50170302_22_dialog_content = "난 상단의 경호원 일을 자주 했으니까, 마을 사람 지키는 일 정도는 식은 죽 먹기라구!",
  ui_story_5017_50170302_23_dialog_content = "그렇다면 모쪼록 잘 부탁드리겠습니다.",
  ui_story_5017_50170302_24_dialog_content = "감사합니다! 정말 감사합니다!",
  ui_story_5017_50170302_25_dialog_content = "하마터면 오니한테 잡아 먹힐 뻔했네요...",
  ui_story_5017_50170302_26_dialog_content = "정말 감사합니다! 은인 여러분!",
  ui_story_5017_50170302_27_dialog_content = "아하하... 왠지 창피하네...",
  ui_story_5017_50170302_28_dialog_content = "사실 답례는 저쪽의 무녀한테 하셔야 돼요.",
  ui_story_5017_50170302_29_dialog_content = "무녀... 말입니까? 설마...",
  ui_story_5017_50170302_30_dialog_content = "저기, 당신들은 강부성 사람이야?",
  ui_story_5017_50170302_31_dialog_content = "그렇습니다. 지금 강부성으로 돌아가는 길이었지요.",
  ui_story_5017_50170302_32_dialog_content = "그럼 혹시 나 알아?",
  ui_story_5017_50170302_33_dialog_content = "네...?",
  ui_story_5017_50170302_34_dialog_content = "얼른 자세히 봐봐!",
  ui_story_5017_50170302_35_dialog_content = "저희가... 아는 사이였나요?",
  ui_story_5017_50170302_36_dialog_content = "자, 자, 수다는 나중에 떨고.",
  ui_story_5017_50170302_37_dialog_content = "일단 안전한 곳으로 가자.",
  ui_story_5017_50170302_38_dialog_content = "그것도 그렇네! 알겠어!",
  ui_story_5017_50170302_39_dialog_content = "린네 쪽은... 괜찮을까...",
  ui_story_5017_50170302_40_dialog_content = "(「음」의 기운이 여전히 성하군요.)",
  ui_story_5017_50170302_41_dialog_content = "(이 시기에 모습을 드러낸 것은... 「춘일제」와 관계가 있는 것일까요...)",
  ui_story_5017_50170302_42_dialog_content = "(오니는 얼마나 더 있는 것일지요...)",
  ui_story_5017_50170302_43_dialog_content = "(모쪼록 「춘일제」에 영향을 주게 해서는 안 됩니다...)",
  ui_story_5017_50170302_44_dialog_content = "베여라.",
  ui_story_5017_50170302_45_dialog_content = "윽!",
  ui_story_5017_50170302_46_dialog_content = "이것은...",
  ui_story_5017_50170302_47_dialog_content = "으윽...",
  ui_story_5017_50170302_48_dialog_content = "쿠나이...로군요.",
  ui_story_5017_50170302_49_dialog_content = "이런 비열한 방법이라면...",
  ui_story_5017_50170302_50_dialog_content = "역시 또 「당신」인가요?",
  ui_story_5017_50170302_51_dialog_content = "끄아악... 으어...",
  ui_story_5017_50170302_52_dialog_content = "크... 콜록...",
  ui_story_5017_50170302_53_dialog_content = "오늘은... 모습을 드러내지 않으시는 것인지요.",
  ui_story_5017_50170302_54_dialog_content = "<color=#FFB400>「닌자」 나리.</color>",
  ui_story_5017_50170302_55_dialog_content = "소생의 얼굴은 그대가 죽기 전 보게 될 것이외다.",
  ui_story_5017_50170302_56_dialog_content = "그럼 그때는 귀여운 표정으로 부탁드려도 될까요?",
  ui_story_5017_50170302_57_dialog_content = "그 어여쁜 얼굴이 아깝습니다.",
  ui_story_5017_50170302_58_dialog_content = "무의미한 저항은 삼가라.",
  ui_story_5017_50170302_59_dialog_content = "죄송합니다. 닌자 나리.",
  ui_story_5017_50170302_60_dialog_content = "전 죽을 수 없거든요. 적어도 지금은 말이지요.",
  ui_story_5017_50170302_61_dialog_content = "!!!",
  ui_story_5017_50170302_62_dialog_content = "린네! 괜찮아?!",
  ui_story_5017_50170302_63_dialog_content = "괜찮습니다. 그저 찰과상일 뿐입니다.",
  ui_story_5017_50170302_64_dialog_content = "쳇...",
  ui_story_5017_50170302_65_dialog_content = "감히 린네를 습격해?!",
  ui_story_5017_50170302_66_dialog_content = "비겁한 녀석! 받아라!",
  ui_story_5017_50170401_1_dialog_content = "우와, 너 꽤 하잖아?!",
  ui_story_5017_50170401_2_dialog_content = "이렇게 강한 적을 상대하는 건 정말 오랜만이야!",
  ui_story_5017_50170401_3_dialog_content = "재미있네!",
  ui_story_5017_50170401_4_dialog_content = "잠깐, 그대는...",
  ui_story_5017_50170401_5_dialog_content = "또 피했네?",
  ui_story_5017_50170401_6_dialog_content = "다시!",
  ui_story_5017_50170401_7_dialog_content = "왜 갑자기 진지하게 안 하는 건데?",
  ui_story_5017_50170401_8_dialog_content = "재미없게시리.",
  ui_story_5017_50170401_9_dialog_content = "큭...",
  ui_story_5017_50170401_10_dialog_content = "제대로 하란 말이야!",
  ui_story_5017_50170401_11_dialog_content = "한 대 맞으면 아플걸?",
  ui_story_5017_50170401_12_dialog_content = "「속사 감지」!",
  ui_story_5017_50170401_13_dialog_content = "요우! 왜 갑자기 린네 씨 쪽으로 간 거야?",
  ui_story_5017_50170401_14_dialog_content = "무슨 일 있었어?",
  ui_story_5017_50170401_15_dialog_content = "린네가 어떤 사람한테 습격당했어.",
  ui_story_5017_50170401_16_dialog_content = "사람?",
  ui_story_5017_50170401_17_dialog_content = "응, 사람이었어. 오니가 아니라.",
  ui_story_5017_50170401_18_dialog_content = "이 섬... 대체 어떻게 된 거야?\n사방에 오니가 있는 것도 모자라서 인심도 엉망이네!",
  ui_story_5017_50170401_19_dialog_content = "......",
  ui_story_5017_50170401_20_dialog_content = "아... 당신들 얘기가 아니구요...",
  ui_story_5017_50170401_21_dialog_content = "여러분은... 외지인이시군요.",
  ui_story_5017_50170401_22_dialog_content = "네? 어떻게 알았죠?",
  ui_story_5017_50170401_23_dialog_content = "누가 봐도 뻔하잖아!",
  ui_story_5017_50170401_24_dialog_content = "여러분은 무섭지 않으신가요?",
  ui_story_5017_50170401_25_dialog_content = "아니요. 처음엔 저도 엄청 무서웠죠...",
  ui_story_5017_50170401_26_dialog_content = "근데 전혀 무서워하지 않는 사람 둘이랑 같이 있다 보니까,\n아무래도 영향을 받은 것 같아요.",
  ui_story_5017_50170401_27_dialog_content = "그 둘은 지금 없잖아.",
  ui_story_5017_50170401_28_dialog_content = "조용히 좀 해!",
  ui_story_5017_50170401_29_dialog_content = "그저 떠도는 오니 정도는 무서운 것이 아닙니다.",
  ui_story_5017_50170401_30_dialog_content = "하지만... 운도에서는 이미 오랫동안 오니가 이렇게 많이 나타난 적이 없었습니다.",
  ui_story_5017_50170401_31_dialog_content = "마지막으로 이런 일이 있었던 것은 10년 전이었지요.",
  ui_story_5017_50170401_32_dialog_content = "운도의 노인들은 그것을...",
  ui_story_5017_50170401_33_dialog_content = "<color=#FFB400>「귀문이 열렸다」</color>고 말했습니다.",
  ui_story_5017_50170401_34_dialog_content = "귀문이 열려? 뭔가 무서운 말이네요...",
  ui_story_5017_50170401_35_dialog_content = "참, 그때도 마침 지금 이 계절이었지요.",
  ui_story_5017_50170401_36_dialog_content = "온 산과 들이 만발한 벚꽃으로 뒤덮여 있었습니다.",
  ui_story_5017_50170401_37_dialog_content = "그 사건 덕분에 몇 년 사이에 벚꽃은 점점 더 아름다워졌습니다.",
  ui_story_5017_50170401_38_dialog_content = "네? 그게 무슨 뜻이죠...?",
  ui_story_5017_50170401_39_dialog_content = "그 전설을 모르시는 겁니까?",
  ui_story_5017_50170401_40_dialog_content = "벚꽃은 처음에는 하얀색이었습니다.",
  ui_story_5017_50170401_41_dialog_content = "<size=45><color=#FFB400>벚나무 뿌리가 신선한 피를 마신 끝에 꽃잎이 조금씩 붉게 물든 것입니다.</color></size>",
  ui_story_5017_50170401_42_dialog_content = "!!!",
  ui_story_5017_50170401_43_dialog_content = "그럼... 「몇 년 사이에 벚꽃이 점점 더 아름다워졌다」는 건...",
  ui_story_5017_50170401_44_dialog_content = "그렇습니다. 많은 사람들이... 하하...",
  ui_story_5017_50170401_45_dialog_content = "게다가 그건 단순한 천재지변이 아니라...",
  ui_story_5017_50170401_46_dialog_content = "사실은 인재였다고 믿는 사람들도 있습니다.",
  ui_story_5017_50170401_47_dialog_content = "그런...",
  ui_story_5017_50170401_48_dialog_content = "그어어...",
  ui_story_5017_50170401_49_dialog_content = "으앗!",
  ui_story_5017_50170401_50_dialog_content = "또 오니한테 포위당했어!",
  ui_story_5017_50170401_51_dialog_content = "바이스! 일단 이쪽을 공격하자!",
  ui_story_5017_50170401_52_dialog_content = "안 돼! 방금 얘기를 듣고 나니까 도저히 싸울 수가 없어!",
  ui_story_5017_50170401_53_dialog_content = "요, 요우랑... 린네 씨한테 가자!",
  ui_story_5017_50170401_54_dialog_content = "다시 두 사람의 정신력을 받아서 용기를 내야 해!",
  ui_story_5017_50170401_55_dialog_content = "<color=#e8d9bb>타다다다다다닥...</color>",
  ui_story_5017_50170401_56_dialog_content = "야──!",
  ui_story_5017_50170401_57_dialog_content = "야!",
  ui_story_5017_50170401_58_dialog_content = "거기! 우리 좀 봐 줘!",
  ui_story_5017_50170401_59_dialog_content = "바이스, PlayerName, 다들 왜 이쪽으로 왔어?",
  ui_story_5017_50170401_60_dialog_content = "으악! 오니가 잔뜩 있습니다!",
  ui_story_5017_50170401_61_dialog_content = "전부 몰려오고 있습니다!",
  ui_story_5017_50170401_62_dialog_content = "그어어...",
  ui_story_5017_50170401_63_dialog_content = "우와! 제대로 한판 싸워보겠는걸!",
  ui_story_5017_50170401_64_dialog_content = "거기 꼬맹이, 우리 잠깐 휴전하는 게 어때? 일단 오니부터 처리하고 다시 싸우는 거야!",
  ui_story_5017_50170401_65_dialog_content = "이젠 상의할 시간도 없어! 오니가 벌써 여기까지 왔다고!",
  ui_story_5017_50170401_66_dialog_content = "오! 나한테 맡겨!",
  ui_story_5017_50170402_1_dialog_content = "우오오──",
  ui_story_5017_50170402_2_dialog_content = "야! 꼬맹이, 방금 그건 내가 노린 녀석이었다고!",
  ui_story_5017_50170402_3_dialog_content = "뺏어가면 어떡해?!",
  ui_story_5017_50170402_4_dialog_content = "......",
  ui_story_5017_50170402_5_dialog_content = "네 검술은 아름답지만, 단지 그것뿐이야.",
  ui_story_5017_50170402_6_dialog_content = "초식의 변화도 너무 단조로워.",
  ui_story_5017_50170402_7_dialog_content = "뭐라고 해야 하나... 한 수를 보면 다음 수가 바로 예측이 된다고.",
  ui_story_5017_50170402_8_dialog_content = "그 정도 가지고는 날 이길 수 없어!",
  ui_story_5017_50170402_9_dialog_content = "......",
  ui_story_5017_50170402_10_dialog_content = "억울하면 다시 승부해도 좋아!",
  ui_story_5017_50170402_11_dialog_content = "뭐, 서두를 건 없어. 일단 남은 오니 몇 마리부터 쓰러트리고...",
  ui_story_5017_50170402_12_dialog_content = "그대는...",
  ui_story_5017_50170402_13_dialog_content = "<color=#FFB400>요우</color>인가?",
  ui_story_5017_50170402_14_dialog_content = "뭐...?",
  ui_story_5017_50170402_15_dialog_content = "날... 알아?",
  ui_story_5017_50170402_16_dialog_content = "요우, 너무 다가가지 마세요.",
  ui_story_5017_50170402_17_dialog_content = "그 「개」는 사람을 물거든요.",
  ui_story_5017_50170402_18_dialog_content = "오늘 이토록 많은 망령을 제도했으니, 오늘은 당신에게도 죽기 좋은 날일지도 모르겠네요.",
  ui_story_5017_50170402_19_dialog_content = "적어도 황천으로 향하는 길이 외롭지는 않을 것입니다.",
  ui_story_5017_50170402_20_dialog_content = "......",
  ui_story_5017_50170402_21_dialog_content = "저기...",
  ui_story_5017_50170402_22_dialog_content = "잠깐만──!",
  ui_story_5017_50170402_23_dialog_content = "사라졌잖아?!",
  ui_story_5017_50170402_24_dialog_content = "어머, 닌자 나리께선 저의 제안이 마음에 들지 않으셨나 봅니다.",
  ui_story_5017_50170402_25_dialog_content = "아직 물어보고 싶은 게 있었는데...",
  ui_story_5017_50170402_26_dialog_content = "요우, 무엇을 듣고 싶으셨던 것인지요.",
  ui_story_5017_50170402_27_dialog_content = "그 사람... 왠지 날 아는 것 같았어.",
  ui_story_5017_50170402_28_dialog_content = "신출귀몰한 자입니다. 이 세상 모든 이를 안다 하여도 이상할 것이 없지요.",
  ui_story_5017_50170402_29_dialog_content = "그래?",
  ui_story_5017_50170402_30_dialog_content = "저 사람 대체 정체가 뭔데?",
  ui_story_5017_50170402_31_dialog_content = "닌자입니다.",
  ui_story_5017_50170402_32_dialog_content = "암살을 목적으로, 극단적인 방식으로 단련된 <color=#FFB400>「인간병기」</color>이지요.",
  ui_story_5017_50170402_33_dialog_content = "이름은... 뭐라고 했었는지...",
  ui_story_5017_50170402_34_dialog_content = "아, 그렇네요. 아메모리입니다.",
  ui_story_5017_50170402_35_dialog_content = "암살? 그럼 저 사람이 노리는 암살 대상이 너야?",
  ui_story_5017_50170402_36_dialog_content = "그렇습니다.",
  ui_story_5017_50170402_37_dialog_content = "다만 이유는 저도 모르겠습니다.",
  ui_story_5017_50170402_38_dialog_content = "직접 물어보아도 닌자 나리는 말수가 적습니다.",
  ui_story_5017_50170402_39_dialog_content = "따라서 방금 전처럼...",
  ui_story_5017_50170402_40_dialog_content = "어디서든 마주치면 영문도 모른 채 싸우게 되는 것입니다.",
  ui_story_5017_50170402_41_dialog_content = "정말 무서운 생활을 하고 있었네요...",
  ui_story_5017_50170402_42_dialog_content = "후훗... 실은 꽤나 재미있는 것이랍니다.",
  ui_story_5017_50170402_43_dialog_content = "저와 닌자 나리는 공통점이 있습니다...",
  ui_story_5017_50170402_44_dialog_content = "저희에게 있어 죽음은 아무것도 아닙니다.",
  ui_story_5017_50170402_45_dialog_content = "뭐? 어째서?",
  ui_story_5017_50170402_46_dialog_content = "죽으면 전부 끝이잖아?",
  ui_story_5017_50170402_47_dialog_content = "죽음으로 빼앗길 만한 물건 따위는 제 생에서 가져본 적도 없습니다.",
  ui_story_5017_50170402_48_dialog_content = "제가 진실로 가지고 있는 것은 생사의 윤회에 얽매여 있는 것이 아니랍니다.",
  ui_story_5017_50170402_49_dialog_content = "......",
  ui_story_5017_50170402_50_dialog_content = "저기... 무슨 말인지 잘 모르겠는데, 다시 한번 말해줄래?",
  ui_story_5017_50170402_51_dialog_content = "후훗, 거듭하여 입에 담을 이야기는 아니랍니다.",
  ui_story_5017_50170402_52_dialog_content = "그쪽 분들은 강부성 주민이시겠지요.",
  ui_story_5017_50170402_53_dialog_content = "......",
  ui_story_5017_50170402_54_dialog_content = "네.",
  ui_story_5017_50170402_55_dialog_content = "지금 성 밖은 매우 위험합니다. 저를 따라오시지요.",
  ui_story_5017_50170402_56_dialog_content = "돌아가는 길은 제가 모셔다드리겠습니다.",
  ui_story_5017_50170402_57_dialog_content = "그럼 다시 강부성으로 출발해 볼까요?",
  ui_story_5017_50170402_58_dialog_content = "응!",
  ui_story_5017_50170402_59_dialog_content = "<color=#e8d9bb>스으윽!</color>",
  ui_story_5017_50170402_60_dialog_content = "흐이익!",
  ui_story_5017_50170402_61_dialog_content = "뭐, 뭐야?! 방금 그거?",
  ui_story_5017_50170402_62_dialog_content = "으음?",
  ui_story_5017_50170402_63_dialog_content = "왜 그래? 뭘 보고 놀란 거야?",
  ui_story_5017_50170402_64_dialog_content = "너흰 못 봤어?",
  ui_story_5017_50170402_65_dialog_content = "뭘?",
  ui_story_5017_50170402_66_dialog_content = "뭐, 됐어... 그냥 내가 예민했던 거겠지.",
  ui_story_5017_50170402_67_dialog_content = "가자.",
  ui_story_5017_50170402_68_dialog_content = "후후후...",
  ui_story_5017_50170501_1_dialog_content = "저 죽은 사람들은 왜 오니가 된 거죠?",
  ui_story_5017_50170501_2_dialog_content = "그것은 저마다 사정이 다르겠지요.",
  ui_story_5017_50170501_3_dialog_content = "죽음으로도 풀리지 않는 마음의 응어리를 지닌 이도 있을 것이고...",
  ui_story_5017_50170501_4_dialog_content = "어쩌면 집념이나 아쉬움, 혹은 강한 욕망 탓일 수도 있습니다.",
  ui_story_5017_50170501_5_dialog_content = "그러한 생각 때문에 황천에 가는 것을 거부하면, 영혼이 인간 세상에 남게 됩니다.",
  ui_story_5017_50170501_6_dialog_content = "그리고 그 영혼을 받아들일 그릇을 발견하면, 빙의하여 오니가 되는 것입니다.",
  ui_story_5017_50170501_7_dialog_content = "정말 괴담이랑 똑같네요...",
  ui_story_5017_50170501_8_dialog_content = "개중에는 자신의 의지가 아니라, 다른 뜻을 품은 자들에 의해 속박된 이도 있습니다.",
  ui_story_5017_50170501_9_dialog_content = "어떤 술법은 영혼을 그릇에 가두어 꼭두각시처럼 조종할 수 있으니 말이지요.",
  ui_story_5017_50170501_10_dialog_content = "그로 인해 현세에 속하지 않은 이가 도리어 현세 사람의 욕심을 위해 일하게 되는 것입니다.",
  ui_story_5017_50170501_11_dialog_content = "어떻게 그런...",
  ui_story_5017_50170501_12_dialog_content = "후훗, 인간이란 본디 말썽을 잘 피우는 생물이지요. 그렇지 않습니까?",
  ui_story_5017_50170501_13_dialog_content = "......",
  ui_story_5017_50170501_14_dialog_content = "자, 이제 앞을 보시지요.",
  ui_story_5017_50170501_15_dialog_content = "저곳이 바로 강부성입니다.",
  ui_story_5017_50170501_16_dialog_content = "와! 진짜 예뻐!",
  ui_story_5017_50170501_17_dialog_content = "건물이 잔뜩 있어! 길도 있고 사람도 있어!",
  ui_story_5017_50170501_18_dialog_content = "도시가 다 그런 거 아냐?",
  ui_story_5017_50170501_19_dialog_content = "내 고향이 이렇게 예쁜 곳이었구나...",
  ui_story_5017_50170501_20_dialog_content = "그럼 내 집은 어디 있는 거지?",
  ui_story_5017_50170501_21_dialog_content = "알겠어! 분명히 저 제일 큰 집이야!",
  ui_story_5017_50170501_22_dialog_content = "후훗, 저 큰 건물은 강부성의 <color=#FFB400>「본성」</color>인데, 아쉽게도 이미 주인이 계십니다.",
  ui_story_5017_50170501_23_dialog_content = "강부성을 다스리시는 <color=#FFB400>「합하」</color>께서 지내시는 곳이랍니다.",
  ui_story_5017_50170501_24_dialog_content = "그리고 합하의 가신들도 머무르고 있습니다.",
  ui_story_5017_50170501_25_dialog_content = "저를 포함해서 말이지요.",
  ui_story_5017_50170501_26_dialog_content = "뭐? 린네 넌 저런 호화로운 집에 사는 거였어?!",
  ui_story_5017_50170501_27_dialog_content = "네. 저는 「합하」의 양녀이기 때문입니다.",
  ui_story_5017_50170501_28_dialog_content = "진짜 좋겠다아...",
  ui_story_5017_50170501_29_dialog_content = "그럼 린네 집을 차지할 순 없으니까, 린네 집에서 제일 가까운 곳에 살아야지!",
  ui_story_5017_50170501_30_dialog_content = "어머, 언제든지 환영하겠습니다.",
  ui_story_5017_50170501_31_dialog_content = "그럼 본성 아래를 보아주시지요. 가장 번화한 저 지역은 <color=#FFB400>「사카이 거리」</color>라는 곳입니다.",
  ui_story_5017_50170501_32_dialog_content = "맛있는 음식이나 즐거운 것들이 많이 있답니다. 요우도 분명히 좋아하게 될 것입니다.",
  ui_story_5017_50170501_33_dialog_content = "응! 아주 좋아!",
  ui_story_5017_50170501_34_dialog_content = "그럼 먼 곳에서 오신 손님 여러분.",
  ui_story_5017_50170501_35_dialog_content = "다시 한번 강부성에 오신 것을 환영합니다.",
  ui_story_5017_50170501_36_dialog_content = "드디어 무사히 집에 왔군요!",
  ui_story_5017_50170501_37_dialog_content = "정말 감사했습니다! 생명의 은인 여러분!",
  ui_story_5017_50170501_38_dialog_content = "뭐 그렇게까지야...",
  ui_story_5017_50170501_39_dialog_content = "맞다! 아까 하던 얘기!",
  ui_story_5017_50170501_40_dialog_content = "당신들 정말 나 본 적 없어?",
  ui_story_5017_50170501_41_dialog_content = "그건...",
  ui_story_5017_50170501_42_dialog_content = "지금 모습은 잘 모르겠으면...",
  ui_story_5017_50170501_43_dialog_content = "어렸을 때 만난 적은 없었을까?",
  ui_story_5017_50170501_44_dialog_content = "으음...",
  ui_story_5017_50170501_45_dialog_content = "어릴 땐 지금보다 키도 작고 얼굴도 동글동글했을 거야.",
  ui_story_5017_50170501_46_dialog_content = "머리도 이렇게 안 길고, 아마 왕만두 같은 머리를 하고 있었을 텐데...",
  ui_story_5017_50170501_47_dialog_content = "아, 아무튼 도와주셔서 감사합니다!",
  ui_story_5017_50170501_48_dialog_content = "왜 갑자기 인사를 하는데?!",
  ui_story_5017_50170501_49_dialog_content = "그냥 얼른 말을 돌리고 싶은 거야...",
  ui_story_5017_50170501_50_dialog_content = "그리고 이상한 옷을 입은 은인 두 분도 감사합니다!",
  ui_story_5017_50170501_51_dialog_content = "이상한 옷?!",
  ui_story_5017_50170501_52_dialog_content = "그리고...",
  ui_story_5017_50170501_53_dialog_content = "......",
  ui_story_5017_50170501_54_dialog_content = "......",
  ui_story_5017_50170501_55_dialog_content = "어, 어쨌든 은인 여러분, 구해주셔서 정말 감사합니다!",
  ui_story_5017_50170501_56_dialog_content = "다만... 급한 일이 있어서, 저흰 이만 여기서 실례하겠습니다...",
  ui_story_5017_50170501_57_dialog_content = "그, 그럼 다음에 또 뵙겠습니다!",
  ui_story_5017_50170501_58_dialog_content = "어라? 가버렸네?",
  ui_story_5017_50170501_59_dialog_content = "너무 갑작스럽잖아...",
  ui_story_5017_50170501_60_dialog_content = "「춘일제」가 다가오고 있으니, 모두 무척이나 바쁘겠지요.",
  ui_story_5017_50170501_61_dialog_content = "방해하지 않는 것이 좋을 듯합니다.",
  ui_story_5017_50170501_62_dialog_content = "그렇구나.",
  ui_story_5017_50170501_63_dialog_content = "린네는? 너도 바빠?",
  ui_story_5017_50170501_64_dialog_content = "그렇습니다.",
  ui_story_5017_50170501_65_dialog_content = "저는 이제 「본성」으로 돌아갈 시간입니다.",
  ui_story_5017_50170501_66_dialog_content = "성 밖에서 오니가 설치고 있으니, 반드시 대책을 세워야 합니다.",
  ui_story_5017_50170501_67_dialog_content = "그래...",
  ui_story_5017_50170501_68_dialog_content = "그럼 린네도 우리랑 헤어지는 거네...",
  ui_story_5017_50170501_69_dialog_content = "후훗.",
  ui_story_5017_50170501_70_dialog_content = "가는 방향이 같다면 함께 거리를 걸어보는 것도 좋겠지요.",
  ui_story_5017_50170501_71_dialog_content = "응, 같을 거야!",
  ui_story_5017_50170501_72_dialog_content = "딱 같은 방향이라구!",
  ui_story_5017_50170501_73_dialog_content = "자, 자! 여러분!",
  ui_story_5017_50170501_74_dialog_content = "신선한 바지락이 왔습니다! 한번 보고 가세요!",
  ui_story_5017_50170501_75_dialog_content = "손님, 곁에 계신 아가씨께 꽃다발 하나 선물하지 않으시겠습니까?",
  ui_story_5017_50170501_76_dialog_content = "우와! 진짜 시끌벅적하네!",
  ui_story_5017_50170501_77_dialog_content = "거리에 사람들이 한가득이야!",
  ui_story_5017_50170501_78_dialog_content = "그러게!",
  ui_story_5017_50170501_79_dialog_content = "노점도 엄청 많아!",
  ui_story_5017_50170501_80_dialog_content = "간식에, 장난감에, 공예품, 재봉소까지...",
  ui_story_5017_50170501_81_dialog_content = "여기서 하루 종일 놀 수도 있겠어!",
  ui_story_5017_50170501_82_dialog_content = "후훗, 지금은 아직 준비 기간일 뿐이랍니다.",
  ui_story_5017_50170501_83_dialog_content = "「춘일제」가 정식으로 시작되고 나면 지금보다 더 번화한 모습이 되겠지요.",
  ui_story_5017_50170501_84_dialog_content = "모두들 유카타를 입고 탈을 쓴 채, 사카이 거리로 모여듭니다.",
  ui_story_5017_50170501_85_dialog_content = "무희는 노래에 맞추어 춤을 추고, 꽃수레는 마을을 돌지요.",
  ui_story_5017_50170501_86_dialog_content = "(...정말 그립네요.)",
  ui_story_5017_50170501_87_dialog_content = "우와! 저건 뭐야?",
  ui_story_5017_50170501_88_dialog_content = "사람들이 연못 주변에 모여 있는데?",
  ui_story_5017_50170501_89_dialog_content = "그것은 <color=#FFB400>「금붕어 건지기」</color>라는 것입니다. 이곳에서 유행하는 놀이랍니다.",
  ui_story_5017_50170501_90_dialog_content = "우와, 재밌겠다!",
  ui_story_5017_50170501_91_dialog_content = "해봐도 돼?",
  ui_story_5017_50170501_92_dialog_content = "나도 하고 싶어!",
  ui_story_5017_50170501_93_dialog_content = "그럼 다녀오시지요.",
  ui_story_5017_50170501_94_dialog_content = "다만 돈을 내야 합니다. 혹시 돈은 가지고 계신지요.",
  ui_story_5017_50170501_95_dialog_content = "아, 현금은 얼마 없는데.",
  ui_story_5017_50170501_96_dialog_content = "아스트라 대륙에서 통용되는 수표도 받아?",
  ui_story_5017_50170501_97_dialog_content = "수...표 말인가요?",
  ui_story_5017_50170501_98_dialog_content = "괜찮아. 돈이라면 요우한테는 문제가 안 될 테니까...",
  ui_story_5017_50170501_99_dialog_content = "후후~ 그럼 다녀올게!",
  ui_story_5017_50170501_100_dialog_content = "여기서 기다리고 있어!",
  ui_story_5017_50170501_101_dialog_content = "후훗, 마치 어린아이들 같군요.",
  ui_story_5017_50170501_102_dialog_content = "저희도 주변을 한번 둘러볼까요?",
  ui_story_5017_50170501_103_dialog_content = "그래...",
  ui_story_5017_50170501_104_dialog_content = "<color=#e8d9bb>휘익!</color>",
  ui_story_5017_50170501_105_dialog_content = "?!",
  ui_story_5017_50170501_106_dialog_content = "또 나타났어?!",
  ui_story_5017_50170501_107_dialog_content = "어머, 무슨 일이신가요?",
  ui_story_5017_50170501_108_dialog_content = "넌... 못 봤어?",
  ui_story_5017_50170501_109_dialog_content = "방금 뭐가 「휘익」하고 날아갔는데...",
  ui_story_5017_50170501_110_dialog_content = "전혀 못 봤습니다.",
  ui_story_5017_50170501_111_dialog_content = "설마 오니 같은 건 아니겠지...",
  ui_story_5017_50170501_112_dialog_content = "후훗, PlayerName 님, 어쩌면 너무 긴장하신 탓일지도 모릅니다.",
  ui_story_5017_50170501_113_dialog_content = "이런 번화한 곳 어디에 오니가 나설 자리가 있겠는지요.",
  ui_story_5017_50170501_114_dialog_content = "자, 계속 가볼까요...",
  ui_story_5017_50170501_115_dialog_content = "누나! 사과사탕 살래?",
  ui_story_5017_50170501_116_dialog_content = "어머나.",
  ui_story_5017_50170501_117_dialog_content = "우리 집 사과사탕은 아주 달콤해!",
  ui_story_5017_50170501_118_dialog_content = "그리고 빨간색이 예쁘잖아! 누나한테 딱이야!",
  ui_story_5017_50170501_119_dialog_content = "그런가요? 얼마나 달콤할까요?",
  ui_story_5017_50170501_120_dialog_content = "으음... 내가 대신 먹어볼게!",
  ui_story_5017_50170501_121_dialog_content = "냠냠...",
  ui_story_5017_50170501_122_dialog_content = "응! 진짜 달콤해!",
  ui_story_5017_50170501_123_dialog_content = "누나처럼!",
  ui_story_5017_50170501_X123_dialog_content = "어머, 아직 어린데도 말솜씨가 좋군요.",
  ui_story_5017_50170501_124_dialog_content = "어때? 누나, 하나 안 살래?",
  ui_story_5017_50170501_125_dialog_content = "후훗, 저는...",
  ui_story_5017_50170501_126_dialog_content = "이 녀석, 또 멋대로 돌아다니고... 아빠가 말했잖아. 저 사람한테는 물건 팔면 안 된다고...",
  ui_story_5017_50170501_127_dialog_content = "미안합니다. 사과사탕은 안 팝니다.",
  ui_story_5017_50170501_128_dialog_content = "어라? 아빠, 왜?",
  ui_story_5017_50170501_129_dialog_content = "얼른 따라와!",
  ui_story_5017_50170501_130_dialog_content = "뭐야... 어떻게 된 거야?",
  ui_story_5017_50170501_131_dialog_content = "저 남자, 너무 심하잖아. 우린 손님 아냐?",
  ui_story_5017_50170501_132_dialog_content = "......",
  ui_story_5017_50170501_133_dialog_content = "PlayerName! 와서 좀 도와줘!",
  ui_story_5017_50170501_134_dialog_content = "휴... 무거워... 이 대협객 요우 님도 이 정도는...",
  ui_story_5017_50170501_135_dialog_content = "너, 너희...",
  ui_story_5017_50170501_136_dialog_content = "연못의 금붕어를 죄다 건져 오기라도 한 거야?",
  ui_story_5017_50170501_137_dialog_content = "어쩔 수 없지. 금붕어가 보이는데 잡아야지!",
  ui_story_5017_50170501_138_dialog_content = "이렇게 많이 잡아가지고 뭘 어쩌려는 건데?!",
  ui_story_5017_50170501_139_dialog_content = "음... 식당이라도 찾아갈까?",
  ui_story_5017_50170501_140_dialog_content = "무슨 소리야?! 금붕어는 관상어라고!",
  ui_story_5017_50170501_141_dialog_content = "그래도 배고프단 말이야.",
  ui_story_5017_50170501_142_dialog_content = "그러게, 금붕어 건지느라 힘들었어.",
  ui_story_5017_50170501_143_dialog_content = "사과사탕은 어떠신지요.",
  ui_story_5017_50170501_144_dialog_content = "사과사탕?",
  ui_story_5017_50170501_145_dialog_content = "네, 강부성의 명물 간식입니다. 걸으면서 먹기에 좋을 것입니다.",
  ui_story_5017_50170501_146_dialog_content = "마침 조금 전에 저쪽에서 한 아이가 팔고 있는 것을 보았습니다.",
  ui_story_5017_50170501_147_dialog_content = "그럼 가자! 지금 당장!",
  ui_story_5017_50170501_148_dialog_content = "다녀오시지요. 저는 여기서 기다리고 있겠습니다.",
  ui_story_5017_50170501_149_dialog_content = "어? 왜?",
  ui_story_5017_50170501_150_dialog_content = "걷다 지쳤어?",
  ui_story_5017_50170501_151_dialog_content = "......",
  ui_story_5017_50170501_152_dialog_content = "그렇습니다.",
  ui_story_5017_50170501_153_dialog_content = "고맙습니다!",
  ui_story_5017_50170501_154_dialog_content = "하나, 둘, 셋, 넷...",
  ui_story_5017_50170501_155_dialog_content = "아빠! 돈 많이 벌었어!",
  ui_story_5017_50170501_156_dialog_content = "......",
  ui_story_5017_50170501_157_dialog_content = "저 세 사람, 방금 네 개 산 거냐?",
  ui_story_5017_50170501_158_dialog_content = "응, 맞아.",
  ui_story_5017_50170501_159_dialog_content = "검은 머리 누나가 많이 먹을 것 같았어. 두 개 먹으려는 거 아닐까?",
  ui_story_5017_50170501_160_dialog_content = "저기 저 볼품없는 사내, 방금 무녀 곁에 있던 녀석이야.",
  ui_story_5017_50170501_161_dialog_content = "무녀한테 주려고 산 거겠지... 휴.",
  ui_story_5017_50170501_162_dialog_content = "무녀?",
  ui_story_5017_50170501_163_dialog_content = "아! 빨간 옷 누나?",
  ui_story_5017_50170501_164_dialog_content = "명심해라. 앞으로는 그 여자한테 가까이 가면 안 된다.",
  ui_story_5017_50170501_165_dialog_content = "왜?",
  ui_story_5017_50170501_166_dialog_content = "그 누나 진짜 예뻤는데!",
  ui_story_5017_50170501_167_dialog_content = "그게 중요한 게 아니란 말이다. 그 무녀는 나쁜 사람이야.",
  ui_story_5017_50170501_168_dialog_content = "왜 나쁜 사람인데?",
  ui_story_5017_50170501_169_dialog_content = "그 빨간 옷 누나, 되게 자상하게 말을 걸어줬어. 그리고 우리 사과사탕도 사려고 했어!",
  ui_story_5017_50170501_170_dialog_content = "그건 말이다...",
  ui_story_5017_50170501_171_dialog_content = "<size=30>그 여자는 쇼군 집 사람이야.</size>",
  ui_story_5017_50170501_172_dialog_content = "응?",
  ui_story_5017_50170501_173_dialog_content = "쇼군 집 사람이 왜?",
  ui_story_5017_50170501_174_dialog_content = "쇼군이 나쁜 사람이야?",
  ui_story_5017_50170501_175_dialog_content = "쉿!",
  ui_story_5017_50170501_176_dialog_content = "여긴 밖이잖아! 그런 말을 큰 소리로 하면 안 돼!",
  ui_story_5017_50170501_177_dialog_content = "으응...",
  ui_story_5017_50170501_178_dialog_content = "아빠 무서워...",
  ui_story_5017_50170501_179_dialog_content = "넌 아직 모른다... 어른이 되면 알게 될 거야.",
  ui_story_5017_50170501_180_dialog_content = "아빠 말 명심해라. 아빠가 너한테 해가 될 말은 하지 않으니 말이야.",
  ui_story_5017_50170501_181_dialog_content = "응...",
  ui_story_5017_50170501_182_dialog_content = "그래서 아빠가 뭐라고 했지?",
  ui_story_5017_50170501_183_dialog_content = "빨간 옷 누나한테 가까이 가지 말랬어... 나쁜 사람이라고...",
  ui_story_5017_50170501_184_dialog_content = "그렇지, 착하지.",
  ui_story_5017_50170501_185_dialog_content = "계속 서 있으니까 피곤하지?",
  ui_story_5017_50170501_186_dialog_content = "가자. 아빠가 빙수 사 주마.",
  ui_story_5017_50170501_187_dialog_content = "우와! 빙수다!",
  ui_story_5017_50170601_1_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_5017_50170601_2_dialog_content = "으아... 너흰 나랑 바이스가 고생해서 잡은 물고기들이라구!",
  ui_story_5017_50170601_3_dialog_content = "앞으로 건강하게 살아가야 해!",
  ui_story_5017_50170601_4_dialog_content = "꼭 건강하게 살아!",
  ui_story_5017_50170601_5_dialog_content = "금붕어 풀어주면서 무슨 생이별하는 것처럼...",
  ui_story_5017_50170601_6_dialog_content = "넌 몰라. 저 녀석들은 말이지...",
  ui_story_5017_50170601_7_dialog_content = "이제 밥 먹으러 갈까?",
  ui_story_5017_50170601_8_dialog_content = "가자!",
  ui_story_5017_50170601_9_dialog_content = "정말 알기 쉬운 녀석이라니까...",
  ui_story_5017_50170601_10_dialog_content = "린네, 어디 맛있는 식당 없을까?",
  ui_story_5017_50170601_11_dialog_content = "어머, 제 추천이 필요하신가요?",
  ui_story_5017_50170601_12_dialog_content = "당연하지. 넌 우리보다 여길 잘 알잖아.",
  ui_story_5017_50170601_13_dialog_content = "으음...",
  ui_story_5017_50170601_14_dialog_content = "제가 자주 가는 가게가 근처에 있습니다.",
  ui_story_5017_50170601_15_dialog_content = "맛은 제가 보장할 순 없겠지만, 경치는 정말 좋답니다.",
  ui_story_5017_50170601_16_dialog_content = "그래! 그럼 가자!",
  ui_story_5017_50170601_17_dialog_content = "손님 여러분, 2층으로 모시겠습니다.",
  ui_story_5017_50170601_18_dialog_content = "오오오오!",
  ui_story_5017_50170601_19_dialog_content = "대단해!",
  ui_story_5017_50170601_20_dialog_content = "이곳에 앉으면 성의 풍경을 볼 수 있답니다.",
  ui_story_5017_50170601_21_dialog_content = "모두가 「춘일제」를 위해 바삐 일하고 있군요.",
  ui_story_5017_50170601_22_dialog_content = "그나저나 그 「춘일제」라는 게 구체적으로 어떤 건지 말해줄 수 있어?",
  ui_story_5017_50170601_23_dialog_content = "무슨 기념일이나 의미가 있는 축제인 거야?",
  ui_story_5017_50170601_24_dialog_content = "후훗, 실은 무척 단순한 것이랍니다.",
  ui_story_5017_50170601_25_dialog_content = "이 계절에는 벚꽃이 만개하니, 모두 아름다운 경치를 감상하기 위해\n일을 잠시 내려놓고, 나들이를 다니며 꽃을 감상하곤 한답니다.",
  ui_story_5017_50170601_26_dialog_content = "그것이 시간이 흘러 강부성의 전통이 된 것이지요.",
  ui_story_5017_50170601_27_dialog_content = "조금 더 깊은 뜻을 말씀드리자면... 봄은 한 해의 시작입니다.",
  ui_story_5017_50170601_28_dialog_content = "축제 기간에 신께 풍년을 기원하면서, 한 해를 평안하게 보내길 바라는 것입니다.",
  ui_story_5017_50170601_29_dialog_content = "그렇구나.",
  ui_story_5017_50170601_30_dialog_content = "운도의 벚꽃은 정말 아름답네. 확실히 느긋하게 즐길 필요가 있겠어!",
  ui_story_5017_50170601_31_dialog_content = "다만 현지인들에게는 벚꽃보다 축제 그 자체에 더 큰 의미가 있답니다.",
  ui_story_5017_50170601_32_dialog_content = "그럼 춘일제 기간엔 주로 어딜 가서 노는 게 좋나요?",
  ui_story_5017_50170601_33_dialog_content = "모처럼 좋을 때 왔으니까 즐거운 건 하나도 놓치고 싶지 않아요!",
  ui_story_5017_50170601_34_dialog_content = "어머... 노는 곳이라면 저는 잘 알지 못합니다만.",
  ui_story_5017_50170601_35_dialog_content = "사실 벌써 몇 년이나 운도의 「춘일제」에 참가하지 않았으니 말이지요.",
  ui_story_5017_50170601_36_dialog_content = "뭐? 린네는 운도의 무녀 아니었어?",
  ui_story_5017_50170601_37_dialog_content = "...저는 작년에야 비로소 무녀가 될 수 있었습니다.",
  ui_story_5017_50170601_38_dialog_content = "그전까지는 줄곧 <color=#FFB400>「본도」</color>에서 수행을 하고 있었지요.",
  ui_story_5017_50170601_39_dialog_content = "「본도」?",
  ui_story_5017_50170601_40_dialog_content = "네, 이 근방의 제도에서 가장 큰 섬이랍니다.",
  ui_story_5017_50170601_41_dialog_content = "운도를 포함한 작은 섬들은 모두 「본도」의 관할 하에 있습니다.",
  ui_story_5017_50170601_42_dialog_content = "아, 이해했어. 그럼 린네는 사실 「본도」 사람이었구나?",
  ui_story_5017_50170601_43_dialog_content = "그렇지는 않습니다.",
  ui_story_5017_50170601_44_dialog_content = "저는 운도 태생입니다...",
  ui_story_5017_50170601_45_dialog_content = "「본도」에 갔던 것은 무녀의 직을 계승하기 위한 수행을 위해서였습니다.",
  ui_story_5017_50170601_46_dialog_content = "우와, 힘들었겠네. 나도 수행한 적이 있으니까 알 수 있어!",
  ui_story_5017_50170601_47_dialog_content = "둘이 했던 수행이라는 건 전혀 다른 종류일 것 같은데 말이지...",
  ui_story_5017_50170601_48_dialog_content = "따라서 저는 지금의 「춘일제」에 대해서는 아는 바가 적습니다...",
  ui_story_5017_50170601_49_dialog_content = "도움을 드리지 못해 죄송합니다.",
  ui_story_5017_50170601_50_dialog_content = "괜찮아, 나도 있으니까!",
  ui_story_5017_50170601_51_dialog_content = "내 「운도 여행 가이드북」을 잊어버리면 곤란하지!",
  ui_story_5017_50170601_52_dialog_content = "......",
  ui_story_5017_50170601_53_dialog_content = "......",
  ui_story_5017_50170601_54_dialog_content = "아직도 갖고 있었구나...",
  ui_story_5017_50170601_55_dialog_content = "무시하지 말라고! 내용도 얼마나 자세한데!",
  ui_story_5017_50170601_56_dialog_content = "난 심심할 때마다 이걸 자주 읽었어!",
  ui_story_5017_50170601_57_dialog_content = "가이드북을 무슨 재미로 읽어?",
  ui_story_5017_50170601_58_dialog_content = "꽤 재미있거든! 그리고 민간전승을 소개하는 코너도 있어.",
  ui_story_5017_50170601_59_dialog_content = "민간전승?",
  ui_story_5017_50170601_60_dialog_content = "내가 몇 개 읽어줄게...",
  ui_story_5017_50170601_61_dialog_content = "「강부성 외곽의 어느 민가에는 사는 사람도 없고 소유자도 없다.」",
  ui_story_5017_50170601_62_dialog_content = "「하지만 그곳을 지나는 행인들은 가끔 집안에서 가랑잎 쓰는 소리를 듣게 된다...」",
  ui_story_5017_50170601_63_dialog_content = "어때, 어때?",
  ui_story_5017_50170601_64_dialog_content = "그런 괴담 얘기였냐...",
  ui_story_5017_50170601_65_dialog_content = "또 있어!",
  ui_story_5017_50170601_66_dialog_content = "「운도에는 옛사람이 만든 세 개의 보물이 있는데, 지금은 그 행방을 알 수 없다.」",
  ui_story_5017_50170601_67_dialog_content = "「마을 최고령 할머니의 말에 따르면, 그 보물들은 어떤 소원이든 이루어 준다고 한다...」",
  ui_story_5017_50170601_68_dialog_content = "그런 건 다 지어낸 얘기잖아!",
  ui_story_5017_50170601_69_dialog_content = "자, 자! 그다음이 내가 제일 좋아하는 이야기야!",
  ui_story_5017_50170601_70_dialog_content = "「수많은 적을 쓰러트린 검객은 유일무이한 칭호를 얻게 된다.」",
  ui_story_5017_50170601_71_dialog_content = "「그러나 운도 최강의 검객은 적을 베어 이름을 얻은 것이 아니다.」",
  ui_story_5017_50170601_72_dialog_content = "「그가 벤 것은 바로 귀신이다.」",
  ui_story_5017_50170601_73_dialog_content = "「그 검에는 수만 망령의 얼룩이 스며들어 있는데...」",
  ui_story_5017_50170601_74_dialog_content = "「그로 인해 그는 <color=#FFB400>명토의 유검</color>이라고 불리게 되었다.」",
  ui_story_5017_50170601_75_dialog_content = "<color=#e8d9bb>탁!</color>",
  ui_story_5017_50170601_76_dialog_content = "쉿──",
  ui_story_5017_50170601_77_dialog_content = "그 이름을 입에 올리면 안 됩니다.",
  ui_story_5017_50170601_78_dialog_content = "저도 곤란해지고, 손님들도 곤란해질 것입니다.",
  ui_story_5017_50170601_79_dialog_content = "응? 이 이름이 어쨌다고? 「운도 여행 가이드북」에도 쓰여 있는데...",
  ui_story_5017_50170601_80_dialog_content = "손님들은 객지에서 오셨겠군요.",
  ui_story_5017_50170601_81_dialog_content = "그 책은 오래전에 만들어진 겁니다...",
  ui_story_5017_50170601_82_dialog_content = "시간이 흘러 상황이 변했습니다. 세상이 바뀌었단 말입니다.",
  ui_story_5017_50170601_83_dialog_content = "그 이름만으로도 우리 목숨을 해칠 화를 불러올 수가 있습니다!",
  ui_story_5017_50170601_84_dialog_content = "아... 그래...?",
  ui_story_5017_50170601_85_dialog_content = "무녀님, 이 거리에서 당신을 받아주는 건 우리 가게뿐입니다.",
  ui_story_5017_50170601_86_dialog_content = "그렇다고 해서 제가 화를 자초하고 싶다는 뜻은 아닙니다.",
  ui_story_5017_50170601_87_dialog_content = "......",
  ui_story_5017_50170601_88_dialog_content = "알고 있습니다. 이만 물러가겠습니다.",
  ui_story_5017_50170601_89_dialog_content = "<color=#e8d9bb>쿵── 쿵── 쿵!</color>",
  ui_story_5017_50170601_90_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5017_50170601_91_dialog_content = "으아아악!",
  ui_story_5017_50170601_92_dialog_content = "쇼군님! 전 아무 상관도 없습니다! 아무것도 모릅니다!",
  ui_story_5017_50170601_93_dialog_content = "쇼군님?",
  ui_story_5017_50170601_94_dialog_content = "<color=#e8d9bb>쿵.</color>",
  ui_story_5017_50170601_95_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5017_50170601_96_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_5017_50170601_97_dialog_content = "그어어...",
  ui_story_5017_50170601_98_dialog_content = "끼에에엑!",
  ui_story_5017_50170601_99_dialog_content = "오니?!",
  ui_story_5017_50170601_100_dialog_content = "그럴 리가... 오니가 이곳에 나타날 리가 없습니다!",
  ui_story_5017_50170602_1_dialog_content = "성안에도 오니가 있다니...",
  ui_story_5017_50170602_2_dialog_content = "더는 지체할 수 없습니다. 즉시 본성으로 돌아가야 합니다!",
  ui_story_5017_50170602_3_dialog_content = "아까 본성으로 가야 된다고 한 게 설마 오니랑 관계가 있는 거였어?",
  ui_story_5017_50170602_4_dialog_content = "그렇습니다.",
  ui_story_5017_50170602_5_dialog_content = "본성에는 무녀에게 대를 이어 전해지는 「법기」...",
  ui_story_5017_50170602_6_dialog_content = "<color=#FFB400>「구름의 거울」</color>이 모셔져 있습니다.",
  ui_story_5017_50170602_7_dialog_content = "「구름의 거울」이 있으면 일거에 오니를 퇴치할 수 있습니다.",
  ui_story_5017_50170602_8_dialog_content = "무녀한테 계승되는 법기인데 왜 네가 안 가지고 본성에 두는 건데?",
  ui_story_5017_50170602_9_dialog_content = "구름의 거울은 「합하」께서 대신 보관하고 계신 것입니다.",
  ui_story_5017_50170602_10_dialog_content = "저는 무녀가 된 지 얼마 되지 않아, 아직 「구름의 거울」을 다룰 자격이 없습니다.",
  ui_story_5017_50170602_11_dialog_content = "「합하」라는 건...?",
  ui_story_5017_50170602_12_dialog_content = "이 강부성의 주인을 부르는 말입니다.",
  ui_story_5017_50170602_13_dialog_content = "이곳 사람들이 「쇼군」이라 일컫는 분이시지요.",
  ui_story_5017_50170602_14_dialog_content = "아! 방금 가게 주인도 놀랐을 때 「쇼군」을 외쳤어!",
  ui_story_5017_50170602_X14_dialog_content = "그렇습니다.",
  ui_story_5017_50170602_15_dialog_content = "(구름의 거울을 직접 만진 적은 없습니다만...)",
  ui_story_5017_50170602_16_dialog_content = "(지금 상황에서는 시험해 볼 수 밖에 없습니다...)",
  ui_story_5017_50170602_17_dialog_content = "(부디 합하께서 제 무모함을 용서해 주시기를...)",
  ui_story_5017_50170602_18_dialog_content = "그럼 우리도 같이 본성에 갈게!",
  ui_story_5017_50170602_19_dialog_content = "지금은 성안에도 오니가 있지? 너 혼자 갔다가 휘말리면 큰일이잖아.",
  ui_story_5017_50170602_20_dialog_content = "......",
  ui_story_5017_50170602_21_dialog_content = "알겠습니다. 이런 순간에도 애써 마다할 수는 없겠지요.",
  ui_story_5017_50170602_22_dialog_content = "감사합니다.",
  ui_story_5017_50170602_23_dialog_content = "바이스, 요우, 다들 괜찮지?",
  ui_story_5017_50170602_24_dialog_content = "응!",
  ui_story_5017_50170602_25_dialog_content = "앞부분은 잘 못 알아들었지만...",
  ui_story_5017_50170602_26_dialog_content = "아무튼 린네를 따라가면 되는 거잖아!",
  ui_story_5017_50170602_27_dialog_content = "어머, 요우는 이해력이 좋군요.",
  ui_story_5017_50170602_28_dialog_content = "에헷!",
  ui_story_5017_50170602_29_dialog_content = "본성은 이쪽입니다. 따라오십시오.",
  ui_story_5017_50170602_30_dialog_content = "PlayerName... 난 저 오니들이 어떻게 나타난 건지 좀 신경이 쓰여.",
  ui_story_5017_50170602_31_dialog_content = "뭔가 감응된 건 없었어?",
  ui_story_5017_50170602_32_dialog_content = "모르겠어. 놈들은 우리가 지금까지 봐왔던 어떤 것과도 달라.",
  ui_story_5017_50170602_33_dialog_content = "오니의 몸을 이루고 있는 게 루미나랑 비슷한 에너지라는 건 느껴져.",
  ui_story_5017_50170602_34_dialog_content = "근데 대체 어떤 힘이 그 에너지를 한데 모으고 있는 건지...\n어떤 의식이 놈들을 움직이는 건지는 전혀 모르겠어...",
  ui_story_5017_50170602_35_dialog_content = "어쩌면 내 인식에 제일 중요한 무언가가 부족하기 때문일지도 몰라.",
  ui_story_5017_50170602_36_dialog_content = "린네가 말하는 「영혼」이라는 걸 어떻게 이해해야 할지 난 잘 모르겠거든.",
  ui_story_5017_50170602_37_dialog_content = "그럼 이번에 있었던 전반적인 사건들은 어떻게 생각해?",
  ui_story_5017_50170602_38_dialog_content = "「스카이워커」의 알 수 없는 고장이나, 마을 사람들이 말한 「귀문」...",
  ui_story_5017_50170602_39_dialog_content = "그리고 지금 상황도 포함해서 말이야.",
  ui_story_5017_50170602_40_dialog_content = "지금까진 깊게 생각해 본 적 없었는데...",
  ui_story_5017_50170602_41_dialog_content = "다시 생각해 보면 우린 운도에 온 뒤로 계속 사건에 휘말리고 있는 것 같아...",
  ui_story_5017_50170602_42_dialog_content = "아무래도 이 모든 게 뒤에서 이어지고 있는 것 같은 느낌이 들어.",
  ui_story_5017_50170602_43_dialog_content = "난 마을 사람들이 한 말도 마음에 걸려.",
  ui_story_5017_50170602_44_dialog_content = "「천재지변이 아니라 인재다...」",
  ui_story_5017_50170602_45_dialog_content = "난 그 말은 그냥 겁주는 거라고 생각했는데...",
  ui_story_5017_50170602_46_dialog_content = "그 아메모리라는 닌자 기억해?",
  ui_story_5017_50170602_47_dialog_content = "응.",
  ui_story_5017_50170602_48_dialog_content = "오니는 사람을 해치고, 린네는 오니를 물리쳐.",
  ui_story_5017_50170602_49_dialog_content = "근데 아메모리는 사람이면서 린네를 죽이려고 했어...",
  ui_story_5017_50170602_50_dialog_content = "그럼 그 말은 설마...",
  ui_story_5017_50170602_51_dialog_content = "응...",
  ui_story_5017_50170602_52_dialog_content = "아메모리도 사실은 오니라는 거야?",
  ui_story_5017_50170602_53_dialog_content = "하아?",
  ui_story_5017_50170602_54_dialog_content = "...됐어!",
  ui_story_5017_50170602_55_dialog_content = "너한테 이런 말을 한 내가 바보라니까!",
  ui_story_5017_50170602_56_dialog_content = "에이, 그러지 말고!",
  ui_story_5017_50170602_57_dialog_content = "내가 못 알아들어도 하던 말은 끝까지 해줘야지!",
  ui_story_5017_50170602_58_dialog_content = "......",
  ui_story_5017_50170602_59_dialog_content = "어디까지나 내 추측일 뿐이야.",
  ui_story_5017_50170602_60_dialog_content = "왠지 이 사건의 이면에는 단순히 <color=#FFB400>「인간과 오니의 싸움」</color>만 있는 건 아닌 것 같아.",
  ui_story_5017_50170602_61_dialog_content = "그어어...",
  ui_story_5017_50170602_62_dialog_content = "으흑...",
  ui_story_5017_50170602_63_dialog_content = "아빠...",
  ui_story_5017_50170602_64_dialog_content = "쉿, 아직 우릴 못 찾았어.",
  ui_story_5017_50170602_65_dialog_content = "무서워...",
  ui_story_5017_50170602_66_dialog_content = "무서워할 거 없어. 아빠가 있잖아.",
  ui_story_5017_50170602_67_dialog_content = "왜 갑자기... 오니가 나타난 거야...?",
  ui_story_5017_50170602_68_dialog_content = "나쁜 녀석들을 혼내주러 온 거야.",
  ui_story_5017_50170602_69_dialog_content = "나...나 나쁜 짓 안 했지?",
  ui_story_5017_50170602_70_dialog_content = "당연하지, 넌 착한 애잖아.",
  ui_story_5017_50170602_71_dialog_content = "아빠도 나쁜 짓 안 했지?",
  ui_story_5017_50170602_72_dialog_content = "......",
  ui_story_5017_50170602_73_dialog_content = "그래.",
  ui_story_5017_50170602_74_dialog_content = "그러니까 무서워할 것 없어. 괜찮아.",
  ui_story_5017_50170602_75_dialog_content = "그럼 왜 숨는 건데?",
  ui_story_5017_50170602_76_dialog_content = "그건...",
  ui_story_5017_50170602_77_dialog_content = "어떤 오니는 눈이 없거든. 우릴 잘못 보면 큰일이잖아.",
  ui_story_5017_50170602_78_dialog_content = "괜찮아, 그럼 내가 「나랑 아빠는 착한 사람이야!」라고 외칠게!",
  ui_story_5017_50170602_79_dialog_content = "안 돼! 오니가 네 말을 들을 것 같아?",
  ui_story_5017_50170602_80_dialog_content = "나쁜 사람은 전부 자기가 착한 사람이라 한다고.",
  ui_story_5017_50170602_81_dialog_content = "그...그럼 이제 어떻게 해야 돼?",
  ui_story_5017_50170602_82_dialog_content = "눈 없는 오니가 나타나면 이 아빠가 혼내주마!",
  ui_story_5017_50170602_83_dialog_content = "아빠는 오니랑 싸울 수 있어?",
  ui_story_5017_50170602_84_dialog_content = "없지.",
  ui_story_5017_50170602_85_dialog_content = "날 때부터 오니랑 싸울 수 있는 사람은 없어.",
  ui_story_5017_50170602_86_dialog_content = "그래도... 한 번 싸워보면 할 수 있게 될 거야.",
  ui_story_5017_50170602_87_dialog_content = "응!",
  ui_story_5017_50170602_88_dialog_content = "근처에 뭔가 칼이나 몽둥이 같은 게 있는지 찾아볼래?",
  ui_story_5017_50170602_89_dialog_content = "아빠한텐 무기가 필요해.",
  ui_story_5017_50170602_90_dialog_content = "응...",
  ui_story_5017_50170602_91_dialog_content = "<color=#e8d9bb>부스럭부스럭... 부스럭부스럭...</color>",
  ui_story_5017_50170602_92_dialog_content = "아빠, 못 찾겠어...",
  ui_story_5017_50170602_93_dialog_content = "사과사탕 아직 남았는데 이걸론 안 될까?",
  ui_story_5017_50170602_94_dialog_content = "사과사탕은 됐어... 아빠는 주먹으로 싸울게...",
  ui_story_5017_50170602_95_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5017_50170602_96_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5017_50170602_97_dialog_content = "아, 아빠...",
  ui_story_5017_50170602_98_dialog_content = "괜찮아. 뒤에 숨어 있어.",
  ui_story_5017_50170602_99_dialog_content = "<color=#e8d9bb>콰아아앙!</color>",
  ui_story_5017_50170602_100_dialog_content = "아빠가 흠씬 혼내줄 테니까!",
  ui_story_5017_50170602_101_dialog_content = "<color=#e8d9bb>콰아아앙──!</color>",
  ui_story_5017_50170602_102_dialog_content = "구어어...",
  ui_story_5017_50170602_103_dialog_content = "뭐야?!",
  ui_story_5017_50170602_104_dialog_content = "우와... 멋있는 누나다!",
  ui_story_5017_50170602_105_dialog_content = "여기 아직 평민이 있군.",
  ui_story_5017_50170602_106_dialog_content = "저들을 데려다주시오.",
  ui_story_5017_50170602_107_dialog_content = "예!",
  ui_story_5017_50170602_108_dialog_content = "자, 같이 갑시다.",
  ui_story_5017_50170602_109_dialog_content = "어라?",
  ui_story_5017_50170602_110_dialog_content = "아저씨, 빙수 가게 사장님 아냐?",
  ui_story_5017_50170602_111_dialog_content = "목소리가 비슷해.",
  ui_story_5017_50170602_112_dialog_content = "허허, 말 잘 들으면 이따가 아저씨가 빙수 한 그릇 주마.",
  ui_story_5017_50170602_113_dialog_content = "자네들...",
  ui_story_5017_50170602_114_dialog_content = "재봉소 아저씨... 장난감 가게 형씨... 게다가 생선가게 고우 군까지...",
  ui_story_5017_50170602_115_dialog_content = "왜 다들 무기를 들고 있어? 당신들 설마...",
  ui_story_5017_50170602_116_dialog_content = "자넨 저 「취설각」에 앉아만 있는 쇼군이 강부성을 지켜줄 거라 생각하나?",
  ui_story_5017_50170602_117_dialog_content = "자길 지킬 수 있는 건 자신뿐일세.",
  ui_story_5017_50170602_118_dialog_content = "그 평민들은?",
  ui_story_5017_50170602_119_dialog_content = "이미 안전한 곳으로 보냈습니다.",
  ui_story_5017_50170602_120_dialog_content = "다만...",
  ui_story_5017_50170602_121_dialog_content = "이대로 사태가 커진다면, 저희가 강부성의 모든 백성을 지킬 순 없을 겁니다.",
  ui_story_5017_50170602_122_dialog_content = "알고 있소.",
  ui_story_5017_50170602_123_dialog_content = "그리 되기 전에 소생이 모든 것을 끝내리다.",
  ui_story_5017_50170602_124_dialog_content = "반드시... <color=#FFB400>무녀</color>를 죽일 것이오.",
  ui_story_5017_50170602_125_dialog_content = "무녀 말입니까...",
  ui_story_5017_50170602_126_dialog_content = "하지만 지금은 성안에서 오니가 날뛰고 있습니다.",
  ui_story_5017_50170602_127_dialog_content = "조급하게 움직이시면 안 됩니다...",
  ui_story_5017_50170602_128_dialog_content = "다른 선택지는 없소.",
  ui_story_5017_50170602_129_dialog_content = "그대 말처럼 이대로 사태를 키울 수는 없으니 말이오.",
  ui_story_5017_50170602_130_dialog_content = "하지만 당신의 안위가 더 중요합니다!",
  ui_story_5017_50170602_131_dialog_content = "우린 당신이 필요합니다...",
  ui_story_5017_50170602_132_dialog_content = "<color=#FFB400>총통</color>님...",
  ui_story_5017_50170602_133_dialog_content = "그 호칭은 쓰지 말라 하지 않았는가!",
  ui_story_5017_50170602_134_dialog_content = "<color=#e8d9bb>파사삭──!</color>",
  ui_story_5017_50170602_135_dialog_content = "!!!",
  ui_story_5017_50170602_136_dialog_content = "(대, 대나무가...)",
  ui_story_5017_50170602_137_dialog_content = "그대들의 총통은 단 한 분뿐이외다!",
  ui_story_5017_50170602_138_dialog_content = "총통께선 반드시 살아계실 것이니 말이오!",
  ui_story_5017_50170602_139_dialog_content = "...알겠습니다, 아메모리 님.",
  ui_story_5017_50170602_140_dialog_content = "(아메모리 님께서... 저토록 화를 내실 줄이야.)",
  ui_story_5017_50170602_141_dialog_content = "총통께선 소생에게 무녀를 죽이라 말씀하셨소.",
  ui_story_5017_50170602_142_dialog_content = "총통의 말씀은 반드시 옳은 것이오.",
  ui_story_5017_50170602_143_dialog_content = "소생은 그분의 말씀에 따라 반드시 행할 것이오.",
  ui_story_5017_50170602_144_dialog_content = "하지만 아메모리 님... 정말 무녀를 죽이면 모든 게 해결되겠습니까?",
  ui_story_5017_50170602_145_dialog_content = "몇 년 후면 놈들은 또 새로운 무녀를 보낼 것입니다.",
  ui_story_5017_50170602_146_dialog_content = "그땐 내가 다시 베어버리면 그만이오.",
  ui_story_5017_50170602_147_dialog_content = "우린 그 대가를 감당할 힘이 없습니다!",
  ui_story_5017_50170602_148_dialog_content = "지난번... 우리는 이미 <color=#FFB400>그분</color>을 잃었습니다.",
  ui_story_5017_50170602_149_dialog_content = "만약 이번에도 또...",
  ui_story_5017_50170602_150_dialog_content = "소생은 <color=#FFB400>그분</color>이 아니오.",
  ui_story_5017_50170602_151_dialog_content = "그리고 지금도 그때와는 다르오.",
  ui_story_5017_50170602_152_dialog_content = "아메모리 님...",
  ui_story_5017_50170602_153_dialog_content = "그만하면 됐소. 사카이 거리에서 소생을 기다리시오.",
  ui_story_5017_50170602_154_dialog_content = "「붉은 꽃 꺾어 님에게 주니──」",
  ui_story_5017_50170602_155_dialog_content = "「꽃잎은 옥설 위에 떨어지네.」",
  ui_story_5017_50170602_156_dialog_content = "......",
  ui_story_5017_50170602_157_dialog_content = "또 너야?!",
  ui_story_5017_50170602_158_dialog_content = "막아! 녀석이 노리는 건 린네야!",
  ui_story_5017_50170602_159_dialog_content = "오늘 무녀는 반드시 죽는다.",
  ui_story_5017_50170701_1_dialog_content = "꼬맹이! 아, 아니, 아메모리!",
  ui_story_5017_50170701_2_dialog_content = "넌 왜 린네를 노리는 거야?!",
  ui_story_5017_50170701_3_dialog_content = "대체 이유가 뭐냐고!",
  ui_story_5017_50170701_4_dialog_content = "그리고 넌 정말 날 아는 거야...?",
  ui_story_5017_50170701_5_dialog_content = "뭐야, 왜 또 도망가는 건데?!",
  ui_story_5017_50170701_6_dialog_content = "린네, 조심해!",
  ui_story_5017_50170701_7_dialog_content = "닌자 나리, 다치셨군요.",
  ui_story_5017_50170701_8_dialog_content = "......",
  ui_story_5017_50170701_9_dialog_content = "저는 지금 급한 일이 있습니다. 당신도 가서 상처부터 치료하는 것이 어떠실지요.",
  ui_story_5017_50170701_10_dialog_content = "소생도 급한 일이 있소이다.",
  ui_story_5017_50170701_11_dialog_content = "그러니 지금 당장 죽어줘야겠소.",
  ui_story_5017_50170701_12_dialog_content = "또 오니들이 잔뜩 오고 있어!",
  ui_story_5017_50170701_13_dialog_content = "어느 쪽부터 상대하지?",
  ui_story_5017_50170701_14_dialog_content = "아메모리, 저번처럼 휴전하지 않을래?",
  ui_story_5017_50170701_15_dialog_content = "오니는 소생이 알 바가 아니오.",
  ui_story_5017_50170701_16_dialog_content = "소생은 무녀의 목숨만을 원할 뿐이오.",
  ui_story_5017_50170701_17_dialog_content = "PlayerName, 저 녀석 좀 말릴 방법 없어?",
  ui_story_5017_50170701_18_dialog_content = "이래가지고는 오니랑 싸울 수도 없겠어!",
  ui_story_5017_50170701_19_dialog_content = "지금 생각하고 있다고! 내가 멍하니만 있는 줄 알았어?!",
  ui_story_5017_50170701_20_dialog_content = "일단 오른쪽부터...",
  ui_story_5017_50170701_21_dialog_content = "!!!",
  ui_story_5017_50170701_22_dialog_content = "잠깐만, 뭔가 근처에 있어!",
  ui_story_5017_50170701_23_dialog_content = "주변엔 온통 오니뿐인데 또 뭐가 있다는 건데?",
  ui_story_5017_50170701_24_dialog_content = "지금 있는 오니들보다 훨씬 강해!",
  ui_story_5017_50170701_25_dialog_content = "린네, 그리고 아메모리... 그쪽도 얼른 피해!",
  ui_story_5017_50170701_26_dialog_content = "이런!",
  ui_story_5017_50170701_27_dialog_content = "뭐냐...",
  ui_story_5017_50170701_28_dialog_content = "방해하지 마라.",
  ui_story_5017_50170701_29_dialog_content = "...?!",
  ui_story_5017_50170701_30_dialog_content = "명토의... 유검...",
  ui_story_5017_50170701_31_dialog_content = "<size=45>명토의... 유검──!</size>",
  ui_story_5017_50170701_32_dialog_content = "저 녀석... 말을 하는데?",
  ui_story_5017_50170701_33_dialog_content = "그렇습니다...",
  ui_story_5017_50170701_34_dialog_content = "이토록 흉악한 「악귀」를 부르다니...",
  ui_story_5017_50170701_35_dialog_content = "이번엔 정말 보통 일이 아니로군요.",
  ui_story_5017_50170701_36_dialog_content = "「악귀」? 다른 오니랑 다른 건가요?",
  ui_story_5017_50170701_37_dialog_content = "죽음으로도 사라지지 않는 강한 원념을 가진 영혼만이 악귀가 되는 것입니다.",
  ui_story_5017_50170701_38_dialog_content = "보통의 오니보다 더 강한 음기를 지니고, 형태를 이룬 후엔 지극히 강한 힘을 얻게 되지요...",
  ui_story_5017_50170701_39_dialog_content = "그럼 녀석이 말을 할 수 있는 것도...",
  ui_story_5017_50170701_40_dialog_content = "그렇습니다. 원념이 잔류하는 의식에 머물면서,\n영혼과 인간 세상의 마지막 연결고리가 되고 있는 것입니다.",
  ui_story_5017_50170701_41_dialog_content = "아마 「명토의 유검」이라는 이름이... 저 악귀에게 특별한 의미를 가지고 있는 것이겠지요.",
  ui_story_5017_50170701_42_dialog_content = "그어어... 크아아!",
  ui_story_5017_50170701_43_dialog_content = "명토의... 유검...",
  ui_story_5017_50170701_44_dialog_content = "알고... 있나...",
  ui_story_5017_50170701_45_dialog_content = "이런, 우리 쪽으로 온다!",
  ui_story_5017_50170701_46_dialog_content = "흐아압!",
  ui_story_5017_50170701_47_dialog_content = "방자한 녀석, 이거나 받...",
  ui_story_5017_50170701_48_dialog_content = "요우!",
  ui_story_5017_50170701_49_dialog_content = "쿨럭, 쿨럭...",
  ui_story_5017_50170701_50_dialog_content = "걱정 마, 괜찮으니까...",
  ui_story_5017_50170701_51_dialog_content = "뒤를 봐!",
  ui_story_5017_50170701_52_dialog_content = "뭐?",
  ui_story_5017_50170701_53_dialog_content = "요우, 어서 피하세요.",
  ui_story_5017_50170701_54_dialog_content = "우앗, 린네가 날 구해줬구나!",
  ui_story_5017_50170701_55_dialog_content = "기뻐하기는 아직 이릅니다.",
  ui_story_5017_50170701_56_dialog_content = "지금과 같은 상황에서 악귀에 맞서야 한다면, 저도 자신은 없으니 말이지요...",
  ui_story_5017_50170702_1_dialog_content = "구어어...",
  ui_story_5017_50170702_2_dialog_content = "콜록콜록... 콜록...",
  ui_story_5017_50170702_3_dialog_content = "우와... 이 녀석, 벽까지 부술 정도라니...",
  ui_story_5017_50170702_4_dialog_content = "이대로 계속 싸울 수는 없습니다.",
  ui_story_5017_50170702_5_dialog_content = "응? 린네, 오니를 퇴치할 거 아니었어?",
  ui_story_5017_50170702_6_dialog_content = "여러분이 이대로 죽어가는 것을 보고 싶진 않습니다.",
  ui_story_5017_50170702_7_dialog_content = "오니 무리가 점점 더 강성해지는 것이 느껴집니다.",
  ui_story_5017_50170702_8_dialog_content = "지금 물러나지 않으면 기회는 없습니다.",
  ui_story_5017_50170702_9_dialog_content = "응, 나도 느껴져!",
  ui_story_5017_50170702_10_dialog_content = "커다란 먹구름이... 땅을 조금씩 뒤덮고 있는 느낌이야...",
  ui_story_5017_50170702_11_dialog_content = "그, 근데 도망친다고 해도 어디로...",
  ui_story_5017_50170702_12_dialog_content = "후우...",
  ui_story_5017_50170702_13_dialog_content = "어머, 닌자 나리...",
  ui_story_5017_50170702_14_dialog_content = "오니와 싸우는 것은 어려우신가요.",
  ui_story_5017_50170702_15_dialog_content = "......",
  ui_story_5017_50170702_16_dialog_content = "아니면 계속 저를 죽일 생각만 하시는 것인지요.",
  ui_story_5017_50170702_17_dialog_content = "물론이지.",
  ui_story_5017_50170702_18_dialog_content = "저를 죽이면 당신은 저 오니들을 상대할 수 없을 것입니다만.",
  ui_story_5017_50170702_19_dialog_content = "상관없다.",
  ui_story_5017_50170702_20_dialog_content = "죽을 각오는 언제나 하고 있으니.",
  ui_story_5017_50170702_21_dialog_content = "어머, 저와 황천의 길동무가 되어 주시려는 것인지요.",
  ui_story_5017_50170702_22_dialog_content = "그거 정말 기쁜 일이네요.",
  ui_story_5017_50170702_23_dialog_content = "사후에 제가 당신을 모시고, 함께 악귀가 되면...",
  ui_story_5017_50170702_24_dialog_content = "그때도 저를 죽이실 마음이 있으실지 꼭 제 눈으로 확인해 보고 싶군요.",
  ui_story_5017_50170702_25_dialog_content = "......",
  ui_story_5017_50170702_26_dialog_content = "아메모리! 린네한테 다가오지 마!",
  ui_story_5017_50170702_27_dialog_content = "지금 상황만으로도 충분히 골치가 아프다고!",
  ui_story_5017_50170702_28_dialog_content = "둘이 계속 싸우다간 우린 다 여기서 죽어!",
  ui_story_5017_50170702_29_dialog_content = "그어어...",
  ui_story_5017_50170702_30_dialog_content = "흥...",
  ui_story_5017_50170702_31_dialog_content = "뭐, 뭐야? 도망간 거야?",
  ui_story_5017_50170702_32_dialog_content = "우리도 멍하니 있을 때가 아냐!",
  ui_story_5017_50170702_33_dialog_content = "이쪽이야! 날 따라와!",
  ui_story_5017_50170702_34_dialog_content = "왼쪽은 막혔어. 앞으로 가!",
  ui_story_5017_50170702_35_dialog_content = "<color=#e8d9bb>타탁타탁...</color>",
  ui_story_5017_50170702_36_dialog_content = "이런, 앞에서도 오니가 오고 있어...",
  ui_story_5017_50170702_37_dialog_content = "오른쪽으로!",
  ui_story_5017_50170702_38_dialog_content = "<color=#e8d9bb>타탁타탁...</color>",
  ui_story_5017_50170702_39_dialog_content = "대단하네! PlayerName, 오니가 있는 곳을 느낄 수 있는 거야?",
  ui_story_5017_50170702_40_dialog_content = "그런 건 아냐. 그냥 네가 맨날 말하는 「직감」인 거지!",
  ui_story_5017_50170702_41_dialog_content = "우와, 그럼 나도 더 노력하면 「직감술」을 터득할 수 있으려나?",
  ui_story_5017_50170702_42_dialog_content = "자꾸 쓸데없는 말하면 집중이 안 된다고!",
  ui_story_5017_50170702_43_dialog_content = "아하하, 미안해!",
  ui_story_5017_50170702_44_dialog_content = "이 앞 모퉁이에 오니가 있어, 조심해!",
  ui_story_5017_50170702_45_dialog_content = "그어어...",
  ui_story_5017_50170702_46_dialog_content = "내가 해치울게!",
  ui_story_5017_50170702_47_dialog_content = "받아라──",
  ui_story_5017_50170702_48_dialog_content = "아앗, 아메모리, 아직도 있었어?",
  ui_story_5017_50170702_49_dialog_content = "뒤, 뒤쪽!",
  ui_story_5017_50170702_50_dialog_content = "마찬가지이외다.",
  ui_story_5017_50170702_51_dialog_content = "야! 조심해! 내가 맞을 뻔했잖아!",
  ui_story_5017_50170702_52_dialog_content = "피할 것이라 생각했소.",
  ui_story_5017_50170702_53_dialog_content = "으으... 아프잖아!",
  ui_story_5017_50170702_54_dialog_content = "뭐 하는 거야?!",
  ui_story_5017_50170702_55_dialog_content = "그대가 스스로 부딪힌 것이잖소.",
  ui_story_5017_50170702_56_dialog_content = "나 참, 우린 지금 같이 싸우고 있잖아!",
  ui_story_5017_50170702_57_dialog_content = "그럼 호흡을 좀 맞춰줘!",
  ui_story_5017_50170702_58_dialog_content = "그대와 함께 싸우겠다고 한 적은 없소이다.",
  ui_story_5017_50170702_59_dialog_content = "말싸움은 나중에 해!",
  ui_story_5017_50170702_60_dialog_content = "적어도 여기선 좀 참아!",
  ui_story_5017_50170702_61_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5017_50170702_62_dialog_content = "앗, 또 저 녀석이야! 도망쳐!",
  ui_story_5017_50170702_63_dialog_content = "참, 미리 말해 두는데, 같이 도망가는 건 좋지만 린네한테는 손대지 마!",
  ui_story_5017_50170702_64_dialog_content = "그대의 생각 따위는 소생과는 관계없소.",
  ui_story_5017_50170702_65_dialog_content = "너 정말...",
  ui_story_5017_50170702_66_dialog_content = "말이 안 통하는 녀석이네!",
  ui_story_5017_50170702_67_dialog_content = "으앗, 밀지 마!",
  ui_story_5017_50170702_68_dialog_content = "좀 떨어지라고!",
  ui_story_5017_50170702_69_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_5017_50170702_70_dialog_content = "<color=#e8d9bb>찰랑──!</color>",
  ui_story_5017_50170702_71_dialog_content = "!!!",
  ui_story_5017_50170702_72_dialog_content = "잠깐만, 나 물건 떨어트렸어!",
  ui_story_5017_50170702_73_dialog_content = "어라? 왜 옆에 하나가 더...",
  ui_story_5017_50170702_74_dialog_content = "?!",
  ui_story_5017_50170702_75_dialog_content = "뭐야... 그거 네 거야?",
  ui_story_5017_50170702_76_dialog_content = "역시 우린 아는 사이였구나! 그거 어디서 났어?",
  ui_story_5017_50170702_77_dialog_content = "나머지 반쪽을... 그대가 가지고 있었다니...!",
  ui_story_5017_50170702_78_dialog_content = "이것이 다시 만났다는 것은...",
  ui_story_5017_50170702_79_dialog_content = "야! 네 것만 주웠으면 됐지! 내 건 왜 뺏으려고 하는데?!",
  ui_story_5017_50170702_80_dialog_content = "휴... 뺏길 뻔했네...",
  ui_story_5017_50170702_81_dialog_content = "이리 주시오.",
  ui_story_5017_50170702_82_dialog_content = "내가 왜?! 이건 내 거야!",
  ui_story_5017_50170702_83_dialog_content = "내놓으란 말이오!",
  ui_story_5017_50170702_84_dialog_content = "뭐...뭐야? 왜 소리를 질러?",
  ui_story_5017_50170702_85_dialog_content = "우린 지금 도망치는 중이잖아. 괜한 말썽 피우지 마! 뭐가 중요한지 모르겠어?",
  ui_story_5017_50170702_86_dialog_content = "모르는 건 오히려 그대요! 그것이야말로 더 중요한 일이란 말이오!",
  ui_story_5017_50170702_87_dialog_content = "PlayerName, 어느 쪽이야?",
  ui_story_5017_50170702_88_dialog_content = "뒤쪽의 오니가 점점 더 가까워지고 있어!",
  ui_story_5017_50170702_89_dialog_content = "곤란한데... 어느 쪽이든 전부 오니가 있어... 사방이 온통 적이야...",
  ui_story_5017_50170702_90_dialog_content = "아무래도 더는 갈 곳이 없을 것 같아...",
  ui_story_5017_50170702_91_dialog_content = "말도 안 돼... 다른 방법은 없는 거야?",
  ui_story_5017_50170702_92_dialog_content = "더는 갈 길이 없다면 여기서 상대하는 수밖에 없어.",
  ui_story_5017_50170702_93_dialog_content = "지금 생각하는 중이야...",
  ui_story_5017_50170702_94_dialog_content = "더는 갈 길이 없다면 여기서 상대하는 수밖에 없습니다...",
  ui_story_5017_50170702_95_dialog_content = "저기! 도와줘!",
  ui_story_5017_50170702_96_dialog_content = "아메모리가 내 물건을 뺏으려고 해!",
  ui_story_5017_50170702_97_dialog_content = "뭐야? 지금 이런 상황에서 우리끼리 또 싸워야겠어?!",
  ui_story_5017_50170702_98_dialog_content = "무슨 물건인데? 중요한 거야?",
  ui_story_5017_50170702_99_dialog_content = "내가 가지고 있던 그 옥 말이야!",
  ui_story_5017_50170702_100_dialog_content = "아메모리가... 말도 없이 뺏으려고만 해!",
  ui_story_5017_50170702_101_dialog_content = "곧 오니들이 몰려올 거야!",
  ui_story_5017_50170702_102_dialog_content = "이젠 도망갈 길도 없어. 정면으로 맞서도... 어쩌면 당해내지 못할지도 몰라.",
  ui_story_5017_50170702_103_dialog_content = "그 옥이 아무리 중요한 물건이라고 해도, 여길 살아서 나가지 못하면 의미가 없다고!",
  ui_story_5017_50170702_104_dialog_content = "......",
  ui_story_5017_50170702_105_dialog_content = "...됐소이다.",
  ui_story_5017_50170702_106_dialog_content = "휴, 이제야 놨네!",
  ui_story_5017_50170702_107_dialog_content = "PlayerName, 너 말 잘하는구나!",
  ui_story_5017_50170702_108_dialog_content = "그대들은 처마 위로 올라가시오.",
  ui_story_5017_50170702_109_dialog_content = "어서!",
  ui_story_5017_50170702_110_dialog_content = "뭐? 이번엔 뭘 하려고...",
  ui_story_5017_50170702_111_dialog_content = "!!!",
  ui_story_5017_50170702_112_dialog_content = "그래! 그런 방법이 있었어!",
  ui_story_5017_50170702_113_dialog_content = "아직 지붕 위에는 오니가 없잖아!",
  ui_story_5017_50170702_114_dialog_content = "오호!",
  ui_story_5017_50170702_115_dialog_content = "그럼... 너 우릴 도와주겠다는 거야?",
  ui_story_5017_50170702_116_dialog_content = "그대가 그걸 소생에게 주지 않겠다면...",
  ui_story_5017_50170702_117_dialog_content = "지금은 어떻게든 살아남도록 하시오.",
  ui_story_5017_50170702_118_dialog_content = "흥, 난 대협객이라구. 그럼 일단...",
  ui_story_5017_50170702_119_dialog_content = "하나, 둘...",
  ui_story_5017_50170702_120_dialog_content = "셋!",
  ui_story_5017_50170702_121_dialog_content = "우와아아아악!",
  ui_story_5017_50170702_122_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5017_50170702_123_dialog_content = "아...아파라...",
  ui_story_5017_50170702_124_dialog_content = "지붕도 직접 못 오르고, PlayerName 너 훈련이 부족하구나.",
  ui_story_5017_50170702_125_dialog_content = "요우한테 힘을 쓰게 만들고 말이야.",
  ui_story_5017_50170702_126_dialog_content = "후훗.",
  ui_story_5017_50170702_127_dialog_content = "PlayerName 님, 아프신가요?",
  ui_story_5017_50170702_128_dialog_content = "일어나시지요. 제가 부축해 드리겠습니다.",
  ui_story_5017_50170702_129_dialog_content = "으으... 고마워!",
  ui_story_5017_50170702_130_dialog_content = "다들 린네처럼 자상했으면 참 좋겠는데 말이지...",
  ui_story_5017_50170702_131_dialog_content = "야, 누구 들으라고 하는 얘기야?",
  ui_story_5017_50170702_132_dialog_content = "어라, 요우랑 아메모리는? 왜 안 올라오는데?",
  ui_story_5017_50170702_133_dialog_content = "아메모리, 먼저 올라가!",
  ui_story_5017_50170702_134_dialog_content = "꾸물거리다간 오니한테 잡힐 거라고!",
  ui_story_5017_50170702_135_dialog_content = "그대 먼저 가시오.",
  ui_story_5017_50170702_136_dialog_content = "정말! 왜 또 이럴 때는 사양하는 건데!",
  ui_story_5017_50170702_137_dialog_content = "벽을 오르는 것은 소생이 더 빠르오.",
  ui_story_5017_50170702_138_dialog_content = "소생과 그대 모두 살아남아야 하오.",
  ui_story_5017_50170702_139_dialog_content = "알았어, 그럼 같이 올라가!",
  ui_story_5017_50170702_140_dialog_content = "<color=#e8d9bb>탁, 탁, 탁...</color>",
  ui_story_5017_50170702_141_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5017_50170702_142_dialog_content = "아메모리!",
  ui_story_5017_50170702_143_dialog_content = "괜찮소...",
  ui_story_5017_50170702_144_dialog_content = "어서 올라가!",
  ui_story_5017_50170702_145_dialog_content = "앗...!",
  ui_story_5017_50170702_146_dialog_content = "왜 그러시오?",
  ui_story_5017_50170702_147_dialog_content = "오니가 내 발을 잡았어!",
  ui_story_5017_50170702_148_dialog_content = "소생이 돕겠소.",
  ui_story_5017_50170702_149_dialog_content = "너부터 조심해!",
  ui_story_5017_50170702_150_dialog_content = "큭...",
  ui_story_5017_50170702_151_dialog_content = "뭔가 방법을 찾아볼게!",
  ui_story_5017_50170702_152_dialog_content = "됐으니 어서 가시오!",
  ui_story_5017_50170702_153_dialog_content = "서둘러야 되는 건 너라고! 그래서 내가 먼저 올라가라고 했잖아!",
  ui_story_5017_50170702_154_dialog_content = "정말 귀찮네. 그러니까 내가 사양하지 말라고 했는데!",
  ui_story_5017_50170702_155_dialog_content = "으아아아앗!",
  ui_story_5017_50170702_156_dialog_content = "!!!",
  ui_story_5017_50170702_157_dialog_content = "괜찮소?",
  ui_story_5017_50170702_158_dialog_content = "괘, 괜찮아...",
  ui_story_5017_50170702_159_dialog_content = "......",
  ui_story_5017_50170702_160_dialog_content = "소생의 어깨를 잡으시오.",
  ui_story_5017_50170702_161_dialog_content = "너...",
  ui_story_5017_50170702_162_dialog_content = "뭘 어쩌려고 그래? 너무 무리하는 거 아냐?!",
  ui_story_5017_50170702_163_dialog_content = "이제 그대의 목숨은 그대만의 것이 아니오.",
  ui_story_5017_50170702_164_dialog_content = "말했잖소. 우린 반드시 함께 살아남아야 하오.",
  ui_story_5017_50170702_165_dialog_content = "이러다간 같이 죽을 뿐이라구!",
  ui_story_5017_50170702_166_dialog_content = "어라? 방금 그건...",
  ui_story_5017_50170702_167_dialog_content = "린네! 왜 내려온 거야?!",
  ui_story_5017_50170702_168_dialog_content = "무녀?!",
  ui_story_5017_50170702_169_dialog_content = "무슨 짓이냐... 이 틈에 소생을 처리할 셈인가?",
  ui_story_5017_50170702_170_dialog_content = "후훗.",
  ui_story_5017_50170702_171_dialog_content = "...?!",
  ui_story_5017_50170702_172_dialog_content = "어째서...",
  ui_story_5017_50170702_173_dialog_content = "이유가 필요합니까? 제가 돕는 것은 당신만이 아닙니다.",
  ui_story_5017_50170702_174_dialog_content = "게다가 저는 당신을 적으로 여겨본 적도 없습니다.",
  ui_story_5017_50170702_175_dialog_content = "제 적은 <color=#FFB400>오직 「오니」뿐</color>입니다.",
  ui_story_5017_50170801_1_dialog_content = "둘 다 일단 올라와!",
  ui_story_5017_50170801_2_dialog_content = "안 돼! 린네가 아직 밑에 있어!",
  ui_story_5017_50170801_3_dialog_content = "내려가서 도와야 해!",
  ui_story_5017_50170801_4_dialog_content = "일단 진정해!",
  ui_story_5017_50170801_5_dialog_content = "아래쪽은 오니 투성이야! 지금 가 봤자 죽으러 가는 거나 똑같다고!",
  ui_story_5017_50170801_6_dialog_content = "그럼 어떡해?! 이대로 보고만 있으라고?!",
  ui_story_5017_50170801_7_dialog_content = "PlayerName, 뭔가 다른 방법은 없어?",
  ui_story_5017_50170801_8_dialog_content = "지금 생각하고 있어!",
  ui_story_5017_50170801_9_dialog_content = "(린네, 내 목소리 들려?)",
  ui_story_5017_50170801_10_dialog_content = "(아래쪽의 에너지가 뒤섞여서 상황이 제대로 파악되질 않아...)",
  ui_story_5017_50170801_11_dialog_content = "(린네, 대답해줄 수 있겠어?)",
  ui_story_5017_50170801_12_dialog_content = "<color=#e8d9bb>스으윽!</color>",
  ui_story_5017_50170801_13_dialog_content = "?!",
  ui_story_5017_50170801_14_dialog_content = "<color=#e8d9bb>휘익!</color>",
  ui_story_5017_50170801_15_dialog_content = "흐이익!",
  ui_story_5017_50170801_16_dialog_content = "방금 뭐가 휙 지나갔어!",
  ui_story_5017_50170801_17_dialog_content = "나도 봤어!",
  ui_story_5017_50170801_18_dialog_content = "너희도 드디어 봤구나!",
  ui_story_5017_50170801_19_dialog_content = "PlayerName, 방금 그거 뭐야?",
  ui_story_5017_50170801_20_dialog_content = "나도 몰라...",
  ui_story_5017_50170801_21_dialog_content = "너도 모른다고?",
  ui_story_5017_50170801_22_dialog_content = "그래.",
  ui_story_5017_50170801_23_dialog_content = "근데 여기까지 오는 동안 벌써 두 번이나 봤어...",
  ui_story_5017_50170801_24_dialog_content = "그럼 다시 강부성으로 출발해 볼까요?",
  ui_story_5017_50170801_25_dialog_content = "응!",
  ui_story_5017_50170801_26_dialog_content = "<color=#e8d9bb>스으윽!</color>",
  ui_story_5017_50170801_27_dialog_content = "흐이익!",
  ui_story_5017_50170801_28_dialog_content = "저희도 주변을 한번 둘러볼까요?",
  ui_story_5017_50170801_29_dialog_content = "그래...",
  ui_story_5017_50170801_30_dialog_content = "<color=#e8d9bb>휘익!</color>",
  ui_story_5017_50170801_31_dialog_content = "?!",
  ui_story_5017_50170801_32_dialog_content = "설마 진짜 「귀신」인가...",
  ui_story_5017_50170801_33_dialog_content = "<color=#e8d9bb>후── 후── 후──</color>",
  ui_story_5017_50170801_34_dialog_content = "후!",
  ui_story_5017_50170801_35_dialog_content = "흐이이익!",
  ui_story_5017_50170801_36_dialog_content = "<size=45>「귀신」이다아아아!</size>",
  ui_story_5017_50170801_37_dialog_content = "저기... 전...",
  ui_story_5017_50170801_38_dialog_content = "됐어요... 저 같은 건 아무래도 상관 없으니까요...",
  ui_story_5017_50170801_39_dialog_content = "무녀님... 괜찮으신가요...",
  ui_story_5017_50170801_40_dialog_content = "...카야노, 고마워요.",
  ui_story_5017_50170801_41_dialog_content = "린네! 무사했구나!",
  ui_story_5017_50170801_42_dialog_content = "음... 죽기 직전에 <color=#FFB400>카야노</color>의 도움을 받았습니다.",
  ui_story_5017_50170801_43_dialog_content = "그럼 이 사람은...",
  ui_story_5017_50170801_44_dialog_content = "카야노는 평범한 여자애랍니다.",
  ui_story_5017_50170801_45_dialog_content = "조금 부끄러움이 많긴 하지만, 쉽게 친해질 수 있을 것입니다.",
  ui_story_5017_50170801_46_dialog_content = "무녀님...",
  ui_story_5017_50170801_47_dialog_content = "근데 왜 여기 나타난 건데?",
  ui_story_5017_50170801_48_dialog_content = "사실... 전 계속 같이 있었습니다만...",
  ui_story_5017_50170801_49_dialog_content = "뭐?! 어, 언제부터?",
  ui_story_5017_50170801_50_dialog_content = "여러분이 무녀님과 만났을 때부터입니다...",
  ui_story_5017_50170801_51_dialog_content = "그럼 처음부터 있었던 거잖아!",
  ui_story_5017_50170801_52_dialog_content = "그러니까 내가 본 그 이상한 그림자는...",
  ui_story_5017_50170801_53_dialog_content = "네... 저입니다...",
  ui_story_5017_50170801_54_dialog_content = "후훗, 카야노는 낯을 가리는 편입니다.\n때문에 무서울 정도로 빠르게 움직이는 법을 익혔지요.",
  ui_story_5017_50170801_55_dialog_content = "그래서 자신이 모습을 드러내려 하지 않는 한, 아무도 그 모습을 볼 수 없습니다.",
  ui_story_5017_50170801_56_dialog_content = "그러니까 린네를 오니 무리 속에서 구해낼 수 있었던 거구나...",
  ui_story_5017_50170801_57_dialog_content = "<color=#e8d9bb>타닥... 타닥...</color>",
  ui_story_5017_50170801_58_dialog_content = "오니가... 지붕 위로 올라오기 시작했어!",
  ui_story_5017_50170801_59_dialog_content = "정말 끈질긴 녀석들이네...",
  ui_story_5017_50170801_60_dialog_content = "하앗── 내가 전부 쓰러트려주겠어!",
  ui_story_5017_50170802_1_dialog_content = "여러분... 절 따라오세요...",
  ui_story_5017_50170802_2_dialog_content = "본성까지 가는 길을 알고 있으니까요...",
  ui_story_5017_50170802_3_dialog_content = "린네, 내가 부축해 줄게.",
  ui_story_5017_50170802_4_dialog_content = "어머, 요우에게 걱정을 끼쳐 버렸군요.",
  ui_story_5017_50170802_5_dialog_content = "그저 조금 지쳤을 뿐이랍니다. 걷지 못할 정도는 아닙니다.",
  ui_story_5017_50170802_6_dialog_content = "(게다가...)",
  ui_story_5017_50170802_7_dialog_content = "(제겐 반드시 해야 할 중요한 일이 있으니까요...)",
  ui_story_5017_50170802_8_dialog_content = "뭔가 엄청 순조로워진 것 같네.",
  ui_story_5017_50170802_9_dialog_content = "여기까지 오는 동안 한 번도 안 싸웠잖아.",
  ui_story_5017_50170802_10_dialog_content = "그건... 다들 이쪽 길에 오니가 적다고 말해줬거든요...",
  ui_story_5017_50170802_11_dialog_content = "다들?",
  ui_story_5017_50170802_12_dialog_content = "네...",
  ui_story_5017_50170802_13_dialog_content = "제 곁에 있는 <color=#FFB400>원령</color>들이요...",
  ui_story_5017_50170802_14_dialog_content = "「원령」이면...",
  ui_story_5017_50170802_15_dialog_content = "설마...",
  ui_story_5017_50170802_16_dialog_content = "「오니」?!",
  ui_story_5017_50170802_17_dialog_content = "아직 형체를 이루지 못한 「오니」입니다...",
  ui_story_5017_50170802_18_dialog_content = "음의 기운에 침식되지 않아서... 자기 의식을 유지하고 있어요...",
  ui_story_5017_50170802_19_dialog_content = "모두 착한 사람들이에요...",
  ui_story_5017_50170802_20_dialog_content = "그 사람들이... 지금 옆에 있어...?",
  ui_story_5017_50170802_21_dialog_content = "네...",
  ui_story_5017_50170802_22_dialog_content = "한 명은 당신 어깨에...",
  ui_story_5017_50170802_23_dialog_content = "방금 당신한테 「저녁 먹었어?」라고 물어봤어요...",
  ui_story_5017_50170802_24_dialog_content = "아...아직...",
  ui_story_5017_50170802_25_dialog_content = "시, 신경 써 줘서 고마워...",
  ui_story_5017_50170802_26_dialog_content = "이제 곧 도착할 것입니다.",
  ui_story_5017_50170802_27_dialog_content = "닌자 나리, 자중하시는 모습은 처음인 것 같군요.",
  ui_story_5017_50170802_28_dialog_content = "......",
  ui_story_5017_50170802_29_dialog_content = "당신과 얼굴을 마주 보고 있는데도 절 노리는 암기가 날아오지 않는다니,\n왠지 조금 적응이 안 되는 기분입니다만.",
  ui_story_5017_50170802_30_dialog_content = "...소생이 무엇을 하든 그대와는 무관한 일이오.",
  ui_story_5017_50170802_31_dialog_content = "어머?",
  ui_story_5017_50170802_32_dialog_content = "「무녀를 죽이겠다」는 결심은 그 정도였습니까?",
  ui_story_5017_50170802_33_dialog_content = "......",
  ui_story_5017_50170802_34_dialog_content = "제가 구해드린 것이 이유라면, 불필요한 배려입니다.",
  ui_story_5017_50170802_35_dialog_content = "그러시면 「닌자」라는 것이 그토록 시시한 것이었나 하는 생각이 들 테니 말이지요...",
  ui_story_5017_50170802_36_dialog_content = "내가 닌자로서 어찌 행동할지 그대가 참견할 필요는 없소.",
  ui_story_5017_50170802_37_dialog_content = "후훗, 아무렴 그래야지요.",
  ui_story_5017_50170802_38_dialog_content = "저는 늘 제가 당신의 품에서 죽음을 맞이하는 것이 무척 아름다우리라 생각했답니다.",
  ui_story_5017_50170802_39_dialog_content = "부디 저를 실망시키지 않으시길 바라겠습니다.",
  ui_story_5017_50170802_40_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_5017_50170802_41_dialog_content = "!!!",
  ui_story_5017_50170802_42_dialog_content = "<size=45>물러서라! 역적!</size>",
  ui_story_5017_50170802_43_dialog_content = "무녀님을 해치려는 버러지 같은 녀석.",
  ui_story_5017_50170802_44_dialog_content = "지금 즉시 베어주마!",
  ui_story_5017_50170802_45_dialog_content = "왜 또 싸우는 거야?!",
  ui_story_5017_50170802_46_dialog_content = "저 사람들은...",
  ui_story_5017_50170802_47_dialog_content = "쇼군님의 가신들입니다...",
  ui_story_5017_50170802_48_dialog_content = "강부성에 충성을 맹세하고 무녀님을 지키는 사람들이지요...",
  ui_story_5017_50170802_49_dialog_content = "생각지도 못했군...",
  ui_story_5017_50170802_50_dialog_content = "강부성에 환란을 일으키는 역적의 잔당이 아직도 살아 있었다니!",
  ui_story_5017_50170802_51_dialog_content = "<color=#FFB400>「환란을 일으켜」?</color>",
  ui_story_5017_50170802_52_dialog_content = "잘도 지껄이는구나.",
  ui_story_5017_50170802_53_dialog_content = "!!!",
  ui_story_5017_50170802_54_dialog_content = "(뭐야, 왜 대나무를 벤 거지? 화, 화가 났나?)",
  ui_story_5017_50170802_55_dialog_content = "잡아라!",
  ui_story_5017_50170802_56_dialog_content = "잡아? 가당키나 할 성싶으냐.",
  ui_story_5017_50170802_57_dialog_content = "결코 우리를 절멸시킬 순 없을 것이다.",
  ui_story_5017_50170802_58_dialog_content = "네놈들의 지배가 영원하리라 여기지 않는 게 좋을 게다.",
  ui_story_5017_50170802_59_dialog_content = "제길... 놓치다니...",
  ui_story_5017_50170802_60_dialog_content = "무녀님, 무사하십니까?",
  ui_story_5017_50170802_61_dialog_content = "저는 괜찮습니다.",
  ui_story_5017_50170802_62_dialog_content = "당신들이 왔다는 것은 이제 이곳도 안전하다는 뜻이겠군요.",
  ui_story_5017_50170802_63_dialog_content = "안전이라 하시면...",
  ui_story_5017_50170802_64_dialog_content = "무슨 일이 있으셨습니까?",
  ui_story_5017_50170802_65_dialog_content = "강부성 내에 오니가 나타났습니다...",
  ui_story_5017_50170802_66_dialog_content = "게다가 그 수도 무척 많았습니다.",
  ui_story_5017_50170802_67_dialog_content = "어째서 그런 일이...",
  ui_story_5017_50170802_68_dialog_content = "저는 이제 본성으로 가겠습니다. 그리고...",
  ui_story_5017_50170802_69_dialog_content = "...아닙니다. 그밖의 것은 여러분이 알 필요는 없습니다.",
  ui_story_5017_50170802_70_dialog_content = "......",
  ui_story_5017_50170802_71_dialog_content = "알겠습니다, 무녀님.",
  ui_story_5017_50170802_72_dialog_content = "저희가 본성까지 모셔다드리겠습니다.",
  ui_story_5017_50170802_73_dialog_content = "아메모리 님! 이쪽입니다!",
  ui_story_5017_50170802_74_dialog_content = "...다치셨습니까?!",
  ui_story_5017_50170802_75_dialog_content = "작은 상처일 뿐이오.",
  ui_story_5017_50170802_76_dialog_content = "아까 무사들을 보았습니다.",
  ui_story_5017_50170802_77_dialog_content = "무녀를 베시려던 것은 그럼...",
  ui_story_5017_50170802_78_dialog_content = "실패했소. 무녀는 아직 살아 있소이다.",
  ui_story_5017_50170802_79_dialog_content = "그렇습니까... 그래도 괜찮습니다, 아메모리 님.",
  ui_story_5017_50170802_80_dialog_content = "무녀 문제는 일단 접어두는 게 좋겠습니다. 당신의 안위가 가장 중요합니다.",
  ui_story_5017_50170802_81_dialog_content = "다시 생각해 보니 그대의 말이 맞았소.",
  ui_story_5017_50170802_82_dialog_content = "제 말이요?",
  ui_story_5017_50170802_83_dialog_content = "무녀를 죽인다고 모든 게 해결되진 않을 것이오.",
  ui_story_5017_50170802_84_dialog_content = "그 여자는... 소생이 생각한 것과는 조금 달랐소.",
  ui_story_5017_50170802_85_dialog_content = "소생의 생각이 짧았소이다.",
  ui_story_5017_50170802_86_dialog_content = "아메모리 님...",
  ui_story_5017_50170802_87_dialog_content = "다만 이번 일로 아무런 수확이 없었던 것은 아니오.",
  ui_story_5017_50170802_88_dialog_content = "어쩌면 무녀를 죽이는 것보다 더 가치 있는 일을 할 수 있을지도 모르오.",
  ui_story_5017_50170802_89_dialog_content = "더 가치 있는 일이라 하시면...",
  ui_story_5017_50170802_90_dialog_content = "<color=#FFB400>「능인옥」</color>을 찾았소.",
  ui_story_5017_50170802_91_dialog_content = "「능인옥」을 말입니까?!",
  ui_story_5017_50170802_92_dialog_content = "어디 있었습니까?",
  ui_story_5017_50170802_93_dialog_content = "소생이 아는 자가 가지고 있었소.",
  ui_story_5017_50170802_94_dialog_content = "저는 그럼 여기서 인사 드리겠습니다.",
  ui_story_5017_50170802_95_dialog_content = "모처럼 오신 강부성 여행에 기대가 많으셨을 터인데,\n심려를 끼쳐 드려 죄송합니다.",
  ui_story_5017_50170802_96_dialog_content = "에이, 그게 무슨 말이야... 린네 잘못도 아니잖아!",
  ui_story_5017_50170802_97_dialog_content = "무녀는 본디 운도의 「음양」을 조화시키는 역할을 하고 있습니다.",
  ui_story_5017_50170802_98_dialog_content = "따라서 작금의 위기는 저도 책임을 면할 수는 없는 것입니다.",
  ui_story_5017_50170802_99_dialog_content = "아... 린네가 또 내가 잘 모르는 얘길 하기 시작했어.",
  ui_story_5017_50170802_100_dialog_content = "본성 주변은 적어도 지금은 안전합니다. 안심하고 유람해 주셔도 괜찮습니다.",
  ui_story_5017_50170802_101_dialog_content = "카야노도 강부성 사람이니, 길 안내를 부탁하는 것이 좋겠습니다.",
  ui_story_5017_50170802_102_dialog_content = "네? 저요...?",
  ui_story_5017_50170802_103_dialog_content = "그렇습니다. 잘할 수 있을 것입니다. 그렇지 않나요?",
  ui_story_5017_50170802_104_dialog_content = "강부성 곳곳을 저보다 더 잘 알고 있으니 말이지요.",
  ui_story_5017_50170802_105_dialog_content = "무녀님이 그렇게 말씀하신다면...",
  ui_story_5017_50170802_106_dialog_content = "그럼... 우리 또 만날 수 있는 거지?",
  ui_story_5017_50170802_107_dialog_content = "물론입니다, 요우.",
  ui_story_5017_50170802_108_dialog_content = "이번 일을 처리하고 나면, 제가 여러분을 찾아뵙겠습니다.",
  ui_story_5017_50170802_109_dialog_content = "그때는 함께 「춘일제」를 즐기기로 하지요.",
  ui_story_5017_50170802_110_dialog_content = "응!",
  ui_story_5017_50170802_111_dialog_content = "약속이야! 같이 「춘일제」에서 노는 거야!",
  ui_story_5017_50170901_1_dialog_content = "<color=#e8d9bb>강부성 번화가의 어느 거리</color>",
  ui_story_5017_50170901_2_dialog_content = "(아아... 어쩌다 보니 손님들을 모시고 여기까지 와버렸습니다...)",
  ui_story_5017_50170901_3_dialog_content = "(너무 긴장이 됩니다... 무녀님을 실망시키면 안 되는데... 하지만...)",
  ui_story_5017_50170901_4_dialog_content = "(어떻게 안내하면 좋을까요...)",
  ui_story_5017_50170901_5_dialog_content = "<size=30>여기가 사카이 거리입니다... 강부성의 번화가에 속하는 곳이에요...</size>",
  ui_story_5017_50170901_6_dialog_content = "<size=30>아무튼 시끌벅적하고... 깨끗한 곳이고... 「춘일제」도 여기서 개최합니다...</size>",
  ui_story_5017_50170901_7_dialog_content = "(무슨 말인지 하나도 안 들려!)",
  ui_story_5017_50170901_8_dialog_content = "확실히 여긴 성의 교외보다 훨씬 더 「춘일제」 분위기가 있는 것 같네.",
  ui_story_5017_50170901_9_dialog_content = "거리엔 활짝 핀 벚꽃이 눈처럼 흩날리고... 사람들은 「춘일제」의 음식을 준비하고 있어...",
  ui_story_5017_50170901_10_dialog_content = "어라? 이건...",
  ui_story_5017_50170901_11_dialog_content = "맛있는 냄새!",
  ui_story_5017_50170901_12_dialog_content = "그 엄청나게 잘 맞는 호흡은 뭐야?!",
  ui_story_5017_50170901_13_dialog_content = "(아... 이 냄새... 이건...)",
  ui_story_5017_50170901_14_dialog_content = "후후, 배가 고프면 아무것도 못 한다고!",
  ui_story_5017_50170901_15_dialog_content = "어디 「운도 여행 가이드북」 맛집 특집에는 뭘 추천하는지 볼까나...",
  ui_story_5017_50170901_16_dialog_content = "그 가이드 다시 보니 정말 유용하네.",
  ui_story_5017_50170901_17_dialog_content = "음... 「미각의향연양심적가격쇼군도극찬한맛해가라면성황리에영업중」...?",
  ui_story_5017_50170901_18_dialog_content = "「양심적 가격 쇼군도 극찬」... 으음... 쇼군도 돈 내고 먹어야 하는 거였구나.",
  ui_story_5017_50170901_19_dialog_content = "아하하, 왠지 그렇게 끊어 읽는 게 아닐 것 같은데...",
  ui_story_5017_50170901_20_dialog_content = "내가 좀 볼게... 으음, <color=#FFB400>해가 라면</color>?",
  ui_story_5017_50170901_21_dialog_content = "(앗... 그 가게 이름을 불러버리면...)",
  ui_story_5017_50170901_22_dialog_content = "<size=45>해가 라면──</size>",
  ui_story_5017_50170901_23_dialog_content = "천하제일!",
  ui_story_5017_50170901_24_dialog_content = "어서 오세요~",
  ui_story_5017_50170901_25_dialog_content = "식사는 하셨나요~?",
  ui_story_5017_50170901_26_dialog_content = "배가 고프시면 모모와 안즈의 <color=#FFB400>해가 라면</color>으로 오세요!",
  ui_story_5017_50170901_27_dialog_content = "미각의 향연, 양심적 가격!",
  ui_story_5017_50170901_28_dialog_content = "쇼군도 극찬한 맛!",
  ui_story_5017_50170901_29_dialog_content = "해가 라면, 성황리에 영업 중!",
  ui_story_5017_50170901_30_dialog_content = "광고랑 토씨 하나 안 틀리고 똑같잖아...!",
  ui_story_5017_50170901_31_dialog_content = "광고랑 같은지 어떤지는 한 입만 먹어도 바로 알 수 있다구!",
  ui_story_5017_50170901_32_dialog_content = "역시 가게 이름을 듣자마자... 모모랑 안즈가 나타났습니다...",
  ui_story_5017_50170901_33_dialog_content = "어라? 우리 알바생이잖아?!",
  ui_story_5017_50170901_34_dialog_content = "뭐야, 알바생! 어디 갔나 했더니, 여기 있었어?",
  ui_story_5017_50170901_35_dialog_content = "아, 알바생?!",
  ui_story_5017_50170901_36_dialog_content = "네... 모모와 안즈는... 저를 거두어 준 은인이에요...",
  ui_story_5017_50170901_37_dialog_content = "두 사람 덕분에... 저는 강부성에서 일자리를 구할 수 있었습니다...",
  ui_story_5017_50170901_38_dialog_content = "알바생! 계속 땡땡이 치는 줄 알았는데, 손님을 끌어왔던 거구나!",
  ui_story_5017_50170901_39_dialog_content = "열심히 노력한 걸 봐서 감봉은 반만 해줄게!",
  ui_story_5017_50170901_40_dialog_content = "손님들, 이쪽으로 오세요!",
  ui_story_5017_50170901_41_dialog_content = "정말 친절한 주인장들이네.",
  ui_story_5017_50170901_42_dialog_content = "<color=#e8d9bb>강부성 번화가, 해가 라면 가게 옆</color>",
  ui_story_5017_50170901_43_dialog_content = "자~ 뜨끈뜨끈한 해가 라면 나왔습니다~",
  ui_story_5017_50170901_44_dialog_content = "우와, 냄새 좋다!",
  ui_story_5017_50170901_45_dialog_content = "<color=#FFB400>언니</color>도 이런 맛있는 걸 같이 먹을 수 있으면 좋았을 텐데...",
  ui_story_5017_50170901_46_dialog_content = "언니? 너 언니도 있었어?!",
  ui_story_5017_50170901_47_dialog_content = "너 아무것도 기억이 안 난다고 했던 거 아니었어?",
  ui_story_5017_50170901_48_dialog_content = "아~ 내 말은 린 가문에서 알게 된 언니 얘기야. 우린 의자매라구!",
  ui_story_5017_50170901_49_dialog_content = "우리 언니는 보통 사람이 아냐!",
  ui_story_5017_50170901_50_dialog_content = "린 가문에서... 아니지, 움브라톤 어디든 언니를 이길 수 있는 사람은 없다구.",
  ui_story_5017_50170901_51_dialog_content = "농담이 아냐. 그 이...콜록콜록...반이 상대라도 우리 언니가 이길 확률이 80%는 될 거야!",
  ui_story_5017_50170901_52_dialog_content = "그 기침... 뭘 숨길 생각이 전혀 없잖아!",
  ui_story_5017_50170901_53_dialog_content = "후후~ 아무튼 우리 언니는 대단해! 언니를 이길 수 있는 건...",
  ui_story_5017_50170901_54_dialog_content = "매운 고추뿐이야!",
  ui_story_5017_50170901_55_dialog_content = "뭐?",
  ui_story_5017_50170901_56_dialog_content = "언니는 옛날에 움브라톤에 있는 가게에서 지옥라면을 먹고...",
  ui_story_5017_50170901_57_dialog_content = "주먹으로 자기 입술을 100대 때렸다는 전설이 있거든.",
  ui_story_5017_50170901_58_dialog_content = "...왜 물을 안 마신 건데?!",
  ui_story_5017_50170901_59_dialog_content = "이렇게 부드러운 식감에 맛도 순한 라면을 언니가 먹는다면...",
  ui_story_5017_50170901_60_dialog_content = "분명히 엄청 감동할 거야!",
  ui_story_5017_50170901_61_dialog_content = "헤헤... 이건 우리 비법 레시피로 만든 거야. 운도에 우리 집밖에 없어.",
  ui_story_5017_50170901_62_dialog_content = "쇼군도 이 맛을 극찬했다구!",
  ui_story_5017_50170901_63_dialog_content = "그 쇼군이란 사람은 백성들한테 친근한 모양이네?",
  ui_story_5017_50170901_64_dialog_content = "그럼 린네 씨도 구름의 거울을 잘 빌려올 수 있으려나?",
  ui_story_5017_50170901_65_dialog_content = "쇼군이? 아하하... 손님들은 운도 사람이 아니구나?",
  ui_story_5017_50170901_66_dialog_content = "지난 10년간 쇼군은 운도 철권통치의 상징이었다구.",
  ui_story_5017_50170901_67_dialog_content = "(지난 10년이면... 설마 요우의 기억과 무슨 관계가 있는 건 아니겠지...)",
  ui_story_5017_50170901_68_dialog_content = "저기, 그럼 그동안 무슨 일이 있었는지 자세히 좀 들려줄 수 있을까?",
  ui_story_5017_50170901_69_dialog_content = "응? 근데 손님 벌써 국물까지 다 먹었는데...",
  ui_story_5017_50170901_70_dialog_content = "한 그릇 더!",
  ui_story_5017_50170901_71_dialog_content = "(다행이다...)",
  ui_story_5017_50170901_72_dialog_content = "갑니다~ 정말 시원시원한 손님이네!",
  ui_story_5017_50170901_73_dialog_content = "크흠... 옛날에는 운도가 지금처럼 평화롭지 않았어.",
  ui_story_5017_50170901_74_dialog_content = "이 섬은 「음」과 「양」의 두 힘이 감돌고, 일 년 내내 오니가 섬을 배회했어...",
  ui_story_5017_50170901_75_dialog_content = "게다가 운도 주변 섬에서도 전란이 끊이지 않았어.",
  ui_story_5017_50170901_76_dialog_content = "그러다 본도에서 운도로 쇼군이 파견되고, 강부성이 건설된 뒤로...",
  ui_story_5017_50170901_77_dialog_content = "운도 사람들은 비록 철권통치 아래 살게 되었지만, 대신 오랜 안정과 평화를 얻었어.",
  ui_story_5017_50170901_78_dialog_content = "그 전통이 계속해서 이어졌고, 지금의 쇼군 <color=#FFB400>후지쿠모</color>까지 오게 된 거야.",
  ui_story_5017_50170901_79_dialog_content = "그 뒤에 무슨 일이 있었는지는 다음 시간에...",
  ui_story_5017_50170901_80_dialog_content = "한 그릇 더!",
  ui_story_5017_50170901_81_dialog_content = "(진짜 빨리 먹네!)",
  ui_story_5017_50170901_82_dialog_content = "네~ 손님! 흠흠... 그 뒤로 운도는 후지쿠모의 무력 통치 아래 평화로운 시기가 이어졌지만...",
  ui_story_5017_50170901_83_dialog_content = "섬에 있던 기존의 총통이나 일부 원주민들은 오랫동안 불만을 가지고 있었어...",
  ui_story_5017_50170901_84_dialog_content = "그러던 중에 총통이 얼마 남지 않은 제자와 병력들을 데리고 반란을 일으켰어. 하지만...",
  ui_story_5017_50170901_85_dialog_content = "한 그릇 더!",
  ui_story_5017_50170901_86_dialog_content = "(벌써 익숙해진 거야?!)",
  ui_story_5017_50170901_87_dialog_content = "네~ 갑니다! 하지만 총통은 불행하게도 반란에 실패했고,\n후지쿠모한테 잡혀서 본성에 있는 봉인의 땅에 갇혀 버렸어.",
  ui_story_5017_50170901_88_dialog_content = "근데 소문에 따르면... 그 총통의 잔당이 요즘 몰래 활동하고 있다고 해.",
  ui_story_5017_50170901_89_dialog_content = "정말 불쌍하다니까. 듣기로는 후지쿠모 그 사람은 불사신이고, 피도 눈물도 없다고 하던데.",
  ui_story_5017_50170901_90_dialog_content = "잔당들도 그 쇼군을 당해낼 방법은 없을 거야.",
  ui_story_5017_50170901_91_dialog_content = "뭐, 그래도 해가 라면은 손님을 가리거나 하진 않아~",
  ui_story_5017_50170901_92_dialog_content = "타향 손님이든, 잔당이든, 오니든 상관없이 모두 라면을 맛볼 수 있어!",
  ui_story_5017_50170901_93_dialog_content = "한 그릇 더!",
  ui_story_5017_50170901_94_dialog_content = "예이~ 손님은 정말 대식가구나!",
  ui_story_5017_50170901_95_dialog_content = "근데 이야기는 이제 끝이야.",
  ui_story_5017_50170901_96_dialog_content = "...그럼 미리 말하지! 좀 얍삽하네...",
  ui_story_5017_50170901_97_dialog_content = "어디 보자... 하나, 둘, 셋... 일곱 그릇이면...",
  ui_story_5017_50170901_98_dialog_content = "뭘 세는 건데? 돈이라면 이미 내가 냈어.",
  ui_story_5017_50170901_99_dialog_content = "뭐, 뭐라고?!",
  ui_story_5017_50170901_100_dialog_content = "아침부터 밤까지 계속 먹기만 한 건 나잖아!",
  ui_story_5017_50170901_101_dialog_content = "아이고, 벌써 시간이 이렇게 됐잖아?",
  ui_story_5017_50170901_102_dialog_content = "알바생, 너도 얼른 돌아가.",
  ui_story_5017_50170901_103_dialog_content = "아니면 밤이 돼서 또 <color=#FFB400>그 녀석들</color>이 따라다닐 테니까.",
  ui_story_5017_50170901_104_dialog_content = "아... 그래도 되나요... 그럼 오늘은 먼저 가보겠습니다...",
  ui_story_5017_50170901_105_dialog_content = "그 녀석들? ...설마 카야노 씨가 말했던 「원령」 얘기는 아니겠지...?",
  ui_story_5017_50170901_106_dialog_content = "PlayerName, 요우, 우리가 카야노 씨 데려다주자.",
  ui_story_5017_50170901_107_dialog_content = "응, 그러자.",
  ui_story_5017_50170901_108_dialog_content = "후후~ 드디어 이 대협객의 차례인가!",
  ui_story_5017_50170901_109_dialog_content = "주인장들, 잘 먹었어!",
  ui_story_5017_50170901_110_dialog_content = "다음에 또 와~",
  ui_story_5017_50170901_111_dialog_content = "<color=#e8d9bb>강부성 번화가의 어느 거리</color>",
  ui_story_5017_50170901_112_dialog_content = "저기... 정말 죄송합니다... 손님 여러분께 신세를 져버렸네요...",
  ui_story_5017_50170901_113_dialog_content = "저는 저 앞의 거리에 살고 있으니... 여기까지만 데려다주셔도 괜찮습니다...",
  ui_story_5017_50170901_114_dialog_content = "<color=#e8d9bb>휘이잉── 휘잉──</color>",
  ui_story_5017_50170901_115_dialog_content = "으으...",
  ui_story_5017_50170901_116_dialog_content = "카야노, 추워?",
  ui_story_5017_50170901_117_dialog_content = "추워서 그러는 것 같지는 않은데? 뭔가 긴장한 것 같네.",
  ui_story_5017_50170901_118_dialog_content = "뭐 때문에 그러는데?",
  ui_story_5017_50170901_119_dialog_content = "<color=#e8d9bb>스으윽──!</color>",
  ui_story_5017_50170901_120_dialog_content = "히익!",
  ui_story_5017_50170901_121_dialog_content = "무, 무슨 소리지?!",
  ui_story_5017_50170901_122_dialog_content = "바이스까지 완전히 분위기에 휩쓸려 버렸잖아...",
  ui_story_5017_50170901_123_dialog_content = "카야노, 그럼 설마 아까 라면집 주인장들이 「그 녀석들」이라고 한 건...",
  ui_story_5017_50170901_124_dialog_content = "으으... 죄송합니다, 사실...",
  ui_story_5017_50170901_125_dialog_content = "사실... 곧 형태를 이루려고 하는... 그다지 온순하지 않은 오니가...\n지금 이 주변을 둘러싸고 있는 게 느껴집니다...",
  ui_story_5017_50170901_126_dialog_content = "으아아...",
  ui_story_5017_50170901_127_dialog_content = "카야노 씨! 설마... 그 녀석들이 또 온 건가요?!",
  ui_story_5017_50170901_128_dialog_content = "아... 바이스 님, 안심하세요... 당신 주변엔 없습니다.",
  ui_story_5017_50170901_129_dialog_content = "그래그래. 바이스, 긴장 풀어.",
  ui_story_5017_50170901_130_dialog_content = "운도 여행 가이드북에도 쓰여 있었어. 「밤에 가까워질수록 위험하다」고!",
  ui_story_5017_50170901_131_dialog_content = "뭐?!",
  ui_story_5017_50170901_132_dialog_content = "아니지! 잘못 읽었어. 「성안에 가까워질수록 안전하다」고!",
  ui_story_5017_50170901_133_dialog_content = "이제 곧 강부성의 중심지야. 그러니까 분명히 안전할 거야.",
  ui_story_5017_50170901_134_dialog_content = "맞아요... 아무튼 여러분, 정말 감사합니다... 그럼 저는 이만 가보겠습니다...",
  ui_story_5017_50170901_135_dialog_content = "그리고... 저기...",
  ui_story_5017_50170901_136_dialog_content = "PlayerName 님 옆에 있는 오니는... 여러분도 보이시는 거죠...?",
  ui_story_5017_50170901_137_dialog_content = "우와악?!",
  ui_story_5017_50170901_138_dialog_content = "그어어!",
  ui_story_5017_50170901_139_dialog_content = "크아아!",
  ui_story_5017_50170901_140_dialog_content = "흐이익!",
  ui_story_5017_50170901_141_dialog_content = "오! 그럼 또 이 몸이 나설 차례네!",
  ui_story_5017_50170901_142_dialog_content = "와라! 내 주먹으로 때려눕혀 줄 테니까!",
  ui_story_5017_50170902_1_dialog_content = "흐아압!",
  ui_story_5017_50170902_2_dialog_content = "끄억!",
  ui_story_5017_50170902_3_dialog_content = "그어어!",
  ui_story_5017_50170902_4_dialog_content = "그어어어!",
  ui_story_5017_50170902_5_dialog_content = "서...성안으로 갈수록 안전하다고 한 거 아니었어?!",
  ui_story_5017_50170902_6_dialog_content = "왜 오니가 더 늘어나고 있는 건데?!",
  ui_story_5017_50170902_7_dialog_content = "죄, 죄송합니다! 원래 제 주변의 오니는 조종할 수 있었는데요...",
  ui_story_5017_50170902_8_dialog_content = "으으... 다시 해 볼게요... 침착... 침착하게...",
  ui_story_5017_50170902_9_dialog_content = "역시 안 돼요... 못 하겠어요... 제가 여러분께 폐를 끼쳤네요...",
  ui_story_5017_50170902_10_dialog_content = "전 역시 여러분과 함께 있지 않는 게 좋겠어요...",
  ui_story_5017_50170902_11_dialog_content = "아니야, 이 오니들은 애초에 카야노를 따라온 게 아니었어.",
  ui_story_5017_50170902_12_dialog_content = "왠지 누군가의 조종을 받고 있는 것 같아...",
  ui_story_5017_50170902_13_dialog_content = "PlayerName! 뭘 멍하니 있어?!",
  ui_story_5017_50170902_14_dialog_content = "이런!",
  ui_story_5017_50170902_15_dialog_content = "그어어!",
  ui_story_5017_50170902_16_dialog_content = "<color=#e8d9bb>휙──! 휙──!</color>",
  ui_story_5017_50170902_17_dialog_content = "앗...!",
  ui_story_5017_50170902_18_dialog_content = "끄어어...",
  ui_story_5017_50170902_19_dialog_content = "...후우.",
  ui_story_5017_50170902_20_dialog_content = "이방인이여, 생각에 잠겨 있기만 해서는 위험에 처할 뿐이오.",
  ui_story_5017_50170902_21_dialog_content = "...고, 고마워!",
  ui_story_5017_50170902_22_dialog_content = "아메모리?! 언제 온 거야?",
  ui_story_5017_50170902_23_dialog_content = "그 무사들은 벌써 따돌린 거야?",
  ui_story_5017_50170902_24_dialog_content = "그 정도 추격은 내 검으로 벨 것도 없소이다.",
  ui_story_5017_50170902_25_dialog_content = "...왜 소생의 검을 계속 쳐다보는 것이오?",
  ui_story_5017_50170902_26_dialog_content = "계속 묻고 싶었거든...",
  ui_story_5017_50170902_27_dialog_content = "그 검 어디서 많이 본 것 같단 말이지... 대체 넌 전에 날 어떻게 알았던 거야?",
  ui_story_5017_50170902_28_dialog_content = "...그 물음에 소생이 답할 이유는 없소이다.",
  ui_story_5017_50170902_29_dialog_content = "그대를 알게 된 것도 애당초 소생의 본의가 아니었소.",
  ui_story_5017_50170902_30_dialog_content = "얼버무리지 마!",
  ui_story_5017_50170902_31_dialog_content = "우리가 똑같은 곡옥을 가지고 있는 것만 해도 이미 확실한 증거잖아.",
  ui_story_5017_50170902_32_dialog_content = "이게 사카이 거리 아무 데서나 파는 거라면 모를까!",
  ui_story_5017_50170902_33_dialog_content = "네 곡옥은 어디서 난 건데?",
  ui_story_5017_50170902_34_dialog_content = "그 검술은 어디서 배웠어?",
  ui_story_5017_50170902_35_dialog_content = "그리고 왜 처음 만났는데 내 이름을 알고 있었어?",
  ui_story_5017_50170902_36_dialog_content = "...「곡옥」?",
  ui_story_5017_50170902_37_dialog_content = "<color=#FFB400>「척귀능인」</color>이 보잘것없는 옥 취급을 받은 것을 스승님께서 아시면...",
  ui_story_5017_50170902_38_dialog_content = "그때 그 「능인옥」을 그대에게 주셨던 것을 후회하셨을 것이오.",
  ui_story_5017_50170902_39_dialog_content = "?!",
  ui_story_5017_50170902_40_dialog_content = "<color=#FFB400>스승님</color>?!",
  ui_story_5017_50170902_41_dialog_content = "......",
  ui_story_5017_50170902_42_dialog_content = "정녕 아무것도 기억하지 못한단 말인가.",
  ui_story_5017_50170902_43_dialog_content = "아무래도 이 기회에 확실히 말해 두어야 할 것 같소이다.",
  ui_story_5017_50171001_1_dialog_content = "기억 얘기라면... 사실 기억이 아예 없는 건 아냐.",
  ui_story_5017_50171001_2_dialog_content = "뭐... 아무것도 없는 바다랑 방울 소리, 그리고 이 곡옥뿐이지만.",
  ui_story_5017_50171001_3_dialog_content = "이 곡옥은 내 기억으로는 처음부터 쭉 몸에 지니고 있었던 것 같아.",
  ui_story_5017_50171001_4_dialog_content = "쥐고 있으면... 항상 내 게 아닌 것 같은 따스함과 힘이 느껴졌어.",
  ui_story_5017_50171001_5_dialog_content = "PlayerName 쟤는 이게 분명히 중요한 물건이고, 누군가와 관계가 있다고 확신했어.",
  ui_story_5017_50171001_6_dialog_content = "화, 확신까진 아니고 그냥 합리적인 추측이랄까...",
  ui_story_5017_50171001_7_dialog_content = "근데 「스승님」이란 사람에 대한 기억은 전혀 없어.",
  ui_story_5017_50171001_8_dialog_content = "......",
  ui_story_5017_50171001_9_dialog_content = "그렇군.",
  ui_story_5017_50171001_10_dialog_content = "그 과거를 잊은 것은 나쁜 일이라고 할 수 없을 것이오.",
  ui_story_5017_50171001_11_dialog_content = "그대는 운이 좋소이다.",
  ui_story_5017_50171001_12_dialog_content = "(우와... 진짜 궁금해서 안달 나게 만드네!)",
  ui_story_5017_50171001_13_dialog_content = "...확실하게 말해주지 않을래? 나랑 그 스승님에 대해서 아는 건 다 말해줘!",
  ui_story_5017_50171001_14_dialog_content = "이렇게 부탁할게!",
  ui_story_5017_50171001_15_dialog_content = "<color=#e8d9bb>뚜둑── 뚜둑──</color>",
  ui_story_5017_50171001_16_dialog_content = "...지금 그거 손가락 관절 푸는 소리 아냐...?",
  ui_story_5017_50171001_17_dialog_content = "(그건 부탁이 아니고 협박이잖아!)",
  ui_story_5017_50171001_18_dialog_content = "...그대는 여전히 성급하군.",
  ui_story_5017_50171001_19_dialog_content = "소생의 명예를 걸고 보증하지.",
  ui_story_5017_50171001_20_dialog_content = "이 「척귀능인」은 스승님과 소생, 그리고 그대 사이의 유일한 약속의 증거요.",
  ui_story_5017_50171001_21_dialog_content = "설령 그대에게 기억이 없더라도, 그 누구의 도움이 없더라도...",
  ui_story_5017_50171001_22_dialog_content = "그 「능인옥」은 그대를 운도까지 이끌었을 것이오.",
  ui_story_5017_50171001_23_dialog_content = "제자인 소생과 그대만이 스승님과 이런 인연을 가지는 것이외다.",
  ui_story_5017_50171001_24_dialog_content = "...확실히 뭔가 특별한 힘이 느껴져.",
  ui_story_5017_50171001_25_dialog_content = "스승님께선 매우 뛰어난 능력의 소유자였소.\n또한 자신의 「인술」과 「기공술」을 각각 소생과 그대에게 전수했소.",
  ui_story_5017_50171001_26_dialog_content = "아, 뭔가 기억이 났어! 어쩐지 네 검술이 익숙하게 느껴진다 했어.",
  ui_story_5017_50171001_27_dialog_content = "그럼 넌 어때? 내 초식이 익숙했어?",
  ui_story_5017_50171001_28_dialog_content = "...전혀. 당시 그대의 솜씨는 고작 스승님의 존안에 먹칠만 하지 않는 수준이었소.",
  ui_story_5017_50171001_29_dialog_content = "허나 운도를 떠났다가 돌아온 지금은 권법이 조금 발전했더군.",
  ui_story_5017_50171001_30_dialog_content = "음... 생각해 보니 그대는 결국 소생의 사매이지 않은가.",
  ui_story_5017_50171001_31_dialog_content = "사매?!",
  ui_story_5017_50171001_32_dialog_content = "넌 삐쩍 곯은 것처럼 온몸에 근육도 없는데...",
  ui_story_5017_50171001_33_dialog_content = "그렇게 허약해서 어떻게 내 사저라는 거야?",
  ui_story_5017_50171001_34_dialog_content = "가볍고 민첩한 신체는 인술의 기본이오.",
  ui_story_5017_50171001_35_dialog_content = "소생의 본분을 깎아내리지 마시오.",
  ui_story_5017_50171001_36_dialog_content = "소생도 그대 같은 자와 동문인 것을 인정하고 싶지 않으니 말이외다.",
  ui_story_5017_50171001_37_dialog_content = "내가 뭐 어쨌다고? 똑바로 말해! 주먹 맛 좀 볼래?!",
  ui_story_5017_50171001_38_dialog_content = "자, 자... 둘 다 일단 진정해.",
  ui_story_5017_50171001_39_dialog_content = "그런데 그 스승님이란 사람은 지금 어디 있는데?",
  ui_story_5017_50171001_40_dialog_content = "분명히 요우를 많이 보고 싶어 하지 않을까?",
  ui_story_5017_50171001_41_dialog_content = "......",
  ui_story_5017_50171001_42_dialog_content = "스승님께선...",
  ui_story_5017_50171001_43_dialog_content = "강부성 봉인의 땅에 갇혀 계시오.",
  ui_story_5017_50171001_44_dialog_content = "봉인의 땅?! 그거 아까 해가 라면에서 들은 이야기에 나왔던 거잖아...",
  ui_story_5017_50171001_45_dialog_content = "그럼 설마... 너희 스승님이 운도의 총통이었단 말이야?!",
  ui_story_5017_50171001_46_dialog_content = "내 스승님이 그렇게 대단한 사람이었어?!",
  ui_story_5017_50171001_47_dialog_content = "그렇소. 허나 그것도 이미 과거의 일이오.",
  ui_story_5017_50171001_48_dialog_content = "스승님은 봉인의 땅에 갇힌 뒤로 다시는 소식을 들을 수 없었소.",
  ui_story_5017_50171001_49_dialog_content = "최근 몇 년 사이 운도의 백성들은 쇼군과 오니에게 겹으로 박해를 받아\n고된 삶을 살아가고 있었소.",
  ui_story_5017_50171001_50_dialog_content = "결국 운도 전체가 후지쿠모와 그 하수인들에 의해 혼탁하게 변하고 말았지.",
  ui_story_5017_50171001_51_dialog_content = "참... 또한 후지쿠모 곁에 있는 무녀도...",
  ui_story_5017_50171001_52_dialog_content = "쳇... 생각만 해도 구역질이 나는 자였소.",
  ui_story_5017_50171001_53_dialog_content = "무녀라면... 린네 씨 얘긴가요?",
  ui_story_5017_50171001_54_dialog_content = "「구역질이 난다」니... 전 린네 씨가 그런 사람은 아닌 것 같은걸요...",
  ui_story_5017_50171001_55_dialog_content = "...그자라면 그렇지 않다고 할 수도 있겠지.",
  ui_story_5017_50171001_56_dialog_content = "(설마... 그 후지쿠모한테 다른 무녀가 또 있는 건가?)",
  ui_story_5017_50171001_57_dialog_content = "...실례했소. 방금은 소생이 추태를 보였소.",
  ui_story_5017_50171001_59_dialog_content = "그것보다 아메모리 씨, 당신은 지금도... 린네 씨를 해칠 생각인가요?",
  ui_story_5017_50171001_60_dialog_content = "......",
  ui_story_5017_50171001_61_dialog_content = "사실 그자는 이미 소생의 목표가 아니오. 그것보다 더 중요한 일이 생겼으니 말이오.",
  ui_story_5017_50171001_62_dialog_content = "역시...",
  ui_story_5017_50171001_63_dialog_content = "비록 소생은 왜 그자가 그때 제 몸을 던져 모두를 지키려 했는지 이해할 수 없으나...",
  ui_story_5017_50171001_64_dialog_content = "그런 순수한 의지에는 소생도 놀랐소이다.",
  ui_story_5017_50171001_65_dialog_content = "우와... 그 말을 린네한테 직접 해주면 분명히...",
  ui_story_5017_50171001_66_dialog_content = "...인술!",
  ui_story_5017_50171001_67_dialog_content = "으앗! 농담이라구!",
  ui_story_5017_50171001_68_dialog_content = "본론으로 돌아와서... 지금 소생이 찾아온 유일한 목적은...",
  ui_story_5017_50171001_69_dialog_content = "요우 그대 때문이외다.",
  ui_story_5017_50171001_70_dialog_content = "?!",
  ui_story_5017_50171001_71_dialog_content = "혹여 그대가 소생의 말을 믿어줄 수 있다면...",
  ui_story_5017_50171001_72_dialog_content = "소생과 함께 강부성 본성에 있는 봉인의 땅으로 가서 스승님을 구했으면 하오.",
  ui_story_5017_50171001_73_dialog_content = "「척귀능인」의 힘이 합쳐진다면, 활로는 반드시 열릴 것이오.",
  ui_story_5017_50171001_74_dialog_content = "...비록 스승님의 생사는 알지 못하나... 아니, 스승님께선 반드시 살아계실 것이오!",
  ui_story_5017_50171001_75_dialog_content = "이 「척귀능인」의 반응이야말로 스승님께서 아직 살아계신다는 증거이니 말이외다.",
  ui_story_5017_50171001_76_dialog_content = "이것을 가지고 가서 함께 스승님을 구했으면 하오.",
  ui_story_5017_50171001_77_dialog_content = "그리하면 그대도 더 많은 것을 알게 될 것이오.",
  ui_story_5017_50171001_78_dialog_content = "아니, 갑자기 그런 말을 들으면... 어떻게 해야 할지 잘 모르겠다고...",
  ui_story_5017_50171001_79_dialog_content = "......",
  ui_story_5017_50171001_80_dialog_content = "아...",
  ui_story_5017_50171001_81_dialog_content = "그대가 스승님을 만난다면... 아니, 스승님의 물건이라도 볼 수 있다면...",
  ui_story_5017_50171001_82_dialog_content = "어쩌면 그대도 더 많은 기억을 떠올릴 수도 있을 것이오.",
  ui_story_5017_50171001_83_dialog_content = "그 눈으로 직접 확인하고 싶지 않소?",
  ui_story_5017_50171001_84_dialog_content = "난...",
  ui_story_5017_50171001_85_dialog_content = "......",
  ui_story_5017_50171001_86_dialog_content = "생각이 너무 많아서 머리가 아파졌어! PlayerName, 넌 어떻게 생각해?",
  ui_story_5017_50171001_87_dialog_content = "음... 그건 네가 직접 결정해야 할 일이라고 생각하지만...",
  ui_story_5017_50171001_88_dialog_content = "제삼자의 입장에서 봤을 땐...",
  ui_story_5017_50171001_89_option_content = "일단은 믿어도 될 것 같아.",
  ui_story_5017_50171001_90_dialog_content = "응, 우선은 같이 가 봐도 좋지 않을까?",
  ui_story_5017_50171001_91_dialog_content = "나도 그 스승님이 어떤 사람인지 궁금하기도 하고.",
  ui_story_5017_50171001_92_dialog_content = "무슨 일이 있더라도 최소한 목적이 뭔지 알아낼 순 있을 거잖아.",
  ui_story_5017_50171001_93_dialog_content = "린네도 아직 본성에 있으니까 어떻게든 될 거야.",
  ui_story_5017_50171001_94_option_content = "왠지 다른 목적도 있는 것 같아.",
  ui_story_5017_50171001_95_dialog_content = "음... 확실히 조심할 필요도 있겠어. 지금 말한 게 전부는 아닐지도 모르니까.",
  ui_story_5017_50171001_96_dialog_content = "그래도 방금 반응을 보니까 진지한 마음인 것 같긴 해.",
  ui_story_5017_50171001_97_dialog_content = "일단은 같이 가 보고, 목적이 뭔지 확인해 보는 게 어떨까?",
  ui_story_5017_50171001_98_dialog_content = "린네도 아직 본성에 있으니까 어떻게든 될 거야.",
  ui_story_5017_50171001_99_dialog_content = "헤에, 나도 너희 말이 맞는 것 같아.",
  ui_story_5017_50171001_100_dialog_content = "게다가 그때 무슨 일이 있었는지 우린 아는 게 없잖아.",
  ui_story_5017_50171001_101_dialog_content = "(요우가 기억을 잃은 원인도... 아직 밝혀내지 못했어...)",
  ui_story_5017_50171001_102_dialog_content = "(요우의 기억 속 그 방울 소리는... 정말로 린네가 가진 신악의 방울인 걸까?)",
  ui_story_5017_50171001_103_dialog_content = "(게다가 스승님이라는 그 사람은... 대체 어떤 사람인 거지?)",
  ui_story_5017_50171001_104_dialog_content = "소생을 믿지 못하겠다면 그때가 되어 칼을 뽑을 기회는 얼마든지 있소.",
  ui_story_5017_50171001_105_dialog_content = "후지쿠모의 본성에서 싸워보는 것도... 애당초 해보고 싶던 일이었으니 말이오.",
  ui_story_5017_50171001_106_dialog_content = "응, 그것도 그렇네! 그럼, 네 말대로 할게!",
  ui_story_5017_50171001_107_dialog_content = "왠지 어느 쪽이든 내가 좋아하는 상황이 될 것 같아!",
  ui_story_5017_50171001_108_dialog_content = "그럼 소생을 따라오시오.",
  ui_story_5017_50171001_109_dialog_content = "가자~ 얼른얼른!",
  ui_story_5017_50171001_110_dialog_content = "아하하하하...",
  ui_story_5017_50171001_111_dialog_content = "요우는 정말 긍정적이라니까...",
  ui_story_5017_50171101_1_dialog_content = "<color=#e8d9bb>부스럭부스럭... 부스럭부스럭...</color>",
  ui_story_5017_50171101_2_dialog_content = "주변이 꽤 조용하네...",
  ui_story_5017_50171101_3_dialog_content = "고요한 밤에는 평소에 주의하지 못하는 소리가 들리는 법이오.",
  ui_story_5017_50171101_4_dialog_content = "으으... 아메모리 씨, 그거 그냥 바람 소리 얘기죠...?",
  ui_story_5017_50171101_5_dialog_content = "휘몰아치는 밤바람 소리, 대나무숲에서 우는 벌레 소리,\n참새가 두 발로 땅을 밟는 소리...",
  ui_story_5017_50171101_6_dialog_content = "그리고 소생이 잘 알지 못하는 소리도 있소이다...",
  ui_story_5017_50171101_7_dialog_content = "으엑?!",
  ui_story_5017_50171101_8_dialog_content = "눈을 감으면 그대도 느낄 수 있을 것이오.",
  ui_story_5017_50171101_9_dialog_content = "나, 난 됐어... 그냥 눈 뜨고 있는 거로 할게.",
  ui_story_5017_50171101_10_dialog_content = "아하하! 둘 다 겁먹을 거 없어. 내가 앞장설 테니까!",
  ui_story_5017_50171101_11_dialog_content = "바이스랑 PlayerName 넌 중간에 서고...",
  ui_story_5017_50171101_12_dialog_content = "아메모리, 뒤를 부탁해!",
  ui_story_5017_50171101_13_dialog_content = "그대는 길을 알고 있소?",
  ui_story_5017_50171101_14_dialog_content = "......",
  ui_story_5017_50171101_15_dialog_content = "본성에 들어설 때까지는 사카이 거리의 대로를 따라가면 될 것이오.",
  ui_story_5017_50171101_16_dialog_content = "알겠어요. 그럼 다들 힘내서 가죠.",
  ui_story_5017_50171101_17_dialog_content = "...아메모리?",
  ui_story_5017_50171101_18_dialog_content = "...?",
  ui_story_5017_50171101_19_dialog_content = "스승님에 대해 좀 더 얘기해 줄 수 있어?",
  ui_story_5017_50171101_20_dialog_content = "난 아직도 스승님에 대한 기억은 아무것도 생각이 안 난단 말이야.",
  ui_story_5017_50171101_21_dialog_content = "스승님은 어떤 사람이야?",
  ui_story_5017_50171101_22_dialog_content = "<color=#FFB400>「운도의 총통」</color> 외에도 스승님을 부르는 다른 별호가 있다는 것은 알고 있겠지.",
  ui_story_5017_50171101_23_dialog_content = "스승님의 존함을 직접 부를 수 있는 자는 드물다.\n따라서 운도 사람들은 모두 스승님을 명토의...",
  ui_story_5017_50171101_24_dialog_content = "우웁...우우웁?!",
  ui_story_5017_50171101_25_dialog_content = "어찌 소생의 입을 막는 것이오?!",
  ui_story_5017_50171101_26_dialog_content = "쉿──! 알아, 안다고!",
  ui_story_5017_50171101_27_dialog_content = "그 이름은 다른 사람들 앞에서는 말하면 안 돼. 그건 섬의 규칙이잖아?",
  ui_story_5017_50171101_28_dialog_content = "나도 잘 알고 있다고. 가게 주인장이 알려줬거든.",
  ui_story_5017_50171101_29_dialog_content = "지금 여긴 우리 말고는 아무도 없잖아!",
  ui_story_5017_50171101_30_dialog_content = "...「말하면 안 된다」?",
  ui_story_5017_50171101_31_dialog_content = "흥, 후지쿠모 놈, 스승님을 그렇게까지 기피하는 것인가.",
  ui_story_5017_50171101_32_dialog_content = "<color=#FFB400>명토의 유검</color>, 확실히 본도의 쇼군조차 간담이 서늘해질 이름이지.",
  ui_story_5017_50171101_33_dialog_content = "당시에 후지쿠모는 무사들을 데리고 스승님의 거처를 습격했소...",
  ui_story_5017_50171101_34_dialog_content = "스승님께선 홀로 본도의 세력과 호각으로 맞서셨던 것이오.",
  ui_story_5017_50171101_35_dialog_content = "근데 진 거 아냐?",
  ui_story_5017_50171101_36_dialog_content = "진 것이 아니외다!",
  ui_story_5017_50171101_37_dialog_content = "스승님은 다만... 조용한 곳에서 계속해서 수행을 하시려던 것뿐이오!",
  ui_story_5017_50171101_38_dialog_content = "후지쿠모가 멋대로 꾸며낸 소문을 믿지 말란 말이오...",
  ui_story_5017_50171101_39_dialog_content = "제길...",
  ui_story_5017_50171101_40_dialog_content = "......",
  ui_story_5017_50171101_41_dialog_content = "아메모리 씨... 괜찮아요?",
  ui_story_5017_50171101_42_dialog_content = "아메모리 씨...?",
  ui_story_5017_50171101_43_dialog_content = "아메모리 씨, 어디 간 거지?!",
  ui_story_5017_50171101_44_dialog_content = "엥?!",
  ui_story_5017_50171101_45_dialog_content = "뭐가 어떻게 된 거야? 왜 또 도망간 건데!",
  ui_story_5017_50171101_46_dialog_content = "<color=#e8d9bb>휙──! 휙──!</color>",
  ui_story_5017_50171101_47_dialog_content = "뭔가 있어!",
  ui_story_5017_50171101_48_dialog_content = "뭐지?!",
  ui_story_5017_50171101_49_dialog_content = "그래도 이번엔 나도 준비했으니까... 뭐가 나와도 당황하지 않을 거야!",
  ui_story_5017_50171101_50_dialog_content = "4시 방향에서 온다!",
  ui_story_5017_50171101_51_dialog_content = "기세──",
  ui_story_5017_50171101_X51_dialog_content = "석추침...",
  ui_story_5017_50171101_52_dialog_content = "...소생이오.",
  ui_story_5017_50171101_53_dialog_content = "뭐, 뭐야! 잘도 사라졌다 나타났다 하네!",
  ui_story_5017_50171101_54_dialog_content = "미안하오. 방금 전엔 추태를 보였소.\n길가의 대나무를 베고 왔더니 진정이 되었소이다.",
  ui_story_5017_50171101_55_dialog_content = "...그것도 과장이 너무 심하잖아!",
  ui_story_5017_50171101_56_dialog_content = "휴... 아메모리 씨였구나.",
  ui_story_5017_50171101_57_dialog_content = "난 또 다른 뭔가가 나타난 줄 알고...",
  ui_story_5017_50171101_58_dialog_content = "<color=#e8d9bb>스으윽──</color>",
  ui_story_5017_50171101_59_dialog_content = "히익...?!",
  ui_story_5017_50171101_60_dialog_content = "그어어!",
  ui_story_5017_50171101_61_dialog_content = "그어어!",
  ui_story_5017_50171101_62_dialog_content = "진짜 나타났잖아!",
  ui_story_5017_50171101_63_dialog_content = "소생이 놈들의 주의를 끌겠소.",
  ui_story_5017_50171101_64_dialog_content = "PlayerName, 그대와 바이스는 소생이 놓친 녀석들을 맡아 주시오.",
  ui_story_5017_50171101_65_dialog_content = "요우, 녀석들을 해치우는 건 그대에게 맡기겠소.",
  ui_story_5017_50171101_66_dialog_content = "훗! 이 대협객한테 맡겨줘!",
  ui_story_5017_50171201_1_dialog_content = "<color=#e8d9bb>강부성의 본성, 취설각 안, 쇼군의 방</color>",
  ui_story_5017_50171201_2_dialog_content = "......",
  ui_story_5017_50171201_3_dialog_content = "(아직 찾지 않은 것은 이 방뿐입니다만...)",
  ui_story_5017_50171201_4_dialog_content = "(그러고 보니 합하의 방에 들어가는 것은 처음이로군요.)",
  ui_story_5017_50171201_5_dialog_content = "(방의 구조로 미루어 보면... 구름의 거울을 둔 곳은 아마...)",
  ui_story_5017_50171201_6_dialog_content = "어머.",
  ui_story_5017_50171201_7_dialog_content = "(찾았네요.)",
  ui_story_5017_50171201_8_dialog_content = "(합하께서도 정말 부주의하시군요. 거울을 옷의 앞주머니에 두시다니...)",
  ui_story_5017_50171201_9_dialog_content = "(조금 더 찾기 어려운 곳에 잠가 두었으리라 생각했는데 말이지요...)",
  ui_story_5017_50171201_10_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5017_50171201_11_dialog_content = "누, 누구죠?!",
  ui_story_5017_50171201_12_dialog_content = "누가 감히 합하의 방에 숨어든 것이냐!",
  ui_story_5017_50171201_13_dialog_content = "......",
  ui_story_5017_50171201_14_dialog_content = "...무녀님이셨군요.",
  ui_story_5017_50171201_15_dialog_content = "그렇게 항상 경계해서는 자신에게 부담이 되지 않겠는지요.",
  ui_story_5017_50171201_16_dialog_content = "언제까지 검을 들고 계시려는 것입니까. 설마...",
  ui_story_5017_50171201_17_dialog_content = "제가 위험인물이라 생각하시는지요.",
  ui_story_5017_50171201_18_dialog_content = "합하께선 본성에 안 계십니다. 무녀님은 어찌 이곳에 계십니까?",
  ui_story_5017_50171201_19_dialog_content = "「춘일제」가 곧 시작될 터인데, 운도에는 아직도 이매망량이 창궐하고 있습니다.",
  ui_story_5017_50171201_20_dialog_content = "이에 구름의 거울로 저들을 쫓고자 하는데, 저를 막으실 생각이신지요.",
  ui_story_5017_50171201_21_dialog_content = "합하께서 허락하신 일입니까?",
  ui_story_5017_50171201_22_dialog_content = "합하의 허락 없이 구름의 거울을 사용한 전례는 없습니다.",
  ui_story_5017_50171201_23_dialog_content = "그렇다면 구름의 거울을 가지고 합하께 말씀을 여쭈러 가도록 하지요.",
  ui_story_5017_50171201_24_dialog_content = "무사 나리, 그럼 길을 열어주십시오.",
  ui_story_5017_50171201_25_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5017_50171201_26_dialog_content = "?!",
  ui_story_5017_50171201_27_dialog_content = "그 어떤 정당해 보이는 이유를 대신다 해도...",
  ui_story_5017_50171201_28_dialog_content = "합하의 허락이 없는 한 이곳을 지나실 수는 없습니다.",
  ui_story_5017_50171201_29_dialog_content = "무녀님, 부디 소인을 곤란하게 만들지 마십시오.",
  ui_story_5017_50171201_30_dialog_content = "합하께서 계속 돌아오지 않으신다면, 당신들도 이렇게 계속 절 막을 요량은 아니겠지요.",
  ui_story_5017_50171201_31_dialog_content = "한 마디의 허락을 위해 춘일제가 시작될 때까지 이대로 사태를 방치하자는 것입니까?",
  ui_story_5017_50171201_32_dialog_content = "...당신은 확실히 지금까지의 무녀와는 다르시군요.",
  ui_story_5017_50171201_33_dialog_content = "운도 백성들이 당신을 대하는 태도를... 조금은 이해할 수 있을 듯합니다.",
  ui_story_5017_50171201_34_dialog_content = "...!",
  ui_story_5017_50171201_35_dialog_content = "......",
  ui_story_5017_50171201_36_dialog_content = "후훗, 무사 나리, 혹시 거울을 보는 습관이 있으신지요.",
  ui_story_5017_50171201_37_dialog_content = "...무녀님, 부디 합하의 뜻을 거스르지 마십시오.",
  ui_story_5017_50171201_38_dialog_content = "구름의 거울은 비록 제가 다룰 수 있는 것이라고 하지만,\n이렇게 들고 있으니 왠지 제어할 수 없는 힘이 느껴지는 듯합니다.",
  ui_story_5017_50171201_39_dialog_content = "운도의 전설에 따르면 이 구름의 거울은 상서로운 힘이 있어,\n생사나 길흉을 예견할 수 있다고 합니다만...",
  ui_story_5017_50171201_40_dialog_content = "다른 전설에서는 이것이 불길한 물건이라는 이야기도 있답니다...",
  ui_story_5017_50171201_41_dialog_content = "따라서 중요한 순간이 아니라면 거울을 덮어 두어야 하는 것이지요.",
  ui_story_5017_50171201_42_dialog_content = "당신은 어떻게 생각하시는지요, 무사 나리.",
  ui_story_5017_50171201_43_dialog_content = "...무녀님, 구름의 거울을 내려 놓으십시오.",
  ui_story_5017_50171201_44_dialog_content = "정말 융통성 없는 분이시군요.",
  ui_story_5017_50171201_45_dialog_content = "<color=#e8d9bb>탁──</color>",
  ui_story_5017_50171201_46_dialog_content = "무녀님, 부디 실례를 용서하시길──",
  ui_story_5017_50171201_47_dialog_content = "훗...",
  ui_story_5017_50171201_48_dialog_content = "「지혜와 명정, 심신의 안정을 비나니, 삼혼이 영원하여 혼백이 이울지 않케 하소서」──",
  ui_story_5017_50171201_49_dialog_content = "으윽... 음...",
  ui_story_5017_50171201_50_dialog_content = "정말 유용하네요... 부디 잠을 나쁘게 여기지 마세요.",
  ui_story_5017_50171201_51_dialog_content = "(정심주를 읊는 것만으로도 구름의 거울로 사람을 잠들게 할 수 있다니...)",
  ui_story_5017_50171201_52_dialog_content = "(확실히 함부로 다루어서는 안 될 물건이로군요. 부정한 자의 손에 넘어가기라도 한다면...)",
  ui_story_5017_50171201_53_dialog_content = "(허나... 「춘일제」를 무사히 치르기 위해서는...)",
  ui_story_5017_50171201_54_dialog_content = "(죄송합니다, 합하... 금방 다시 가져다 두겠습니다.)",
  ui_story_5017_50171201_55_dialog_content = "<color=#e8d9bb>강부성 번화가의 어느 거리</color>",
  ui_story_5017_50171201_56_dialog_content = "(강부성에 부정한 존재들이 점점 더 늘어나고 있습니다...)",
  ui_story_5017_50171201_57_dialog_content = "(저는 물론 괜찮습니다만, PlayerName 님과 친구분들은 괜찮으실지...)",
  ui_story_5017_50171201_58_dialog_content = "<color=#e8d9bb>휘리릭──</color>",
  ui_story_5017_50171201_59_dialog_content = "?!",
  ui_story_5017_50171201_60_dialog_content = "악령은 물러나라!",
  ui_story_5017_50171201_61_dialog_content = "흐음...",
  ui_story_5017_50171201_62_dialog_content = "빠른 초식이나, 유감스럽게도 소생에게는 효과가 없소이다.",
  ui_story_5017_50171201_63_dialog_content = "어머... 닌자 나리셨군요.",
  ui_story_5017_50171201_64_dialog_content = "지금은 착한 아이라면 잠을 청할 시간이라 생각합니다만.",
  ui_story_5017_50171201_65_dialog_content = "물론 당신을 거울의 힘을 시험할 상대로 삼는 것도 좋겠지요.",
  ui_story_5017_50171201_66_dialog_content = "아, 린네! 구름의 거울을 찾았어?",
  ui_story_5017_50171201_67_dialog_content = "...요우! PlayerName 님과 바이스 님도 계셨나요?",
  ui_story_5017_50171201_68_dialog_content = "그러면 여러분은... 지금 닌자 나리와 함께 오셨던 것인지요.",
  ui_story_5017_50171201_69_dialog_content = "아, 그게 설명하긴 좀 복잡한데, 아무튼...",
  ui_story_5017_50171201_70_dialog_content = "린네, 무서워하지 않아도 돼. 아메모리는 이제 널 해치지 않을 거야!",
  ui_story_5017_50171201_71_dialog_content = "...어머, 요우, 지금 닌자 나리를 감싸시는 것인지요.",
  ui_story_5017_50171201_72_dialog_content = "어, 엄청 무서운 웃음이네...",
  ui_story_5017_50171201_73_dialog_content = "믿을지 말지는 그대 마음대로 하시오.",
  ui_story_5017_50171201_74_dialog_content = "익숙하지 않은 상대에게는 항상 경계를 늦춰서는 안 되는 법,\n그것은 소생도 같은 생각이니 말이오.",
  ui_story_5017_50171201_75_dialog_content = "참! 린네, 아까 너 없을 때 아메모리가 너에 대해 한 말이 있...",
  ui_story_5017_50171201_76_dialog_content = "으앗!",
  ui_story_5017_50171201_77_dialog_content = "...너 왜 내 단전을 있는 힘껏 노리는 거야?!",
  ui_story_5017_50171201_78_dialog_content = "쓸데없는 말은 삼가시오.",
  ui_story_5017_50171201_79_dialog_content = "어머, 과연 무슨 일이었을까요? 제가 어떻다는 것인지요.",
  ui_story_5017_50171201_80_dialog_content = "과연 닌자 나리께서 저를 어떻게 평가하셨을지 실로 흥미가 생기는군요.",
  ui_story_5017_50171201_81_dialog_content = "...쿠나이나 받으시오!",
  ui_story_5017_50171201_82_dialog_content = "자, 자, 그만해! 내가 설명할 테니까!\n아메모리는 이번에 우리한테 부탁할 일이 있어서 동행하게 됐어.",
  ui_story_5017_50171201_83_dialog_content = "아메모리는...",
  ui_story_5017_50171201_84_dialog_content = "그대들과 함께 강부성의 오니를 소탕할 것이오.",
  ui_story_5017_50171201_85_dialog_content = "(뭐? 아까랑 얘기가 다르잖아!)",
  ui_story_5017_50171201_86_dialog_content = "(으음?)",
  ui_story_5017_50171201_87_dialog_content = "<size=30>부탁이오. 지금은 아직 당사자가 아닌 이에게는 알리고 싶지 않소.</size>",
  ui_story_5017_50171201_88_dialog_content = "(...그런 거였구나. 그럼 일단 그렇게 믿어둬야겠네...)",
  ui_story_5017_50171201_89_dialog_content = "구름의 거울이 있다면 강부성은 분명히 하루빨리 안녕을 되찾을 수 있을 것이오.",
  ui_story_5017_50171201_90_dialog_content = "(정말 진지한 모습이군요. 닌자 나리... 이마에 땀이 흐르고 있네요...)",
  ui_story_5017_50171201_91_dialog_content = "(대체 무슨 이유를 들어 PlayerName 님께 동행할 것을 설득했을까요...)",
  ui_story_5017_50171201_92_dialog_content = "(일단은 믿는 척하기로 하지요... 후훗, 갑자기 일이 재미있어지는걸요...)",
  ui_story_5017_50171201_93_dialog_content = "PlayerName 님이 그렇게 말씀하신다면...",
  ui_story_5017_50171201_94_dialog_content = "저는 물론 상관없습니다.",
  ui_story_5017_50171201_95_dialog_content = "게다가, 실로 감동적이었습니다...",
  ui_story_5017_50171201_96_dialog_content = "우리 <color=#FFB400>아메모리 님</color>께서 이토록 운도의 백성을 생각하고 계셨다니요.",
  ui_story_5017_50171201_97_dialog_content = "으윽...",
  ui_story_5017_50171201_98_dialog_content = "후훗... 그런 열정을 냉혹한 외모 속에 감추고 계셨다니, 그것이 바로 인술의 오의인가요?",
  ui_story_5017_50171201_99_dialog_content = "갑자기 아메모리 님이 존경스러워지는군요.",
  ui_story_5017_50171201_100_dialog_content = "...소생을 조롱하지 마시오!",
  ui_story_5017_50171201_101_dialog_content = "잠깐...",
  ui_story_5017_50171201_102_dialog_content = "위험하오!",
  ui_story_5017_50171201_103_dialog_content = "그어어!",
  ui_story_5017_50171201_104_dialog_content = "괜찮습니다. 그저 구름의 거울을 사용할 때가 된 것이지 않습니까.",
  ui_story_5017_50171201_105_dialog_content = "이것으로 아메모리 님의 「강부성 오니 소탕」이라는 목표에 한 걸음 더 다가서겠지요.",
  ui_story_5017_50171201_106_dialog_content = "(정말 싫은 여자다...)",
  ui_story_5017_50171301_1_dialog_content = "「금운이 솟아 십방을 비추나니, 귀요는 낙담하고 정괴는 소망할지어다」──",
  ui_story_5017_50171301_2_dialog_content = "으윽...",
  ui_story_5017_50171301_3_dialog_content = "끄어어...",
  ui_story_5017_50171301_4_dialog_content = "그으으...",
  ui_story_5017_50171301_5_dialog_content = "순식간에 사라져 버렸어!",
  ui_story_5017_50171301_6_dialog_content = "그 거울... 생각했던 것보다 훨씬 대단하네요!",
  ui_story_5017_50171301_7_dialog_content = "후훗, 당연합니다. 이는 본디 「춘일제」에서 망령 정화에 쓰였던 신기이기 때문이지요.",
  ui_story_5017_50171301_8_dialog_content = "이번에는 「춘일제」가 무사히 개최될 수 있도록 미리 가지고 나온 것입니다.",
  ui_story_5017_50171301_S8_dialog_content = "우와! 그렇게 대단한 물건이 있었다니... 오니한테 비추기만 해도 「정화」가 되는 건가...",
  ui_story_5017_50171301_S9_dialog_content = "린네가 말한 「정화」는 또 무슨 뜻인데?",
  ui_story_5017_50171301_S10_dialog_content = "후훗... 물론 전부 죽.여.버.린.다는 뜻이랍니다.",
  ui_story_5017_50171301_9_dialog_content = "이 망령들에게 있어 거울의 힘으로 한시라도 빨리 왕생할 수 있는 것은...",
  ui_story_5017_50171301_10_dialog_content = "영예로운 일이지요.",
  ui_story_5017_50171301_11_dialog_content = "......",
  ui_story_5017_50171301_12_dialog_content = "요우, 혹시... 뭔가 생각난 것이오?",
  ui_story_5017_50171301_13_dialog_content = "나...",
  ui_story_5017_50171301_14_dialog_content = "저 거울, 본 적 있는 것 같아...",
  ui_story_5017_50171301_15_dialog_content = "본 적이 있으시다고요? 그럴 리가 없습니다.\n거울의 힘을 받은 자는 모두 죽어서 없는걸요.",
  ui_story_5017_50171301_16_dialog_content = "정말 직설적인 말이네...",
  ui_story_5017_50171301_17_dialog_content = "게다가 요우는 「춘일제」에 참가한 적이 없지 않나요... 그러니 본 적이 있을 리가...",
  ui_story_5017_50171301_18_dialog_content = "으음... 나도 잘은 모르겠어. 하지만 그 거울을 보고 있으면 왠지...",
  ui_story_5017_50171301_19_dialog_content = "<color=#FFB400>「무녀를... 죽인다...」</color>",
  ui_story_5017_50171301_20_dialog_content = "?!",
  ui_story_5017_50171301_21_dialog_content = "요, 요우?!",
  ui_story_5017_50171301_22_dialog_content = "요우, 방금 얼마나 무서운 말을 했는지 알고 계신가요?",
  ui_story_5017_50171301_23_dialog_content = "설마 아메모리에게 물들어 버린 건가요?",
  ui_story_5017_50171301_24_dialog_content = "바...방금 그건 내가 말한 게 아냐!\n그냥 갑자기... 이 「능인옥」에 담긴 사념이 느껴져서...",
  ui_story_5017_50171301_25_dialog_content = "내가 린네를 해치고 싶을 리가 없잖아!",
  ui_story_5017_50171301_26_dialog_content = "오히려 난 린네를 처음 만났을 때부터 왠지 모르게 정말 친밀한 느낌을 받았다구!",
  ui_story_5017_50171301_27_dialog_content = "으으... 이 「능인옥」... 대체 나한테 뭘 말하려고 하는 거지?",
  ui_story_5017_50171301_28_dialog_content = "......",
  ui_story_5017_50171301_29_dialog_content = "(「능인옥」에 담긴 사념이라...)",
  ui_story_5017_50171301_30_dialog_content = "(스승님, <color=#FFB400>그때 그 사건</color>에서 당신과 요우는 대체 어떤 경험을 하신 것입니까...)",
  ui_story_5017_50171301_31_dialog_content = "<color=#e8d9bb>끽, 끼긱, 까드득... 끼릭...</color>",
  ui_story_5017_50171301_32_dialog_content = "어라?",
  ui_story_5017_50171301_33_dialog_content = "이 소리... 엄청 기분 나쁜데...",
  ui_story_5017_50171301_34_dialog_content = "...거울에 죽은 오니들을 조심하시오!",
  ui_story_5017_50171301_35_dialog_content = "<color=#e8d9bb>끽, 끼긱, 까드득... 끼릭...</color>",
  ui_story_5017_50171301_36_dialog_content = "그르르...",
  ui_story_5017_50171301_37_dialog_content = "그어어!",
  ui_story_5017_50171301_38_dialog_content = "어, 어째서?!",
  ui_story_5017_50171301_39_dialog_content = "분명 구름의 거울을 사용했을 터인데... 어찌 망령들이 되살아난단 말입니까?!",
  ui_story_5017_50171301_40_dialog_content = "지금까지 「춘일제」에서 이런 일이 일어난 적은 없었습니다!",
  ui_story_5017_50171301_41_dialog_content = "그어어!",
  ui_story_5017_50171301_42_dialog_content = "말도 안 됩니다... 이런 일은 절대 있을 수 없습니다!",
  ui_story_5017_50171301_S42_dialog_content = "대대로 전해진 구름의 거울은 이매망량을 퇴치하는 법기라고...",
  ui_story_5017_50171301_S43_dialog_content = "분명히 합하께서 말씀해 주신 것입니다만...",
  ui_story_5017_50171301_43_dialog_content = "그저 이 구름의 거울만 있으면... 거울의 힘을 다시 한번 사용한다면...",
  ui_story_5017_50171301_44_dialog_content = "「금운이 솟아 십방을 비추나니, 귀요는 낙담하고 정괴는 소망할지어다」──",
  ui_story_5017_50171301_45_dialog_content = "...으윽!",
  ui_story_5017_50171301_46_dialog_content = "(...갑자기 몸에 통증이... 이건 대체...)",
  ui_story_5017_50171301_S46_dialog_content = "(구름의 거울...)",
  ui_story_5017_50171301_47_dialog_content = "그어어!",
  ui_story_5017_50171301_48_dialog_content = "그어어!",
  ui_story_5017_50171301_49_dialog_content = "기세── 석추침해!",
  ui_story_5017_50171301_S49_dialog_content = "구름의 거울이 오니를 물리친다고 한 거 아니었어? 왜 오니들이 오히려 다시 살아나는 건데?!",
  ui_story_5017_50171301_50_dialog_content = "린네! 일단은 그 거울을 쓰지 마! 오니들은 내가 다시 해치울 테니까!",
  ui_story_5017_50171301_51_dialog_content = "오의! 그림자 쫓기 술법!",
  ui_story_5017_50171301_52_dialog_content = "끄어어...",
  ui_story_5017_50171301_53_dialog_content = "......",
  ui_story_5017_50171301_54_dialog_content = "지금은 거울의 문제를 따질 때가 아니오...",
  ui_story_5017_50171301_55_dialog_content = "이 오니들이 나타난 방향...",
  ui_story_5017_50171301_56_dialog_content = "...저쪽은... 강부성의 본성이 아닙니까?!",
  ui_story_5017_50171301_57_dialog_content = "본성은 결코 위험에 처해서는 안 됩니다!",
  ui_story_5017_50171301_58_dialog_content = "여러분, 부디 저와 함께 「부정함」을 없애고 본성의 안전을 지켜 주십시오!",
  ui_story_5017_50171301_59_dialog_content = "...우연이지만 지금은 목적이 일치하게 된 모양이오.",
  ui_story_5017_50171301_60_dialog_content = "본성 내부의 길 안내는 그대에게 부탁하겠소.",
  ui_story_5017_50171301_61_dialog_content = "<color=#e8d9bb>강부성의 본성, 운수각 안, 봉인의 땅 근처</color>",
  ui_story_5017_50171301_62_dialog_content = "......",
  ui_story_5017_50171301_63_dialog_content = "......",
  ui_story_5017_50171301_64_dialog_content = "...?",
  ui_story_5017_50171301_65_dialog_content = "공기가 답답해...",
  ui_story_5017_50171301_66_dialog_content = "쉿, 린네를 방해하면 안 돼.",
  ui_story_5017_50171301_67_dialog_content = "?!",
  ui_story_5017_50171301_68_dialog_content = "「척귀능인」의 힘이 강해지고 있소.",
  ui_story_5017_50171301_69_dialog_content = "가까워지고 있는 것이오.",
  ui_story_5017_50171301_70_dialog_content = "이쪽이 틀림없습니다. 느껴집니다...",
  ui_story_5017_50171301_71_dialog_content = "「부정」한 기운이 그 어느 때보다 더 뚜렷합니다.",
  ui_story_5017_50171301_72_dialog_content = "......",
  ui_story_5017_50171301_73_dialog_content = "「부정」하다고? 내 스승님이 부정할 리가 없잖아!",
  ui_story_5017_50171301_74_dialog_content = "네? 요우의... 스승님?",
  ui_story_5017_50171301_75_dialog_content = "...참으로 성가신 사매이지 않은가...",
  ui_story_5017_50171301_76_dialog_content = "...어쩔 수 없군. 지금이라면 말해 두어도 좋을 것 같소.",
  ui_story_5017_50171301_77_dialog_content = "지금 그대가 안내하는 것은 봉인의 땅으로 가는 길이외다.",
  ui_story_5017_50171301_78_dialog_content = "봉인의 땅?",
  ui_story_5017_50171301_79_dialog_content = "합하로부터 그러한 것은 들어본 적이 없습니다...",
  ui_story_5017_50171301_80_dialog_content = "소생과 요우의 스승님은 지금 후지쿠모에 의해 봉인의 땅에 갇혀 있소.",
  ui_story_5017_50171301_81_dialog_content = "스승님? 그렇다면... 봉인의 땅에 갇혀 있는 「부정한 것」이란...",
  ui_story_5017_50171301_82_dialog_content = "그대는 자신이 느끼는 「부정함」이...",
  ui_story_5017_50171301_83_dialog_content = "본성에 침입한 오니라 생각하는가, 아니면 소생의 스승님이라 생각하는가.",
  ui_story_5017_50171301_84_dialog_content = "그게 아니라면 무엇이겠는지요.",
  ui_story_5017_50171301_85_dialog_content = "......",
  ui_story_5017_50171301_86_dialog_content = "소생은 그대가 쉽게 납득하리라 생각하지 않았소.",
  ui_story_5017_50171301_87_dialog_content = "이 모퉁이를 돌면 우린 목적지에 도착할 수 있을 것이오...",
  ui_story_5017_50171301_88_dialog_content = "이번에 소생이 그대와 함께 온 것에는 확실히 다른 목적이 있었소.",
  ui_story_5017_50171301_89_dialog_content = "부디 그대의 힘으로 스승님을 붙잡고 있는 마의 장벽을 제거해 주었으면 하오.",
  ui_story_5017_50171301_90_dialog_content = "그 마의 장벽이야말로 진정한 「부정함」이외다.",
  ui_story_5017_50171301_91_dialog_content = "린네, 자기 눈으로 직접 확인해 보시오.",
  ui_story_5017_50171301_92_dialog_content = "대체 무엇이 후지쿠모를 섬기고 있는지...",
  ui_story_5017_50171301_93_dialog_content = "그게 무슨...",
  ui_story_5017_50171301_94_dialog_content = "그어어──",
  ui_story_5017_50171301_95_dialog_content = "뭐야?! 이 오니들... 왜 강부성의 옷을 입고 있지?!",
  ui_story_5017_50171301_96_dialog_content = "정말 그렇군요... 이 오니들... 모두...",
  ui_story_5017_50171301_97_dialog_content = "옷에 합하의 문장이 수놓아져 있습니다...",
  ui_story_5017_50171301_98_dialog_content = "그어어...",
  ui_story_5017_50171301_99_dialog_content = "크오오!",
  ui_story_5017_50171301_100_dialog_content = "이 오니들... 꼭 의식이 있는 것처럼 보여!",
  ui_story_5017_50171301_101_dialog_content = "(놀라운 적응력에... 모종의 의식에 따라 움직이고, 목적도 단순하고 명확해...)",
  ui_story_5017_50171301_X101_dialog_content = "(이렇게 진화하고, 명령에 복종하고, 우리를 공격하는 건...)",
  ui_story_5017_50171301_102_dialog_content = "(놈들을 「특수한 암귀」라 불러도 이상할 게 없잖아...)",
  ui_story_5017_50171301_103_dialog_content = "뭘 멍하니 있는 것이오, 린네.",
  ui_story_5017_50171301_104_dialog_content = "이 오니 무사들은 보통의 방식으로는 멸할 수 없소...",
  ui_story_5017_50171301_105_dialog_content = "치열한 싸움이 될 것이오. 모두 만반의 준비를 하는 게 좋을 게요.",
  ui_story_5017_50171301_106_dialog_content = "하지만... 저는 이들이 어째서 여기 나타난 것인지 모르겠습니다...",
  ui_story_5017_50171301_107_dialog_content = "오니들이 이 정도로 「무언가를 지킨다」는 의식을 가지는 것은...\n결코 있을 수 없는 일입니다...",
  ui_story_5017_50171301_108_dialog_content = "합하께선 어째서 이곳에 오니를 두신 것일까요...",
  ui_story_5017_50171301_109_dialog_content = "합하께서는... 대체 무엇을... 하시려는 것인지요...",
  ui_story_5017_50171301_110_dialog_content = "적당히 하시오!",
  ui_story_5017_50171301_111_dialog_content = "「어떤 입장에 서 있더라도, 우리의 적은 오직 오니뿐이다.」",
  ui_story_5017_50171301_112_dialog_content = "소생에게 그렇게 말한 것은 그대였지 않은가!",
  ui_story_5017_50171301_113_dialog_content = "...?!",
  ui_story_5017_50171301_114_dialog_content = "아메모리...",
  ui_story_5017_50171301_115_dialog_content = "좋아! 내 손끝의 힘은 벌써 타오르고 있다구!",
  ui_story_5017_50171301_116_dialog_content = "바이스, PlayerName, 준비됐어?",
  ui_story_5017_50171301_117_dialog_content = "이 오니인지 인간인지 모를 녀석들이랑 시원하게 한판 붙어보자구!",
  ui_story_5017_50171301_118_dialog_content = "흐아압──",
  ui_story_5017_50171302_1_dialog_content = "끄어어...",
  ui_story_5017_50171302_2_dialog_content = "후, 후우──",
  ui_story_5017_50171302_3_dialog_content = "정말 통쾌한 싸움이었어!",
  ui_story_5017_50171302_4_dialog_content = "크어어!",
  ui_story_5017_50171302_5_dialog_content = "이제... 마지막 한 무리야!",
  ui_story_5017_50171302_6_dialog_content = "정화될지어다...",
  ui_story_5017_50171302_7_dialog_content = "신역을 여기에!",
  ui_story_5017_50171302_8_dialog_content = "으어...",
  ui_story_5017_50171302_9_dialog_content = "휴...",
  ui_story_5017_50171302_10_dialog_content = "끝났소.",
  ui_story_5017_50171302_11_dialog_content = "......",
  ui_story_5017_50171302_12_dialog_content = "린네 씨! 방금 그 정화 의식... 정말 대단했어요.",
  ui_story_5017_50171302_13_dialog_content = "거울의 힘 없이도 전혀 빈틈이 없었잖아요...",
  ui_story_5017_50171302_14_dialog_content = "그러니까 이번 「춘일제」에서는 훌륭한 무녀로서 운도 사람들 앞에 설 수 있을 거예요!",
  ui_story_5017_50171302_15_dialog_content = "후훗... 그런가요.",
  ui_story_5017_50171302_16_dialog_content = "전 줄곧 기대해 왔습니다. 합하와 운도의 백성 모두가 인정하는 어엿한 무녀가 되어...\n「춘일제」에 나서는 것을 말이지요...",
  ui_story_5017_50171302_17_dialog_content = "허나 지금 저는 구름의 거울의 진정한 힘조차 알지 못합니다.",
  ui_story_5017_50171302_18_dialog_content = "그동안 성의 망령을 쫓고, 「춘일제」를 방해하는 일체의 요소를 처리해 왔습니다만...",
  ui_story_5017_50171302_19_dialog_content = "오니가 강부성의 본성 안을 서성거리고 있으리라고는 생각도 하지 못했습니다.",
  ui_story_5017_50171302_20_dialog_content = "후후훗...",
  ui_story_5017_50171302_21_dialog_content = "린네...",
  ui_story_5017_50171302_22_dialog_content = "그렇지 않아, 린네.",
  ui_story_5017_50171302_23_dialog_content = "너한테는 정말 「춘일제」에서 인정받는 게 가장 중요한 일인 거야?",
  ui_story_5017_50171302_24_dialog_content = "아니, 내가 보기엔...",
  ui_story_5017_50171302_25_dialog_content = "(으... 정말 말해도 되는 걸까...)",
  ui_story_5017_50171302_26_dialog_content = "......",
  ui_story_5017_50171302_27_dialog_content = "우리가 위험에 처했을 때, 모두를 지키기 위해 네가 오니를 막은 그 순간...",
  ui_story_5017_50171302_28_dialog_content = "네가 보여줬던 신념을 난 확실하게 느낄 수 있었어.",
  ui_story_5017_50171302_29_dialog_content = "......",
  ui_story_5017_50171302_30_dialog_content = "결과를 무릅쓰고 「죽음」에 맞서서, 본능으로 모든 「삶」을 지키려 했던...",
  ui_story_5017_50171302_31_dialog_content = "그런 너라면 이미 오래전에 어엿한 무녀가 되었다고 생각해.",
  ui_story_5017_50171302_32_dialog_content = "그러니까... 괴로워할 필요는 없어.",
  ui_story_5017_50171302_33_dialog_content = "......",
  ui_story_5017_50171302_34_dialog_content = "...후훗.",
  ui_story_5017_50171302_35_dialog_content = "PlayerName 님은 정말 사랑스러운 분이시군요. 제가 괴로워 보이셨나요?",
  ui_story_5017_50171302_36_dialog_content = "(뭐, 그런대로 기분이 안정된 것 같네...)",
  ui_story_5017_50171302_37_dialog_content = "우와, 빨라! 그거 극동에 전해지는 「얼굴 바꾸기」 술법이지?!",
  ui_story_5017_50171302_38_dialog_content = "으엑?!",
  ui_story_5017_50171302_39_dialog_content = "...으음?",
  ui_story_5017_50171302_40_dialog_content = "어머, 그것은...",
  ui_story_5017_50171302_41_dialog_content = "<color=#e8d9bb>찰랑──</color>",
  ui_story_5017_50171302_42_dialog_content = "어라? 사라졌어?",
  ui_story_5017_50171302_43_dialog_content = "아니, 사라진 것이 아니오...",
  ui_story_5017_50171302_44_dialog_content = "<color=#e8d9bb>쿠르르르──</color>",
  ui_story_5017_50171302_45_dialog_content = "봉인의 땅이... 엄청 흔들리고 있어...",
  ui_story_5017_50171302_46_dialog_content = "스승님은 역시... 살아계셨소...",
  ui_story_5017_50171302_47_dialog_content = "「척귀능인」이 부름에 따라 스승님 곁으로 돌아간 것이오!",
  ui_story_5017_50171302_48_dialog_content = "합하께서 이런 곳에 봉인한 자라면, 대체 어떤 악령일까요...",
  ui_story_5017_50171302_49_dialog_content = "악령인지 무엇인지는 곧 알 수 있을 것이외다.",
  ui_story_5017_50171401_1_dialog_content = "<color=#e8d9bb>쿠르르르──</color>",
  ui_story_5017_50171401_2_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5017_50171401_3_dialog_content = "후우...",
  ui_story_5017_50171401_4_dialog_content = "받은 물건을 제 발로 돌려주러 오다니, 무슨 생각이냐.",
  ui_story_5017_50171401_5_dialog_content = "오랜만이로구나, 내 제자들아.",
  ui_story_5017_50171401_6_dialog_content = "...스승님!",
  ui_story_5017_50171401_7_dialog_content = "그간 고초가 많으셨습니다...\n소생은 줄곧 스승님께서 건재하심을 굳게 믿고 있었습니다.",
  ui_story_5017_50171401_8_dialog_content = "소생의 인법첩에도 많은 심득을 기록했습니다...\n그저 스승님께서 돌아와 읽어주실 날을 기다리며...",
  ui_story_5017_50171401_9_dialog_content = "......",
  ui_story_5017_50171401_10_dialog_content = "아메모리, 너는 여전하구나.",
  ui_story_5017_50171401_11_dialog_content = "때로는 애써 무정한 척하고, 때로는 없어야 할 동정과 나약함을 보인다.",
  ui_story_5017_50171401_12_dialog_content = "가장한 무심함도, 무익한 동정과 나약함도 옳지 못한 것.",
  ui_story_5017_50171401_13_dialog_content = "모두 네가 「감정」에 얽매여 마음에 두고 있기 때문이다.",
  ui_story_5017_50171401_14_dialog_content = "이 세상을 살아간다면 「감정」 따위는 잊어버리는 게 좋을 게다.",
  ui_story_5017_50171401_15_dialog_content = "스승님...",
  ui_story_5017_50171401_16_dialog_content = "스승님의 가르침, 소생 반드시 명심하겠습니다...!",
  ui_story_5017_50171401_17_dialog_content = "하하... 요우, 역시 왔구나.",
  ui_story_5017_50171401_18_dialog_content = "스승님...?",
  ui_story_5017_50171401_19_dialog_content = "아...저기... 정말 제 스승님이세요?",
  ui_story_5017_50171401_20_dialog_content = "(이 사람도... 내 이름을 알아...)",
  ui_story_5017_50171401_21_dialog_content = "(근데 왜일까... 이 사람을 보면 두려운 마음이 들어...)",
  ui_story_5017_50171401_22_dialog_content = "(아니야... 너무 많이 생각하지 말자... 공포는 기공술의 금기야!)",
  ui_story_5017_50171401_23_dialog_content = "...이번에 제가 운도에 온 건... 10년 전 일을 확실히 알고 싶어서예요.",
  ui_story_5017_50171401_24_dialog_content = "전 오랫동안 제 혼란스러운 기억 때문에 괴로웠어요!",
  ui_story_5017_50171401_25_dialog_content = "방울 소리가 계속 들리고... 어딘가 익숙한 그 거울까지...",
  ui_story_5017_50171401_26_dialog_content = "어째서 전부 「춘일제」와 관계가 있는 거죠?",
  ui_story_5017_50171401_27_dialog_content = "당신이 만약 정말 제 스승님이라면, 반드시 전부 알고 있겠죠!",
  ui_story_5017_50171401_28_dialog_content = "요우, 10년 동안 많이 자랐구나.",
  ui_story_5017_50171401_29_dialog_content = "물론 넌 모든 것을 알 권리가 있다. 허나──",
  ui_story_5017_50171401_30_dialog_content = "지금은 좋은 시기가 아니다.",
  ui_story_5017_50171401_31_dialog_content = "내겐 아직 해야 할 중요한 일이 있으니 말이다.",
  ui_story_5017_50171401_32_dialog_content = "어이... 너.",
  ui_story_5017_50171401_33_dialog_content = "......",
  ui_story_5017_50171401_34_dialog_content = "그 옷차림을 보니 네가 후지쿠모의 새 무녀겠구나.",
  ui_story_5017_50171401_35_dialog_content = "...후후, <color=#FFB400>그 무녀</color>와는 조금도 닮지 않았잖아.",
  ui_story_5017_50171401_36_dialog_content = "으읏... 손을 치워주시지요!",
  ui_story_5017_50171401_37_dialog_content = "말해라. 후지쿠모는 지금 강부성에 있나?",
  ui_story_5017_50171401_38_dialog_content = "...그게 당신과 무슨 상관이 있는지요.",
  ui_story_5017_50171401_39_dialog_content = "흥, 예상했던 답이다.",
  ui_story_5017_50171401_40_dialog_content = "후지쿠모의 졸개들은 충성심 하나는 강했지.",
  ui_story_5017_50171401_41_dialog_content = "뭐, 그것도 그리 중요한 것은 아니다만.",
  ui_story_5017_50171401_42_dialog_content = "허나... 후지쿠모 녀석이 없다면, 일은 더 수월할 것이다.",
  ui_story_5017_50171401_43_dialog_content = "멈추세요!",
  ui_story_5017_50171401_44_dialog_content = "뭘 하려는 것입니까?!",
  ui_story_5017_50171401_45_dialog_content = "(으윽...)",
  ui_story_5017_50171401_46_dialog_content = "린네 씨...! 괜찮아요?!",
  ui_story_5017_50171401_47_dialog_content = "괜찮습니다... 그 누구라도 강부성의 안위를 해치는 자는 제가 용서하지 않습니다!",
  ui_story_5017_50171401_48_dialog_content = "...귀찮구나.",
  ui_story_5017_50171401_49_dialog_content = "너도 후지쿠모에게 오랜 시간 이용당한 것이겠지.",
  ui_story_5017_50171401_50_dialog_content = "...합하의 노고를 당신이 왈가왈부할 자격은 없습니다!",
  ui_story_5017_50171401_51_dialog_content = "너는 생각보다 의지가 강하구나.",
  ui_story_5017_50171401_52_dialog_content = "그렇다면 더 이상의 이야기는 필요하지 않겠지.",
  ui_story_5017_50171401_53_dialog_content = "린네! 피해!",
  ui_story_5017_50171401_54_dialog_content = "...?!",
  ui_story_5017_50171401_55_dialog_content = "<color=#e8d9bb>스륵──</color>",
  ui_story_5017_50171401_56_dialog_content = "악령은 물러나라!",
  ui_story_5017_50171401_57_dialog_content = "스승님... 위험합니다!",
  ui_story_5017_50171401_58_dialog_content = "후후, 기민한 반응이로다... 아무래도 이렇게 해결하는 게 피차 손쉬울 성싶구나.",
  ui_story_5017_50171401_59_dialog_content = "스승님... 괜찮으십니까?",
  ui_story_5017_50171401_60_dialog_content = "부디 존체를 생각해서... 검을 거두어 주십시오.\n이제 막 풀려나셨으니, 곧바로 합을 겨루는 것은 상책이 아닙니다.",
  ui_story_5017_50171401_61_dialog_content = "스승님, 운도는 총통 없이는 존립할 수 없습니다... 부디 저와 함께 가시지요.",
  ui_story_5017_50171401_62_dialog_content = "...나를 막겠다는 것이냐?",
  ui_story_5017_50171401_63_dialog_content = "소생은... 그저...",
  ui_story_5017_50171401_64_dialog_content = "스승님을 계속 따르고 싶을 뿐입니다.",
  ui_story_5017_50171401_65_dialog_content = "벌써 10년이 되었습니다. 모두가 스승님께서 돌아오시길 기다리고 있습니다.",
  ui_story_5017_50171401_66_dialog_content = "틀렸다.",
  ui_story_5017_50171401_67_dialog_content = "10년 전 봉인의 땅에 갇힌 순간부터, 나는 이미 총통이 아니었다.",
  ui_story_5017_50171401_68_dialog_content = "이곳을 떠난 후 나는 나만을 위해 싸울 것이다.",
  ui_story_5017_50171401_69_dialog_content = "그들의 목숨이나 신뢰도... 이미 오래전에 내가 짊어질 짐이 아니게 되었다.",
  ui_story_5017_50171401_70_dialog_content = "스승님?!",
  ui_story_5017_50171401_71_dialog_content = "......",
  ui_story_5017_50171401_72_dialog_content = "그렇다 해도... 소생은 스승님을 따르겠습니다!",
  ui_story_5017_50171401_73_dialog_content = "...넌 아직도 내 말을 알아듣지 못한 것이냐.\n네가 날 따르는 것도 내게는 방해가 된다.",
  ui_story_5017_50171401_74_dialog_content = "무슨 일이 있어도 그렇게 할 생각이라면...",
  ui_story_5017_50171401_75_dialog_content = "그 검을 내게 휘둘러라.",
  ui_story_5017_50171401_76_dialog_content = "<color=#e8d9bb>치잉──</color>",
  ui_story_5017_50171401_77_dialog_content = "이 싸움을 면할 수 없다면...",
  ui_story_5017_50171401_78_dialog_content = "내 제자가 얼마나 발전했는지 어디 확인해 보도록 할까.",
  ui_story_5017_50171401_79_dialog_content = "흥, 이 대협객님도 그럴 생각이야!",
  ui_story_5017_50171401_80_dialog_content = "당신이 내 스승님으로 어울리는지 확인해야겠어!",
  ui_story_5017_50171401_81_dialog_content = "PlayerName, 우리도 도와주자!",
  ui_story_5017_50171401_82_dialog_content = "응, 당연하지.",
  ui_story_5017_50171501_1_dialog_content = "하아... 하...",
  ui_story_5017_50171501_2_dialog_content = "생각보다 훨씬 벅찬데...",
  ui_story_5017_50171501_3_dialog_content = "후... 후우...",
  ui_story_5017_50171501_4_dialog_content = "(무서운 힘이다... 우리... 이긴 건가?)",
  ui_story_5017_50171501_5_dialog_content = "......",
  ui_story_5017_50171501_6_dialog_content = "PlayerName... 정신 차려...",
  ui_story_5017_50171501_7_dialog_content = "두려워할 것 없다. 너흴 몰살할 만큼 내게 시간이 많지는 않으니 말이다.",
  ui_story_5017_50171501_8_dialog_content = "허나 너희는 확실히 상대할 만한 가치는 있었다.",
  ui_story_5017_50171501_9_dialog_content = "일시의 변덕으로 거두었던 제자들도 날 실망시키진 않는구나.",
  ui_story_5017_50171501_10_dialog_content = "또 만나게 될 것이다.",
  ui_story_5017_50171501_11_dialog_content = "...꼭 가시겠다는 것입니까, 스승님...",
  ui_story_5017_50171501_12_dialog_content = "난 너무나도 오랜 시간 동안 이날을 기다려 왔다.",
  ui_story_5017_50171501_13_dialog_content = "그거 잘됐군.",
  ui_story_5017_50171501_14_dialog_content = "그 말은 고스란히 그대에게 돌려주마, <color=#FFB400>나기</color>.",
  ui_story_5017_50171501_15_dialog_content = "(스승님의 이름을 함부로 부르다니...)",
  ui_story_5017_50171501_16_dialog_content = "입구의 오니 무사는 그대들의 소행인가?",
  ui_story_5017_50171501_17_dialog_content = "나기여, 패배를 맛보고 오랜 시간이 흘렀거늘,\n여전히 그리도 충동적이고 가소로운지고.",
  ui_story_5017_50171501_18_dialog_content = "이런 아이들의 도움을 빌어 몸을 피할 지경까지 떨어질 줄이야.",
  ui_story_5017_50171501_19_dialog_content = "후지쿠모... 때맞춰 잘 왔구나.",
  ui_story_5017_50171501_20_dialog_content = "그렇다면 이 무녀를 더는 괴롭힐 필요도 없겠지.",
  ui_story_5017_50171501_21_dialog_content = "하, 합하... 돌아오셨군요!",
  ui_story_5017_50171501_22_dialog_content = "하오나 어찌 합하 홀로...",
  ui_story_5017_50171501_23_dialog_content = "<color=#e8d9bb>짝──!</color>",
  ui_story_5017_50171501_24_dialog_content = "...?!",
  ui_story_5017_50171501_25_dialog_content = "내 허락 없이 멋대로 구름의 거울에 손을 댔으니, 이것은 가법에 따라 내린 벌이다.",
  ui_story_5017_50171501_26_dialog_content = "죄...죄송합니다...",
  ui_story_5017_50171501_27_dialog_content = "그리고 이것은 모든 운도의 백성을 대신해 내리는 벌이다.\n구름의 거울을 유용했으니 그에 걸맞은 대가를...",
  ui_story_5017_50171501_28_dialog_content = "흐아압!",
  ui_story_5017_50171501_29_dialog_content = "......",
  ui_story_5017_50171501_30_dialog_content = "나를 거스르면 어떤 대가를 치를지 아는 것이냐.",
  ui_story_5017_50171501_31_dialog_content = "네가 누구든 무슨 상관이야! 내 친구를 때렸으면 나쁜 놈이지!",
  ui_story_5017_50171501_32_dialog_content = "악당 주제에 운도 사람들을 대신해서 린네를 벌할 자격 따윈 없어!",
  ui_story_5017_50171501_33_dialog_content = "허허... 참으로 귀여운지고. 린네의 벗들이었단 말이냐.",
  ui_story_5017_50171501_34_dialog_content = "적어도 나기 공에 비하면...",
  ui_story_5017_50171501_35_dialog_content = "나야말로 운도를 통치하기에 합당한 몸이니라.",
  ui_story_5017_50171501_36_dialog_content = "너 따위와 잡담할 생각은 없다, 후지쿠모. 이제 곧 네 소행의 대가를 치르게 될 것이다.",
  ui_story_5017_50171501_37_dialog_content = "대가라...",
  ui_story_5017_50171501_38_dialog_content = "10년 전, 나는 이미 큰 대가를 치렀다.",
  ui_story_5017_50171501_39_dialog_content = "10년 전...?!",
  ui_story_5017_50171501_40_dialog_content = "네게 그런 말을 할 자격이 있을 성싶으냐!",
  ui_story_5017_50171501_41_dialog_content = "진정하게... 나기여, 그대는 10년 전의 싸움에 아직도 미련이 있는 것인가.",
  ui_story_5017_50171501_42_dialog_content = "그렇다면 그때의 상황을 미루어... 이번에도 내 먼저 출수하도록 하지!",
  ui_story_5017_50171501_43_dialog_content = "<color=#e8d9bb>휘익──</color>",
  ui_story_5017_50171501_44_dialog_content = "후우...",
  ui_story_5017_50171501_45_dialog_content = "이 정도 일에 스승님께서 친히 나서시게 할 순 없다.",
  ui_story_5017_50171501_46_dialog_content = "...재미있구나. 그대가 바로 나기의 제자인가.",
  ui_story_5017_50171501_47_dialog_content = "일이 이제는 이 지경이 되었는가.\n이런 젊은이들의 손을 빌어 우리 대의 은원을 풀어야 한다니...",
  ui_story_5017_50171501_48_dialog_content = "린네, 놈들을 죽여라.",
  ui_story_5017_50171501_49_dialog_content = "......",
  ui_story_5017_50171501_50_dialog_content = "어찌 그러느냐, 네게는 수월한 일이 아니더냐.",
  ui_story_5017_50171501_51_dialog_content = "거울의 힘은 느껴 보았느냐?",
  ui_story_5017_50171501_52_dialog_content = "지금의 네 힘으로는 그것을 온전히 부릴 수는 없으나...",
  ui_story_5017_50171501_53_dialog_content = "다루는 것을 허락하마.",
  ui_story_5017_50171501_54_dialog_content = "네 눈앞에 있는 것은 오랫동안 봉인돼 있던 괴물,\n운도를 혼탁하게 만드는 부정 그 자체다.",
  ui_story_5017_50171501_55_dialog_content = "...어서 죽이는 것이다. 해보고 싶지 않은 것이냐?",
  ui_story_5017_50171501_56_dialog_content = "......",
  ui_story_5017_50171501_57_dialog_content = "(...린네?!)",
  ui_story_5017_50171501_58_dialog_content = "...아니요.",
  ui_story_5017_50171501_59_dialog_content = "합하, 부디 용서해 주십시오. 합하의 명은 따를 수 없사옵니다.",
  ui_story_5017_50171501_60_dialog_content = "흐음?!",
  ui_story_5017_50171501_61_dialog_content = "저는 제 벗들을 해칠 수 없사옵니다.",
  ui_story_5017_50171501_62_dialog_content = "게다가 합하께 여쭙고 싶은 것이 있사옵니다...",
  ui_story_5017_50171501_63_dialog_content = "부디 말씀해 주십시오. 구름의 거울은 대체 무엇을 위한 것인지요.",
  ui_story_5017_50171501_64_dialog_content = "합하께서는... 어찌하여 오니를 조종하실 수 있는지요.",
  ui_story_5017_50171501_65_dialog_content = "!!!",
  ui_story_5017_50171501_66_dialog_content = "린네, 나를 실망시키는구나.",
  ui_story_5017_50171501_67_dialog_content = "저들을 모두 처리하고 나면, 너도 더는 「춘일제」에 관여하지 않아도 된다.",
  ui_story_5017_50171501_68_dialog_content = "합하, 기어코 그리 하시겠다면...",
  ui_story_5017_50171501_69_dialog_content = "저도 다시 한번 합하의 뜻을 거스르는 수밖에 없사옵니다.",
  ui_story_5017_50171501_70_dialog_content = "......",
  ui_story_5017_50171501_71_dialog_content = "좋다, 린네.",
  ui_story_5017_50171501_72_dialog_content = "네 욕망과 야심은 역시 구름의 거울과 잘 어울리는구나.",
  ui_story_5017_50171501_73_dialog_content = "허나 유감이로다...",
  ui_story_5017_50171501_74_dialog_content = "네 힘으로는 나를 거역할 수 없느니라!",
  ui_story_5017_50171501_75_dialog_content = "으윽...",
  ui_story_5017_50171501_76_dialog_content = "린네!",
  ui_story_5017_50171501_77_dialog_content = "나쁜 자식! 어떻게 자기 양녀한테 그럴 수가 있어?!",
  ui_story_5017_50171501_78_dialog_content = "그대들이 멋대로 구름의 거울에 손을 댄 것도 용서해 주었거늘...",
  ui_story_5017_50171501_79_dialog_content = "거듭 내 인내를 시험하겠다는 것이냐.",
  ui_story_5017_50171501_80_dialog_content = "아무래도 강부성의 법도를 내 친히 가르칠 필요가 있겠구나.",
  ui_story_5017_50171601_1_dialog_content = "쿨럭, 쿨럭...",
  ui_story_5017_50171601_2_dialog_content = "린네! 괜찮아?!",
  ui_story_5017_50171601_3_dialog_content = "저는 괜찮습니다. 구름의 거울은...",
  ui_story_5017_50171601_4_dialog_content = "<color=#e8d9bb>철커덩──!</color>",
  ui_story_5017_50171601_5_dialog_content = "하, 참으로 경망스러운 아이가 아니더냐...",
  ui_story_5017_50171601_6_dialog_content = "물건을 떨어트리는 것도 모자라서, 내가 주워 주어야 하겠느냐.",
  ui_story_5017_50171601_7_dialog_content = "말했을 터, 너는 아직 구름의 거울을 완전히 다룰 수 없느니라.",
  ui_story_5017_50171601_8_dialog_content = "거울의 힘이 네게 끼치는 반동은 괴로울 것이다...",
  ui_story_5017_50171601_9_dialog_content = "허나 문제가 되지는 않겠지.",
  ui_story_5017_50171601_10_dialog_content = "이는 구름의 거울이 너를 받아들이고 있다는 증좌이니 말이다.",
  ui_story_5017_50171601_11_dialog_content = "그러면... 당신은 처음부터... 이 거울의 진정한 힘과 쓰임새를 알고 계셨군요!",
  ui_story_5017_50171601_12_dialog_content = "...대체... 어째서 이런 일을 하신 겁니까?!",
  ui_story_5017_50171601_13_dialog_content = "윤회를 거친 영혼만이 죽음의 고통을 아는 법이다.",
  ui_story_5017_50171601_14_dialog_content = "...비열한 놈.",
  ui_story_5017_50171601_15_dialog_content = "여봐라, 무녀님을 「뫼셔」라.",
  ui_story_5017_50171601_16_dialog_content = "예!",
  ui_story_5017_50171601_17_dialog_content = "마음대로 될 줄 알고!",
  ui_story_5017_50171601_18_dialog_content = "참으로 볼만하구나.",
  ui_story_5017_50171601_19_dialog_content = "그때도 그렇게 그 여자를 이용했나?",
  ui_story_5017_50171601_20_dialog_content = "무녀여, 넌 그저 도구로 선택되었을 뿐이다.",
  ui_story_5017_50171601_21_dialog_content = "넌 전대 무녀가 어떤 끝을 맞았는지 알고 있나?",
  ui_story_5017_50171601_22_dialog_content = "닥쳐라!",
  ui_story_5017_50171601_23_dialog_content = "여봐라, <size=45>저 여자를 잡아라!</size>",
  ui_story_5017_50171601_24_dialog_content = "하하하! 후지쿠모, 겨우 이 정도로 조급해졌나?",
  ui_story_5017_50171601_25_dialog_content = "10년이나 지났는데 전혀 성장하지 않았어. 내 두 제자만도 못하잖아.",
  ui_story_5017_50171601_26_dialog_content = "하아...",
  ui_story_5017_50171601_27_dialog_content = "벚꽃을 못 본 지도 너무 오래된 것 같구나.",
  ui_story_5017_50171601_28_dialog_content = "여기서 너무 오랫동안 잠들어 있었어. 이제 몸을 좀 풀 때가 된 모양이다.",
  ui_story_5017_50171601_29_dialog_content = "배웅은 됐소이다, 쇼군 나리.",
  ui_story_5017_50171601_30_dialog_content = "조만간 맞붙게 되겠지. 허나 지금은 아니다.",
  ui_story_5017_50171601_31_dialog_content = "내가 준비할 <color=#e8d9bb>선물</color>을 기대하고 있으라고.",
  ui_story_5017_50171601_32_dialog_content = "스승님?",
  ui_story_5017_50171601_33_dialog_content = "「척귀능인」은 잠시 거두어 가마.",
  ui_story_5017_50171601_34_dialog_content = "제자들이여, 인연이 닿으면 다시 보자고.",
  ui_story_5017_50171601_35_dialog_content = "스승님!",
  ui_story_5017_50171601_36_dialog_content = "아메모리, 어쩌려고 그래?!",
  ui_story_5017_50171601_37_dialog_content = "우리도 가세!",
  ui_story_5017_50171601_38_dialog_content = "일단 진정해, 아메모리...",
  ui_story_5017_50171601_39_dialog_content = "뭘 망설이는 것이오?",
  ui_story_5017_50171601_40_dialog_content = "린네가 다쳤어. 난 린네를 도울 거야. 두고 갈 순 없어!",
  ui_story_5017_50171601_41_dialog_content = "...그렇다면 그대는 여기 남으시오.",
  ui_story_5017_50171601_42_dialog_content = "아메모리!",
  ui_story_5017_50171601_43_dialog_content = "그대들이 갈 곳은 없느니라. 그 누구도 가지 못한다.",
  ui_story_5017_50171601_44_dialog_content = "잡아라.",
  ui_story_5017_50171601_45_dialog_content = "예!",
  ui_story_5017_50171601_46_dialog_content = "PlayerName, 린네 데리고 먼저 도망쳐. 나랑 요우가 뒤를 막을게.",
  ui_story_5017_50171601_47_dialog_content = "성문을 봉쇄하라. 린네 외에는 살려둘 필요 없다!",
  ui_story_5017_50171601_48_dialog_content = "기세── 우락송림!",
  ui_story_5017_50171601_49_dialog_content = "합하의 명이다, 수배령을 전하라! 역적을 잡는 자에게는 상을 내릴 것이다!",
  ui_story_5017_50171601_50_dialog_content = "이쪽에는 없습니다!",
  ui_story_5017_50171601_51_dialog_content = "이쪽도 없었습니다!",
  ui_story_5017_50171601_52_dialog_content = "아직 성을 벗어나진 못했을 것이다. 샅샅이 뒤져라!",
  ui_story_5017_50171601_53_dialog_content = "방 하나도 남기지 말고 찾아라!",
  ui_story_5017_50171601_54_dialog_content = "나머지는 나를 따라 사카이 거리로 간다!",
  ui_story_5017_50171601_55_dialog_content = "예!",
  ui_story_5017_50171601_56_dialog_content = "......",
  ui_story_5017_50171601_57_dialog_content = "이제 어떻게 하지?",
  ui_story_5017_50171601_58_option_content = "정면으로 돌파하자.",
  ui_story_5017_50171601_59_dialog_content = "안 돼, 너무 위험해!",
  ui_story_5017_50171601_60_dialog_content = "차라리... 내가 놈들을 유인할 테니까, 너희들은 어떻게든 도망쳐.",
  ui_story_5017_50171601_61_option_content = "일단 여기 숨어 있자.",
  ui_story_5017_50171601_62_dialog_content = "결국엔 여기도 찾아내고 말 거야.",
  ui_story_5017_50171601_63_dialog_content = "이대로 숨어있는 건 상책이 아냐. 여기서 나가야 해.",
  ui_story_5017_50171601_64_dialog_content = "내가 놈들을 유인할 테니까, 너희들은 어떻게든 도망쳐.",
  ui_story_5017_50171601_65_dialog_content = "안 돼, 너무 위험해!",
  ui_story_5017_50171601_66_dialog_content = "린네는 상처가 깊어. 반드시 데리고 나가야 해.",
  ui_story_5017_50171601_67_dialog_content = "지금 아직 싸울 수 있는 건 나밖에 없잖아.",
  ui_story_5017_50171601_68_dialog_content = "어머... 마치 제가 죽어가고 있는 것처럼 말씀하시는군요.",
  ui_story_5017_50171601_69_dialog_content = "린네, 정신이 들었구나. 괜찮아?",
  ui_story_5017_50171601_70_dialog_content = "무탈합니다.",
  ui_story_5017_50171601_71_dialog_content = "한순간 구름의 거울이 제 힘을 먹고, 나아가 제 목숨을 노리는 느낌을 받았습니다.",
  ui_story_5017_50171601_72_dialog_content = "강부성 안에 어째서 그런 무기가 있는 것일까요... 저는 도무지 모르겠습니다.",
  ui_story_5017_50171601_73_dialog_content = "그분 말이 옳았습니다. 저는 아직 거울을 잘 다룰 수 없습니다.\n역시 건드리지 말았어야 하는 것이겠지요.",
  ui_story_5017_50171601_74_dialog_content = "허나 어떻게 해서든, 저는 반드시 그것을 부술 것입니다.",
  ui_story_5017_50171601_75_dialog_content = "적어도 지금은 아니야. 우선 여기서 도망치자. 대책은 그다음에 세우는 거야.",
  ui_story_5017_50171601_76_dialog_content = "제가 출구를 알고 있습니다.",
  ui_story_5017_50171601_77_dialog_content = "PlayerName 님, 이제부터 제가 드리는 말씀을 기억해 주십시오.",
  ui_story_5017_50171601_78_dialog_content = "이제부터 요우는 저를 인질로 잡고 이곳을 나가세요.",
  ui_story_5017_50171601_79_dialog_content = "안 돼!",
  ui_story_5017_50171601_80_dialog_content = "제 말 들으세요. 요우는 착한 아이잖아요? 저는 괜찮습니다.",
  ui_story_5017_50171601_81_dialog_content = "린네...",
  ui_story_5017_50171601_82_dialog_content = "저를 인질로 잡으면 쇼군이 없는 한 가신들은 섣불리 손을 대지 못할 것입니다.\n그 틈에 여러분은 도망치십시오.",
  ui_story_5017_50171601_83_dialog_content = "복도 끝 오른쪽에 정원으로 이어지는 좁은 통로가 있습니다.",
  ui_story_5017_50171601_84_dialog_content = "정원에 있는 폭포 소리가 여러분의 기척을 가려줄 것입니다.",
  ui_story_5017_50171601_85_dialog_content = "반드시 대나무숲을 빠져나가십시오. 무슨 일이 있어도 멈춰선 안 됩니다.\n정원을 둘러싼 담이 보이면, 뛰어넘어서 밖으로 나가세요.",
  ui_story_5017_50171601_86_dialog_content = "산을 내려가면 사카이 거리에 가서 모모와 안즈를 찾아가세요.\n제가 보냈다고 전하면 될 것입니다.",
  ui_story_5017_50171601_87_dialog_content = "<color=#FFB400>유시의 북이 울릴 무렵</color>, 저도 여러분과 합류하겠습니다.",
  ui_story_5017_50171601_88_dialog_content = "하지만...",
  ui_story_5017_50171601_89_dialog_content = "안심하십시오. 저는 아직 그분에게 이용 가치가 있으니까요.\n저를 해치진 못할 것입니다.",
  ui_story_5017_50171601_90_dialog_content = "자, 갑시다.",
  ui_story_5017_50171601_91_dialog_content = "<color=#e8d9bb>덜커덕──</color>",
  ui_story_5017_50171601_92_dialog_content = "저는 여기 있습니다.",
  ui_story_5017_50171601_93_dialog_content = "린네 님?! 여봐라! 역적이 여기 있다!",
  ui_story_5017_50171601_94_dialog_content = "무엄하다! 감히 린네 님을 인질로 잡다니!",
  ui_story_5017_50171601_95_dialog_content = "어서 포위해라!",
  ui_story_5017_50171601_96_dialog_content = "후후, 어디 그만한 실력이 있나 볼까?",
  ui_story_5017_50171601_97_dialog_content = "기세── 우락송림!",
  ui_story_5017_50171601_98_dialog_content = "<size=30>PlayerName, 린네 데리고 도망쳐!</size>",
  ui_story_5017_50171601_99_dialog_content = "요우?! 하지만...",
  ui_story_5017_50171601_100_dialog_content = "역적의 우두머리를 잡아라!",
  ui_story_5017_50171601_101_dialog_content = "하! 다 덤비라고!",
  ui_story_5017_50171601_102_dialog_content = "<size=30>얼른, PlayerName. 지금이야!</size>",
  ui_story_5017_50171601_103_dialog_content = "<size=30>더는 린네를 저 악당들의 손에 넘겨줄 순 없어!</size>",
  ui_story_5017_50171601_104_dialog_content = "어딜 도망치려고!",
  ui_story_5017_50171601_105_dialog_content = "하아── 천인합일, 파죽지세!",
  ui_story_5017_50171601_106_dialog_content = "?!",
  ui_story_5017_50171601_107_dialog_content = "요, 요우?!",
  ui_story_5017_50171601_108_dialog_content = "PlayerName, 이쪽!",
  ui_story_5017_50171601_109_dialog_content = "이게 바로 대협객의 인질 계획이라구!",
  ui_story_5017_50171601_110_dialog_content = "빨리 도망쳐, 린네. 내가 잡으러 가기 전에!",
  ui_story_5017_50171601_111_dialog_content = "...!",
  ui_story_5017_50171601_112_dialog_content = "요우...",
  ui_story_5017_50171601_113_dialog_content = "린네, 요우를 믿자!",
  ui_story_5017_50171601_114_dialog_content = "지금은 이게 모두를 지킬 유일한 방법이야...",
  ui_story_5017_50171601_115_dialog_content = "저 무사들은 요우의 상대가 못 돼. 그건 나보다 네가 더 잘 알잖아!",
  ui_story_5017_50171601_116_dialog_content = "...알겠습니다.",
  ui_story_5017_50171601_117_dialog_content = "감사합니다, PlayerName 님.",
  ui_story_5017_50171601_118_dialog_content = "응? 나?",
  ui_story_5017_50171601_119_dialog_content = "봉인의 땅이 열리기 전에 제게 하셨던 말씀들...",
  ui_story_5017_50171601_120_dialog_content = "물론 지금까지 동행하면서 있었던 일도... 모두 감사합니다.",
  ui_story_5017_50171601_121_dialog_content = "그 모든 것을... 여러분께 감사하고 싶습니다...",
  ui_story_5017_50171601_122_dialog_content = "아...알겠어! 근데... 지금은 그럴 때가 아냐!",
  ui_story_5017_50171601_123_dialog_content = "후훗, 그것도 그렇네요.",
  ui_story_5017_50171601_124_dialog_content = "<color=#FFB400>쇼군</color>이 무사들을 이끌고, 저흴 추격해 오기 전에...",
  ui_story_5017_50171601_125_dialog_content = "먼저 움직이죠!",
  ui_story_5017_50171601_126_dialog_content = "PlayerName 님, 바이스 님, 운수각의 계단을 따라 내려가면 본성을 나가는 뒷문이 있습니다.",
  ui_story_5017_50171601_127_dialog_content = "가시지요. 사카이 거리로 가서 부정함을 없애는 것입니다!",
  ui_story_5017_50171601_128_dialog_content = "응!",
  ui_story_5017_50171601_129_dialog_content = "(아아... 벌써 해가 뜨기 시작합니다...)",
  ui_story_5017_50171601_130_dialog_content = "(지금까지와는 다른 춘일제가 곧 강부성에서 그 막을 올리려 합니다...)",
  ui_story_5017_50171601_131_dialog_content = "(이매망량의 횡행이 혼란을 초래하고 있지만, 그래도 저는 알 수 있습니다...)",
  ui_story_5017_50171601_132_dialog_content = "(오랜 시간 준비된 계략이 지금 이 순간 강부성에서 실현되고 있습니다...)",
  ui_story_5017_50171601_133_dialog_content = "(그 전례 없는 새로움은 사람을 불안하게 만들고... 저조차 답을 예측할 수 없습니다...)",
  ui_story_5017_50171601_134_dialog_content = "(...허나 무슨 일이 있더라도, 제 무지로 인한 죄업을 모호하게 청산할 수는 없습니다...)",
  ui_story_5017_50171601_135_dialog_content = "(지금 제가 유일하게 할 수 있는 것은... 무고한 백성들의 안녕을 위해 악귀를 물리치는 일...)",
  ui_story_5017_50171601_136_dialog_content = "(오직 그것만이... 제가 강부성에 보답하는 길이겠지요...)",
  ui_story_5017_50171601_137_dialog_content = "<color=#e8d9bb>다음 편에 계속...</color>"
}
return config
